_RULESPEC_RESOLUTION_CACHE: ContextVar[_RuleSpecResolutionCache | None] = ContextVar(
    "axiom_rulespec_resolution_cache",
    default=None,
)


@contextlib.contextmanager
def _rulespec_resolution_cache_scope() -> Iterator[_RuleSpecResolutionCache]:
    """Bound RuleSpec path and identity caches to one explicit operation."""

    current = _RULESPEC_RESOLUTION_CACHE.get()
    if current is not None:
        yield current
        return
    cache = _RuleSpecResolutionCache()
    with _rulespec_routing_cache_scope():
        token = _RULESPEC_RESOLUTION_CACHE.set(cache)
        try:
            yield cache
        finally:
            _RULESPEC_RESOLUTION_CACHE.reset(token)


@contextlib.contextmanager
def _authoritative_corpus_scope(
    release: LocalCorpusRelease,
) -> Iterator[LocalCorpusRelease]:
    """Restrict corpus lookups to one named local release for the whole scope."""

    if not isinstance(release, LocalCorpusRelease):
        raise TypeError("release must be a validated LocalCorpusRelease")
    token = _AUTHORITATIVE_CORPUS_RELEASE.set(release)
    try:
        yield release
    finally:
        _AUTHORITATIVE_CORPUS_RELEASE.reset(token)


@contextlib.contextmanager
def _authoritative_rulespec_dependency_scope(
    roots: Iterable[Path],
) -> Iterator[tuple[Path, ...]]:
    """Bind the exact caller-authorized RuleSpec dependency checkouts."""

    normalized = _normalize_rulespec_dependency_roots(roots)
    token = _AUTHORITATIVE_RULESPEC_DEPENDENCY_ROOTS.set(normalized)
    try:
        yield normalized
    finally:
        _AUTHORITATIVE_RULESPEC_DEPENDENCY_ROOTS.reset(token)


def _without_sensitive_environment(env: Mapping[str, str]) -> dict[str, str]:
    """Remove credentials before invoking deterministic validator subprocesses."""

    return {
        name: value
        for name, value in env.items()
        if not any(marker in name.upper() for marker in _SENSITIVE_ENV_NAME_MARKERS)
    }


class _UniqueKeySafeLoader(yaml.SafeLoader):
    """PyYAML safe loader that rejects duplicate mapping keys."""


def _construct_mapping_without_duplicate_keys(
    loader: yaml.SafeLoader,
    node: yaml.nodes.MappingNode,
    deep: bool = False,
) -> dict[Any, Any]:
    loader.flatten_mapping(node)
    seen: set[Any] = set()
    for key_node, _value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        try:
            duplicate = key in seen
        except TypeError:
            key = repr(key)
            duplicate = key in seen
        if duplicate:
            raise yaml.constructor.ConstructorError(
                "while constructing a mapping",
                node.start_mark,
                f"found duplicate key {key!r}",
                key_node.start_mark,
            )
        seen.add(key)
    return loader.construct_mapping(node, deep=deep)


_UniqueKeySafeLoader.add_constructor(
    yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,
    _construct_mapping_without_duplicate_keys,
)


def _safe_load_unique_keys(content: str) -> Any:
    """Load YAML with duplicate mapping keys treated as parse errors."""
    return yaml.load(content, Loader=_UniqueKeySafeLoader)


def _yaml_parse_issue(path: Path, exc: BaseException) -> str:
    return f"{path.name} YAML parse failed: {exc}"


def run_claude_code(
    prompt: str,
    model: str = REVIEWER_CLI_MODEL,
    timeout: int = 120,
    cwd: Optional[Path] = None,
) -> tuple[str, int]:
    """
    Run reviewer CLI as subprocess.

    Prefer Claude Code CLI when available, but fall back to Codex CLI on
    machines where Claude is not installed. This keeps reviewer-based evals
    working in local Codex-only environments.

    Returns:
        Tuple of (output text, return code)
    """
    reviewer_cli_preference = os.getenv("AXIOM_ENCODE_REVIEWER_CLI", "").strip().lower()
    if reviewer_cli_preference == "codex":
        return _run_codex_reviewer_cli(prompt, timeout=timeout, cwd=cwd)

    cmd = [
        "claude",
        "--print",
        "--permission-mode",
        "dontAsk",
        "--safe-mode",
        "--no-session-persistence",
        "--disable-slash-commands",
        "--no-chrome",
        "--strict-mcp-config",
        "--mcp-config",
        '{"mcpServers": {}}',
        "--tools",
        "",
        "--allowed-tools",
        "",
        "--model",
        model,
        "-p",
        prompt,
    ]

    try:
        idle_timeout_env = os.getenv(
            "AXIOM_ENCODE_REVIEWER_CLAUDE_IDLE_TIMEOUT_SECONDS"
        )
        idle_timeout = timeout
        if idle_timeout_env is not None:
            idle_timeout = min(timeout, max(0, int(idle_timeout_env)))
        result = _run_subprocess_with_idle_timeout(
            cmd,
            timeout=timeout,
            idle_timeout=idle_timeout,
            cwd=cwd,
            env=scrub_attestation_signing_keys(),
        )
        return result.output, result.returncode
    except subprocess.TimeoutExpired as exc:
        return f"Timeout after {exc.timeout}s", 1
    except FileNotFoundError:
        return _run_codex_reviewer_cli(prompt, timeout=timeout, cwd=cwd)
    except Exception as e:
        return f"Error: {e}", 1


def _run_codex_reviewer_cli(
    prompt: str,
    timeout: int = 120,
    cwd: Optional[Path] = None,
) -> tuple[str, int]:
    """Run reviewer prompts through Codex CLI and return assistant text."""
    cmd = [
        resolve_codex_cli(),
        "exec",
        "--json",
        "--skip-git-repo-check",
        "--sandbox",
        "read-only",
        "--model",
        os.environ.get("AXIOM_ENCODE_REVIEWER_CODEX_MODEL", DEFAULT_OPENAI_MODEL),
    ]
    if cwd is not None:
        cmd.extend(["-C", str(cwd)])
    cmd.append(prompt)

    try:
        idle_timeout = min(
            timeout,
            max(
                0,
                int(
                    os.getenv(
                        "AXIOM_ENCODE_REVIEWER_CODEX_IDLE_TIMEOUT_SECONDS",
                        "45",
                    )
                ),
            ),
        )
        result = _run_subprocess_with_idle_timeout(
            cmd,
            timeout=timeout,
            idle_timeout=idle_timeout,
            cwd=cwd,
        )
        return _extract_codex_text_output(result.output), result.returncode
    except subprocess.TimeoutExpired:
        return f"Timeout after {timeout}s", 1
    except FileNotFoundError:
        return "Reviewer CLIs not found (missing claude and codex)", 1
    except Exception as e:
        return f"Error: {e}", 1


@dataclass
class _SubprocessRunResult:
    """Captured subprocess output plus exit status."""

    output: str
    returncode: int


def _sha256_text(text: str | None) -> str | None:
    """Return a stable digest for prompt text."""
    if text is None:
        return None
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _run_subprocess_with_idle_timeout(
    cmd: list[str],
    *,
    timeout: int,
    idle_timeout: int,
    cwd: Optional[Path] = None,
    env: Mapping[str, str] | None = None,
    poll_interval: float = 0.5,
) -> _SubprocessRunResult:
    """Run a subprocess, aborting if it stops emitting output for too long."""
    capture_root: Path | None = None
    try:
        with tempfile.TemporaryDirectory(
            prefix="axiom-validator-subprocess-",
            ignore_cleanup_errors=True,
        ) as capture_dir:
            capture_root = Path(capture_dir)
            stdout_path = capture_root / "stdout.log"
            stderr_path = capture_root / "stderr.log"
            with (
                stdout_path.open("w+") as stdout_file,
                stderr_path.open("w+") as stderr_file,
            ):
                process = subprocess.Popen(
                    cmd,
                    stdin=subprocess.DEVNULL,
                    stdout=stdout_file,
                    stderr=stderr_file,
                    text=True,
                    cwd=cwd,
                    env=(
                        scrub_attestation_signing_keys()
                        if env is None
                        else scrub_attestation_signing_keys(env)
                    ),
                )

            start = time.time()
            last_activity = start
            last_snapshot: tuple[tuple[int, int, int], tuple[int, int, int]] | None = (
                None
            )

            def _snapshot() -> tuple[tuple[int, int, int], tuple[int, int, int]]:
                values: list[tuple[int, int, int]] = []
                for path in (stdout_path, stderr_path):
                    try:
                        stat = path.stat()
                    except OSError:
                        values.append((0, 0, 0))
                        continue
                    values.append((1, stat.st_size, stat.st_mtime_ns))
                return values[0], values[1]

            while True:
                if process.poll() is not None:
                    break

                now = time.time()
                if now - start > timeout:
                    process.kill()
                    process.wait()
                    raise subprocess.TimeoutExpired(cmd, timeout)

                snapshot = _snapshot()
                if snapshot != last_snapshot:
                    last_snapshot = snapshot
                    last_activity = now
                elif idle_timeout >= 0 and now - last_activity >= idle_timeout:
                    process.kill()
                    process.wait()
                    raise subprocess.TimeoutExpired(cmd, idle_timeout)

                time.sleep(poll_interval)

            output = stdout_path.read_text() + stderr_path.read_text()
            normalized_output = _normalize_validation_staging_text(
                output,
                capture_root,
                placeholder=_VALIDATOR_SUBPROCESS_CAPTURE_PLACEHOLDER,
            )
            return _SubprocessRunResult(
                output=normalized_output,
                returncode=process.returncode or 0,
            )
    except subprocess.TimeoutExpired:
        raise
    except Exception as exc:
        if capture_root is None:
            raise RuntimeError(
                f"Validator subprocess capture setup failed: {type(exc).__name__}"
            ) from exc
        normalized_error = _normalize_validation_staging_text(
            str(exc),
            capture_root,
            placeholder=_VALIDATOR_SUBPROCESS_CAPTURE_PLACEHOLDER,
        )
        if normalized_error == str(exc):
            raise
        raise RuntimeError(normalized_error) from exc


def _extract_codex_text_output(output: str) -> str:
    """Return the concatenated assistant text from a Codex JSONL stream."""
    assistant_messages: list[str] = []
    last_error: str | None = None

    for line in output.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError:
            continue
        if not isinstance(payload, dict):
            continue
        payload_type = payload.get("type")
        if payload_type == "item.completed":
            item = payload.get("item") or {}
            if item.get("type") == "agent_message" and item.get("text"):
                assistant_messages.append(item["text"])
        elif payload_type == "error":
            last_error = payload.get("message") or "codex exec error"

    return "\n".join(assistant_messages).strip() or last_error or output


_REVIEW_JSON_KEYS = {
    "score",
    "passed",
    "issues",
    "blocking_issues",
    "non_blocking_issues",
    "reasoning",
}


def _looks_like_review_json(data: dict[str, Any]) -> bool:
    """Return true for the reviewer payload, not surrounding CLI metadata."""
    return bool(_REVIEW_JSON_KEYS.intersection(data))


def _strip_trailing_json_commas(text: str) -> str:
    """Remove common model-emitted trailing commas before JSON closers."""
    return re.sub(r",(\s*[}\]])", r"\1", text)


def _decode_json_object_candidate(text: str) -> dict[str, Any] | None:
    """Decode a JSON object candidate with strict and reviewer-friendly modes."""
    cleaned = text.strip().replace("\u3000", " ")
    if not cleaned:
        return None

    variants = [cleaned]
    without_trailing_commas = _strip_trailing_json_commas(cleaned)
    if without_trailing_commas != cleaned:
        variants.append(without_trailing_commas)

    for variant in variants:
        for strict in (True, False):
            with contextlib.suppress(json.JSONDecodeError):
                data = json.loads(variant, strict=strict)
                if isinstance(data, dict):
                    return data

        for strict in (True, False):
            decoder = json.JSONDecoder(strict=strict)
            with contextlib.suppress(json.JSONDecodeError):
                data, _ = decoder.raw_decode(variant)
                if isinstance(data, dict):
                    return data

    return None


def _iter_balanced_json_object_snippets(output: str) -> list[str]:
    """Return brace-balanced object snippets for repair-oriented parsing."""
    snippets: list[str] = []
    for start, char in enumerate(output):
        if char != "{":
            continue

        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(output)):
            current = output[index]
            if escaped:
                escaped = False
                continue
            if current == "\\":
                escaped = True
                continue
            if current == '"':
                in_string = not in_string
                continue
            if in_string:
                continue
            if current == "{":
                depth += 1
            elif current == "}":
                depth -= 1
                if depth == 0:
                    snippets.append(output[start : index + 1])
                    break
    return snippets


def _iter_terminal_object_brace_repairs(output: str) -> list[str]:
    """Repair reviewer output that is missing only the final top-level brace."""
    snippets: list[str] = []
    for start, char in enumerate(output):
        if char != "{":
            continue

        stack: list[str] = []
        in_string = False
        escaped = False
        balanced_before_end = False
        invalid = False
        for index in range(start, len(output)):
            current = output[index]
            if escaped:
                escaped = False
                continue
            if current == "\\":
                escaped = True
                continue
            if current == '"':
                in_string = not in_string
                continue
            if in_string:
                continue
            if current == "{":
                stack.append("}")
            elif current == "[":
                stack.append("]")
            elif current in "}]":
                if not stack or stack[-1] != current:
                    invalid = True
                    break
                stack.pop()
                if not stack:
                    balanced_before_end = True
                    break

        if invalid or balanced_before_end or in_string or stack != ["}"]:
            continue

        candidate = output[start:].strip()
        candidate = re.sub(r"\s*```\s*$", "", candidate).strip()
        snippets.append(candidate + "}")

    return snippets


def _extract_json_object(output: str) -> dict[str, Any]:
    """Extract the reviewer JSON object from model output."""
    candidates: list[dict[str, Any]] = []
    fenced_blocks = re.findall(
        r"```(?:json)?\s*(.*?)```",
        output,
        flags=re.DOTALL | re.IGNORECASE,
    )
    for block in fenced_blocks:
        data = _decode_json_object_candidate(block)
        if data is not None:
            candidates.append(data)

    for snippet in _iter_balanced_json_object_snippets(output):
        data = _decode_json_object_candidate(snippet)
        if data is not None:
            candidates.append(data)

    for snippet in _iter_terminal_object_brace_repairs(output):
        data = _decode_json_object_candidate(snippet)
        if data is not None:
            candidates.append(data)

    for data in candidates:
        if _looks_like_review_json(data):
            return data
    if candidates:
        return candidates[0]

    raise ValueError("No JSON found in output")


_REVIEW_JSON_FORMAT = """
Output your review as JSON:
{
  "score": <float 1-10>,
  "passed": <boolean>,
  "issues": ["issue1", "issue2"],
  "reasoning": "<brief explanation>"
}
"""

_GENERALIST_REVIEW_JSON_FORMAT = """
Output your review as JSON:
{
  "score": <float 1-10>,
  "passed": <boolean>,
  "blocking_issues": ["issue1", "issue2"],
  "non_blocking_issues": ["issue3", "issue4"],
  "reasoning": "<brief explanation>"
}

Use `passed: true` when the encoding is safe to promote even if there are minor cleanup notes.
Only place substantive statutory-fidelity defects in `blocking_issues`.
Place minor naming cleanups, dead code, test naming nits, or possible-but-uncertain import suggestions in `non_blocking_issues`.
"""

