def _numeric_profile_for_citation_path(citation_path: str | None) -> str:
    """Select a locale only from a canonical evidence citation path."""
    if not isinstance(citation_path, str) or not citation_path:
        return "legacy"
    try:
        canonical = require_canonical_corpus_citation_path(citation_path)
    except (InvalidCorpusCitationError, TypeError, ValueError):
        return "legacy"
    if canonical.startswith("de/"):
        return "de-DE"
    if canonical.startswith("dk/"):
        return "da-DK"
    return "legacy"


def _locale_sign_is_unary(
    text: str,
    sign_index: int,
    *,
    profile: str,
    boundaries: _NumericContextBoundaries | None = None,
) -> bool:
    lower_bound = boundaries.lower_bound(sign_index) if boundaries is not None else 0
    if boundaries is not None:
        wall_index = bisect_right(boundaries.starts, sign_index) - 1
        if wall_index >= 0 and boundaries.spans[wall_index][1] >= sign_index:
            return False
    prefix_index = sign_index - 1
    if profile == "da-DK" and text[sign_index] in "-\u2013\u2212":
        while (
            prefix_index >= lower_bound
            and text[prefix_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
        ):
            prefix_index -= 1
    else:
        while prefix_index >= lower_bound and (
            text[prefix_index] in _LOCALE_NUMERIC_GROUPING_SPACES
            or (
                profile == "da-DK"
                and text[prefix_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
            )
        ):
            prefix_index -= 1
    if prefix_index < lower_bound:
        return lower_bound == 0
    prefix = text[prefix_index]
    return (
        prefix.isspace()
        or prefix in _LOCALE_UNARY_PREFIXES
        or prefix in _LOCALE_UNARY_SIGNS
    )


def _locale_glued_sentence_marker_end(
    text: str,
    dot_index: int,
    *,
    profile: str,
) -> int | None:
    """Return the end of a juris ``.3Die``-style marker prefix, if present."""
    if dot_index >= len(text) or text[dot_index] != ".":
        return None

    marker_end = dot_index + 1
    digit_count = 0
    while digit_count < 2:
        if profile == "da-DK":
            marker_end = _next_numeric_joiner_end(text, marker_end)
        if marker_end >= len(text) or not text[marker_end].isdecimal():
            break
        marker_end += 1
        digit_count += 1
    if profile == "da-DK":
        marker_end = _next_numeric_joiner_end(text, marker_end)

    if (
        digit_count > 0
        and marker_end < len(text)
        and unicodedata.category(text[marker_end]) == "Lu"
    ):
        return marker_end
    return None


def _locale_numeric_envelope_grammar_accepts(
    character: str,
    *,
    profile: str,
    grouping_characters: str,
) -> bool:
    """Define the complete character grammar shared by scan and continuation."""
    return bool(
        character.isdigit()
        or character in ".,Ee"
        or character in grouping_characters
        or character in _LOCALE_UNARY_SIGNS
        or (
            profile == "da-DK" and character in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
        )
    )


def _next_numeric_joiner_end(text: str, index: int) -> int:
    """Return the first index after a contiguous Danish numeric-joiner run."""
    while index < len(text) and text[index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS:
        index += 1
    return index


def _numeric_grammar_run_end(
    text: str,
    index: int,
    *,
    run_characters: str,
    profile: str,
) -> tuple[int, int]:
    """Consume one grammar-character run with interspersed Danish joiners."""
    character_count = 0
    while True:
        while index < len(text) and text[index] in run_characters:
            index += 1
            character_count += 1
        if profile != "da-DK":
            return index, character_count
        joiner_end = _next_numeric_joiner_end(text, index)
        if joiner_end >= len(text) or text[joiner_end] not in run_characters:
            return joiner_end, character_count
        index = joiner_end


def _danish_ordinal_list_match_has_admissible_left_boundary(
    scan_text: str,
    match: re.Match[str],
) -> bool:
    """Reject a grouping-space boundary that continues an earlier digit run."""
    boundary_start, boundary_end = match.span("boundary")
    if (
        boundary_start == boundary_end
        or scan_text[boundary_start] not in _DANISH_NUMERIC_GROUPING_SPACES
    ):
        return True
    previous = boundary_start - 1
    while previous >= 0 and scan_text[previous] in _DANISH_NUMERIC_GROUPING_SPACES:
        previous -= 1
    return previous < 0 or not scan_text[previous].isdigit()


def _danish_ordinal_list_match_starts_inside_range(
    match: re.Match[str],
    source_offsets: Sequence[int],
    range_internal_starts: Sequence[int],
    range_internal_prefix_max_ends: Sequence[int],
) -> bool:
    """Reject list items that restart strictly inside a range candidate."""
    return any(
        _span_is_contained_in_index(
            (
                source_offsets[match.start(group_name)],
                source_offsets[match.start(group_name)] + 1,
            ),
            range_internal_starts,
            range_internal_prefix_max_ends,
        )
        for group_name in ("item_before", "item_after")
    )


def _danish_ordinal_range_internal_index_from_view(
    scan_text: str,
    source_offsets: Sequence[int],
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Index strict range interiors from a joiner-filtered source view."""
    return _span_containment_index(
        tuple(
            (
                source_offsets[match.start("range_item")] + 1,
                source_offsets[match.end("range_item") - 1] + 1,
            )
            for match in _DANISH_ORDINAL_RANGE_SCAN_PATTERN.finditer(scan_text)
        )
    )


def _danish_ordinal_range_internal_index(
    text: str,
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Index strict range interiors in source coordinates."""
    return _danish_ordinal_range_internal_index_from_view(
        *_numeric_joiner_filtered_view(text)
    )


def _danish_ordinal_list_separator_indices(
    text: str,
    *,
    range_internal_index: tuple[Sequence[int], Sequence[int]] | None = None,
) -> frozenset[int]:
    """Locate separators bounded by two admissible ordinal-list items."""
    scan_text, source_offsets = _numeric_joiner_filtered_view(text)
    if range_internal_index is None:
        range_internal_index = _danish_ordinal_range_internal_index_from_view(
            scan_text,
            source_offsets,
        )
    range_internal_starts, range_internal_prefix_max_ends = range_internal_index
    return frozenset(
        source_offsets[match.end("item_before") - 1]
        for match in _DANISH_ORDINAL_LIST_SEPARATOR_PATTERN.finditer(scan_text)
        if _danish_ordinal_list_match_has_admissible_left_boundary(scan_text, match)
        and not _danish_ordinal_list_match_starts_inside_range(
            match,
            source_offsets,
            range_internal_starts,
            range_internal_prefix_max_ends,
        )
    )


def _danish_repeated_leading_sign_run_start(
    text: str,
    sign_index: int,
) -> int | None:
    """Return the first sign in a joiner-transparent repeated run."""
    start = sign_index
    sign_count = 1
    while True:
        previous = _previous_non_joiner_character(text, start)
        if previous < 0 or text[previous] not in _LOCALE_UNARY_SIGNS:
            break
        start = previous
        sign_count += 1
    return start if sign_count >= 2 else None


@dataclass(frozen=True)
class _LocaleNumericGrammarState:
    """State shared by direct and joiner-mediated envelope continuation."""

    exponent_seen: bool = False
    exponent_digits_seen: bool = False


def _advance_locale_numeric_grammar(
    text: str,
    index: int,
    *,
    profile: str,
    grouping_characters: str,
    state: _LocaleNumericGrammarState,
    ordinal_list_separator_indices: frozenset[int] = frozenset(),
) -> tuple[int, _LocaleNumericGrammarState, bool] | None:
    """Advance one transition in the locale numeric-envelope grammar."""
    if index >= len(text):
        return None
    character = text[index]
    if not _locale_numeric_envelope_grammar_accepts(
        character,
        profile=profile,
        grouping_characters=grouping_characters,
    ):
        return None
    if character.isdigit():
        return (
            index + 1,
            _LocaleNumericGrammarState(
                exponent_seen=state.exponent_seen,
                exponent_digits_seen=(
                    state.exponent_digits_seen or state.exponent_seen
                ),
            ),
            False,
        )
    if profile == "da-DK" and character in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS:
        return None
    if (
        profile in _DECIMAL_COMMA_NUMERIC_PROFILES
        and character == "."
        and _locale_glued_sentence_marker_end(text, index, profile=profile) is not None
    ):
        return None
    if character in ".,":
        if profile == "da-DK" and index in ordinal_list_separator_indices:
            return None
        digit_index, separator_count = _numeric_grammar_run_end(
            text,
            index,
            run_characters=".,",
            profile=profile,
        )
        if digit_index < len(text) and text[digit_index].isdigit():
            return digit_index, state, False
        if profile == "da-DK" and separator_count >= 2:
            return digit_index, state, True
        return None
    if character in grouping_characters:
        digit_index, separator_count = _numeric_grammar_run_end(
            text,
            index,
            run_characters=grouping_characters,
            profile=profile,
        )
        if digit_index < len(text) and text[digit_index].isdigit():
            return digit_index, state, False
        if profile == "da-DK" and separator_count >= 2:
            return digit_index, state, True
        return None
    if character in "Ee" and not state.exponent_seen:
        return index + 1, _LocaleNumericGrammarState(exponent_seen=True), False
    if (
        character in _LOCALE_UNARY_SIGNS
        and state.exponent_seen
        and not state.exponent_digits_seen
    ):
        # Reserve malformed sign runs atomically; the strict parser rejects them.
        return index + 1, state, False
    return None


def _advance_numeric_grammar_through_joiners(
    text: str,
    index: int,
    *,
    profile: str,
    grouping_characters: str,
    state: _LocaleNumericGrammarState,
    ordinal_list_separator_indices: frozenset[int],
) -> tuple[int, _LocaleNumericGrammarState, bool] | None:
    """Skip joiners, then preserve the direct grammar's next transition."""
    index = _next_numeric_joiner_end(text, index)
    return _advance_locale_numeric_grammar(
        text,
        index,
        profile=profile,
        grouping_characters=grouping_characters,
        state=state,
        ordinal_list_separator_indices=ordinal_list_separator_indices,
    )


def _iter_locale_numeric_envelopes(
    text: str,
    *,
    profile: str,
    boundaries: _NumericContextBoundaries | None = None,
    danish_ordinal_range_internal_index: tuple[Sequence[int], Sequence[int]]
    | None = None,
) -> Iterator[tuple[int, int]]:
    """Reserve each complete numeric-looking span before locale validation."""
    grouping_spaces = (
        _DANISH_NUMERIC_GROUPING_SPACES
        if profile == "da-DK"
        else _LOCALE_NUMERIC_GROUPING_SPACES
    )
    ordinal_list_separator_indices = (
        _danish_ordinal_list_separator_indices(
            text,
            range_internal_index=danish_ordinal_range_internal_index,
        )
        if profile == "da-DK"
        else frozenset()
    )
    occupied_until = 0
    for digit_match in re.finditer(r"\d", text):
        digit_start = digit_match.start()
        if digit_start < occupied_until:
            continue
        marker_dot = digit_start - 1
        if profile == "da-DK":
            while (
                marker_dot >= 0
                and text[marker_dot] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
            ):
                marker_dot -= 1
        if (
            profile in _DECIMAL_COMMA_NUMERIC_PROFILES
            and marker_dot >= 0
            and text[marker_dot] == "."
        ):
            marker_end = _locale_glued_sentence_marker_end(
                text,
                marker_dot,
                profile=profile,
            )
            if marker_end is not None:
                occupied_until = marker_end
                continue

        start = digit_start
        prefix_cursor = digit_start
        while True:
            punctuation_index = prefix_cursor - 1
            if profile == "da-DK":
                while (
                    punctuation_index >= 0
                    and text[punctuation_index]
                    in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
                ):
                    punctuation_index -= 1
            if punctuation_index < 0 or text[punctuation_index] not in ".,":
                break
            start = punctuation_index
            prefix_cursor = punctuation_index

        sign_search_cursor = start
        while True:
            grouping_index = sign_search_cursor - 1
            if profile == "da-DK":
                while (
                    grouping_index >= 0
                    and text[grouping_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
                ):
                    grouping_index -= 1
            if grouping_index < 0 or text[grouping_index] not in grouping_spaces:
                break
            sign_search_cursor = grouping_index

        sign_index = sign_search_cursor - 1
        if profile == "da-DK":
            while (
                sign_index >= 0
                and text[sign_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
            ):
                sign_index -= 1
        sign_is_candidate = (
            sign_index >= 0
            and text[sign_index] in _LOCALE_UNARY_SIGNS
            and (
                profile != "da-DK"
                or text[sign_index] == "+"
                or _next_numeric_joiner_end(text, sign_index + 1) == digit_start
            )
        )
        repeated_sign_start = (
            _danish_repeated_leading_sign_run_start(text, sign_index)
            if profile == "da-DK" and sign_is_candidate
            else None
        )
        if repeated_sign_start is not None:
            start = repeated_sign_start
        elif sign_is_candidate and _locale_sign_is_unary(
            text,
            sign_index,
            profile=profile,
            boundaries=boundaries,
        ):
            start = sign_index

        index = digit_start
        grammar_state = _LocaleNumericGrammarState()
        reserved_until = 0
        while index < len(text):
            char = text[index]
            if profile == "da-DK" and char in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS:
                advanced = _advance_numeric_grammar_through_joiners(
                    text,
                    index,
                    profile=profile,
                    grouping_characters=grouping_spaces,
                    state=grammar_state,
                    ordinal_list_separator_indices=ordinal_list_separator_indices,
                )
            else:
                marker_end = (
                    _locale_glued_sentence_marker_end(text, index, profile=profile)
                    if profile in _DECIMAL_COMMA_NUMERIC_PROFILES and char == "."
                    else None
                )
                if marker_end is not None:
                    reserved_until = marker_end
                    break
                advanced = _advance_locale_numeric_grammar(
                    text,
                    index,
                    profile=profile,
                    grouping_characters=grouping_spaces,
                    state=grammar_state,
                    ordinal_list_separator_indices=ordinal_list_separator_indices,
                )
            if advanced is None:
                break
            index, grammar_state, terminal_invalid = advanced
            if terminal_invalid:
                break

        occupied_until = max(index, reserved_until)
        yield start, index


def _valid_grouped_integer(
    raw: str,
    *,
    allowed_separators: str,
) -> tuple[bool, str]:
    separators = {char for char in raw if char in allowed_separators}
    if not separators:
        return raw.isdigit(), raw
    if len(separators) != 1:
        return False, ""
    separator = next(iter(separators))
    groups = raw.split(separator)
    if (
        not groups
        or not groups[0].isdigit()
        or not 1 <= len(groups[0]) <= 3
        or (len(groups[0]) > 1 and groups[0].startswith("0"))
        or any(len(group) != 3 or not group.isdigit() for group in groups[1:])
    ):
        return False, ""
    return True, "".join(groups)


def _parse_locale_numeric_envelope(raw: str, profile: str) -> float | None:
    if profile == "da-DK":
        raw = "".join(
            character
            for character in raw
            if character not in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
        )
        if raw and (
            raw[0] in _DANISH_NUMERIC_GROUPING_SPACES
            or raw[-1] in _DANISH_NUMERIC_GROUPING_SPACES
        ):
            return None
    stripped = raw.strip(_LOCALE_NUMERIC_GROUPING_SPACES)
    sign = 1.0
    if stripped and stripped[0] in _LOCALE_UNARY_SIGNS:
        if stripped[0] in "-\u2013\u2212":
            sign = -1.0
        stripped = stripped[1:].lstrip(_LOCALE_NUMERIC_GROUPING_SPACES)
    if not stripped:
        return None

    scientific = re.fullmatch(
        r"(?P<mantissa>.+?)(?P<exponent>[Ee][+\-\u2013\u2212]?\d+)?",
        stripped,
    )
    if scientific is None:
        return None
    mantissa = scientific.group("mantissa")
    exponent = (
        (scientific.group("exponent") or "")
        .replace("\u2013", "-")
        .replace("\u2212", "-")
    )

    if profile in _DECIMAL_COMMA_NUMERIC_PROFILES:
        if mantissa.count(",") > 1:
            return None
        integer, comma, fraction = mantissa.partition(",")
        if comma and (not fraction or not fraction.isdigit()):
            return None
        valid, normalized_integer = _valid_grouped_integer(
            integer,
            allowed_separators=(
                "." + _DANISH_NUMERIC_GROUPING_SPACES
                if profile == "da-DK"
                else "." + _LOCALE_NUMERIC_GROUPING_SPACES
            ),
        )
        if not valid:
            return None
        normalized = normalized_integer + (f".{fraction}" if comma else "") + exponent
    else:
        if mantissa.count(".") > 1:
            return None
        integer, dot, fraction = mantissa.partition(".")
        if dot and (not fraction or not fraction.isdigit()):
            return None
        valid, normalized_integer = _valid_grouped_integer(
            integer,
            allowed_separators=",",
        )
        if not valid:
            return None
        normalized = normalized_integer + (f".{fraction}" if dot else "") + exponent

    with contextlib.suppress(ValueError, OverflowError):
        value = sign * float(normalized)
        if math.isfinite(value):
            return value
    return None


def _locale_numeric_envelope_has_token_boundaries(
    text: str,
    span: tuple[int, int],
    *,
    profile: str = "legacy",
    source_text: str | None = None,
) -> bool:
    boundary_text = text if source_text is None else source_text
    before_index = span[0] - 1
    after_index = span[1]
    if profile == "da-DK":
        while (
            before_index >= 0
            and boundary_text[before_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
        ):
            before_index -= 1
        while (
            after_index < len(boundary_text)
            and boundary_text[after_index] in _DANISH_NUMERIC_JOINER_FORMAT_CHARACTERS
        ):
            after_index += 1
    before = boundary_text[before_index] if before_index >= 0 else ""
    after = boundary_text[after_index] if after_index < len(boundary_text) else ""
    return not (
        (before and (before.isalnum() or before == "_"))
        or (after and (after.isalnum() or after == "_"))
    )


def _temporal_numeric_component_spans(
    text: str,
) -> tuple[tuple[int, int], ...]:
    """Classify exact numeric tokens that form source-stated dates or periods."""
    spans: set[tuple[int, int]] = set()
    for match in _DOTTED_DATE_PATTERN.finditer(text):
        spans.update(match.span(group_name) for group_name in ("day", "month", "year"))
    for pattern in (
        _GERMAN_DAY_MONTH_YEAR_PATTERN,
        _ENGLISH_MONTH_DAY_YEAR_PATTERN,
        _ENGLISH_DAY_MONTH_YEAR_PATTERN,
    ):
        for match in pattern.finditer(text):
            spans.add(match.span("day"))
            spans.add(match.span("year"))
    for pattern in (
        _GERMAN_MONTH_YEAR_PATTERN,
        _ENGLISH_MONTH_YEAR_PATTERN,
        _TEMPORAL_PREPOSITION_YEAR_PATTERN,
    ):
        spans.update(match.span("year") for match in pattern.finditer(text))
    for match in _TEMPORAL_YEAR_RANGE_PATTERN.finditer(text):
        spans.add(match.span("start"))
        spans.add(match.span("end"))
    for match in _TEMPORAL_YEAR_CUE_PATTERN.finditer(text):
        years_start = match.start("years")
        spans.update(
            (
                years_start + year_match.start(),
                years_start + year_match.end(),
            )
            for year_match in _TEMPORAL_YEAR_TOKEN_PATTERN.finditer(
                match.group("years")
            )
        )
    return tuple(sorted(spans))


def _structural_numeric_component_spans(
    text: str,
    *,
    profile: str = "legacy",
) -> tuple[tuple[int, int], ...]:
    """Classify source spans whose numbers are only legal structural labels."""
    patterns = [
        _GERMAN_STRUCTURAL_LABEL_PATTERN,
        _GERMAN_STRUCTURAL_REFERENCE_PATTERN,
        _ENGLISH_STRUCTURAL_REFERENCE_PATTERN,
        _ENGLISH_STRUCTURAL_DIGIT_LABEL_PATTERN,
        _HEBREW_STRUCTURAL_REFERENCE_PATTERN,
        _HEBREW_WEEKDAY_PATTERN,
        _STRUCTURAL_SOURCE_STATE_CODE_CITATION_PATTERN,
        _STRUCTURAL_SOURCE_NJ_TITLE_54A_HEADING_PATTERN,
        _STRUCTURAL_LINE_MARKER_PATTERN,
        _STRUCTURAL_GLUED_SENTENCE_MARKER_PATTERN,
    ]
    if profile == "da-DK":
        danish_spans = _format_ignorable_pattern_source_spans(
            text,
            (
                _DANISH_STRUCTURAL_REFERENCE_PATTERN,
                _DANISH_STRUCTURAL_SENTENCE_PATTERN,
            ),
        )
    spans = {match.span() for pattern in patterns for match in pattern.finditer(text)}
    if profile == "da-DK":
        spans.update(danish_spans)
    spans.update(
        match.span("ordinal")
        for match in _STRUCTURAL_INLINE_NJ_LEGAL_ORDINAL_PATTERN.finditer(text)
    )
    return tuple(sorted(spans))


def _has_malformed_profiled_numeric_envelope(
    text: str,
    *,
    profile: str,
) -> bool:
    """Return whether strict-profile text contains an unparseable full span."""
    if profile == "legacy":
        return False
    if profile not in _NUMERIC_EXTRACTION_PROFILES:
        raise ValueError(f"Unsupported numeric profile: {profile}")
    if profile == "da-DK":
        ordinal_range_internal_index = _danish_ordinal_range_internal_index(text)
        numeric_mask = _danish_equal_length_numeric_mask(text)
        cleaned = numeric_mask.text
        boundaries = _NumericContextBoundaries.from_spans(
            (
                *numeric_mask.spans,
                *_structural_numeric_component_spans(text, profile=profile),
            )
        )
    else:
        cleaned = _clean_source_text_for_numeric_extraction(text, profile=profile)
        boundaries = None
        ordinal_range_internal_index = None
    return any(
        _locale_numeric_envelope_has_token_boundaries(
            cleaned,
            span,
            profile=profile,
            source_text=text if profile == "da-DK" else None,
        )
        and _parse_locale_numeric_envelope(cleaned[span[0] : span[1]], profile) is None
        for span in _iter_locale_numeric_envelopes(
            cleaned,
            profile=profile,
            boundaries=boundaries,
            danish_ordinal_range_internal_index=ordinal_range_internal_index,
        )
    )


def _german_word_number_occurrences(
    cleaned: str,
    *,
    view: _NumericTextView,
    collector: _LegacyNumericCollector,
) -> tuple[list[NumericOccurrence], list[NumericOccurrence]]:
    """Extract German word-number grounding candidates."""

    grounding: list[NumericOccurrence] = []
    inventory: list[NumericOccurrence] = []

    def add_unambiguous(span: tuple[int, int], value: float) -> None:
        occurrence = collector.occurrence(
            view,
            span,
            value,
            is_word_number=True,
        )
        grounding.append(occurrence)

    def add_fraction_alternatives(
        span: tuple[int, int],
        denominator: float,
        *,
        fraction_is_primary: bool = False,
        include_in_inventory: bool = True,
    ) -> None:
        reciprocal = 1.0 / denominator
        denominator_occurrence = collector.occurrence(
            view,
            span,
            denominator,
            is_word_number=True,
            alternative_values=(reciprocal,),
        )
        reciprocal_occurrence = collector.occurrence(
            view,
            span,
            reciprocal,
            is_word_number=True,
            alternative_values=(denominator,),
        )
        alternatives = (
            (reciprocal_occurrence, denominator_occurrence)
            if fraction_is_primary
            else (denominator_occurrence, reciprocal_occurrence)
        )
        grounding.extend(alternatives)
        # Keep one lexical candidate for the shared inventory projection.
        # `_scalar_recall_numeric_inventory` removes word-number candidates:
        # their numeric readings ground formula literals but do not independently
        # require named scalar definitions.
        if include_in_inventory:
            inventory.append(alternatives[0])

    for match in _GERMAN_FRACTION_WORD_PATTERN.finditer(cleaned):
        normalized_fraction = match.group("fraction").casefold()
        denominator = _GERMAN_FRACTION_DENOMINATOR_VALUES_CASEFOLD.get(
            normalized_fraction
        )
        if denominator is not None:
            add_fraction_alternatives(
                match.span(),
                denominator,
                fraction_is_primary=normalized_fraction == "hälfte".casefold(),
                include_in_inventory=normalized_fraction != "hälfte".casefold(),
            )

    seen_cardinal_spans: set[tuple[int, int]] = set()
    for pattern in (
        _GERMAN_CARDINAL_BEFORE_UNIT_PATTERN,
        _GERMAN_CARDINAL_BEFORE_MODIFIED_UNIT_PATTERN,
        _GERMAN_CARDINAL_BEFORE_FRACTION_PATTERN,
        _GERMAN_PRORATION_CARDINAL_PATTERN,
        _GERMAN_DIVISOR_CARDINAL_PATTERN,
    ):
        for match in pattern.finditer(cleaned):
            span = match.span("cardinal")
            if span in seen_cardinal_spans:
                continue
            value = _GERMAN_QUANTITATIVE_CARDINAL_VALUES_CASEFOLD.get(
                match.group("cardinal").casefold()
            )
            if value is None:
                continue
            add_unambiguous(span, value)
            seen_cardinal_spans.add(span)

    for match in _GERMAN_WORD_MULTIPLIER_PATTERN.finditer(cleaned):
        value = _GERMAN_MULTIPLIER_VALUES_CASEFOLD.get(
            match.group("multiplier").casefold()
        )
        if value is not None:
            add_unambiguous(match.span(), value)
    for match in _GERMAN_DOUBLE_MULTIPLIER_PATTERN.finditer(cleaned):
        add_unambiguous(match.span(), 2.0)

    for match in _GERMAN_ORDINAL_PART_PATTERN.finditer(cleaned):
        denominator = _GERMAN_ORDINAL_PART_VALUES_CASEFOLD.get(
            match.group("ordinal").casefold()
        )
        if denominator is not None:
            add_fraction_alternatives(
                match.span("ordinal"),
                denominator,
                fraction_is_primary=True,
                include_in_inventory=False,
            )

    return grounding, inventory


def _english_word_number_occurrences(
    cleaned: str,
    *,
    view: _NumericTextView,
    collector: _LegacyNumericCollector,
) -> list[NumericOccurrence]:
    """Extract unambiguous compound English cardinal grounding candidates."""

    occurrences: list[NumericOccurrence] = []
    for span, value in _iter_cardinal_word_number_matches(
        cleaned,
        compound_only=True,
    ):
        strict_value = _parse_strict_cardinal_number_words(cleaned[slice(*span)])
        if strict_value is None or not math.isclose(strict_value, value):
            continue
        occurrences.append(
            collector.occurrence(
                view,
                span,
                strict_value,
                is_word_number=True,
            )
        )
    return occurrences


def _scalar_recall_numeric_inventory(
    occurrences: Iterable[NumericOccurrence],
) -> tuple[NumericOccurrence, ...]:
    """Project typed grounding evidence into scalar-recall obligations."""
    return tuple(
        occurrence
        for occurrence in occurrences
        if not occurrence.is_word_number
        and not occurrence.has_temporal_context
        and not occurrence.has_structural_context
    )


def _is_same_evidence_scaled_inventory_duplicate(
    occurrence: NumericOccurrence,
    occurrences: Sequence[NumericOccurrence],
) -> bool:
    """Collapse scaled/unscaled readings only when one source span supplied both."""
    if math.isclose(
        occurrence.value,
        0,
        rel_tol=0,
        abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
    ):
        return True
    if occurrence.value > 1:
        return False
    scaled_value = round(occurrence.value * 100, 9)
    return any(
        candidate is not occurrence
        and candidate.span == occurrence.span
        and _occurrence_value_matches(candidate.value, scaled_value)
        for candidate in occurrences
    )


def _complete_typed_year_occurrences(
    collector: _LegacyNumericCollector,
    occurrences: Iterable[NumericOccurrence],
) -> tuple[NumericOccurrence, ...]:
    """Normalize and recover typed year tokens removed by structural cleaning."""
    typed_year_spans = {
        span
        for span in collector.temporal_component_spans
        if _locale_numeric_envelope_has_token_boundaries(
            collector.source,
            span,
            profile=collector.profile,
        )
        if not (
            span[1] + 1 < len(collector.source)
            and collector.source[span[1]] in ".,"
            and collector.source[span[1] + 1].isdigit()
        )
        if _TEMPORAL_YEAR_TOKEN_PATTERN.fullmatch(collector.source[span[0] : span[1]])
    }
    normalized = [
        occurrence
        for occurrence in occurrences
        if not any(
            occurrence.span != year_span
            and occurrence.start < year_span[0]
            and occurrence.end == year_span[1]
            and collector.source[occurrence.start : year_span[0]] == "-"
            for year_span in typed_year_spans
        )
    ]
    existing_spans = {occurrence.span for occurrence in normalized}
    source_view = _NumericTextView.identity(collector.source)
    for span in sorted(typed_year_spans):
        if span in existing_spans:
            continue
        raw = collector.source[span[0] : span[1]]
        occurrence = collector.occurrence(source_view, span, float(raw))
        insertion_index = next(
            (
                index
                for index, existing in enumerate(normalized)
                if existing.start > occurrence.start
            ),
            len(normalized),
        )
        normalized.insert(insertion_index, occurrence)
        existing_spans.add(span)
    typed_indices = [
        index
        for index, occurrence in enumerate(normalized)
        if occurrence.span in typed_year_spans
    ]
    typed_occurrences = sorted(
        (normalized[index] for index in typed_indices),
        key=lambda occurrence: occurrence.span,
    )
    for index, occurrence in zip(typed_indices, typed_occurrences, strict=True):
        normalized[index] = occurrence
    return tuple(normalized)


def _tokenize_profiled_numeric_occurrences(
    text: str,
    *,
    profile: str,
) -> _NumericTokenization:
    """Tokenize strict locale-aware numeric envelopes without suffix fallback."""
    if profile == "da-DK":
        ordinal_range_internal_index = _danish_ordinal_range_internal_index(text)
        numeric_mask = _danish_equal_length_numeric_mask(text)
        cleaned = numeric_mask.text
        view = _NumericTextView.equal_length_masked(text, cleaned)
        masked_context_spans = numeric_mask.spans
        numeric_boundaries = None
    else:
        cleaned_tracked = _clean_source_text_for_numeric_extraction_tracked(
            text, profile=profile
        )
        cleaned = cleaned_tracked.text
        view = _NumericTextView.tracked(text, cleaned_tracked)
        masked_context_spans = ()
        numeric_boundaries = None
        ordinal_range_internal_index = None
    collector = _LegacyNumericCollector(
        text,
        profile=profile,
        masked_context_spans=masked_context_spans,
    )
    if profile == "da-DK":
        numeric_boundaries = collector.context_boundaries
    grounding_occurrences: list[NumericOccurrence] = []
    inventory_occurrences: list[NumericOccurrence] = []

    for span in _iter_locale_numeric_envelopes(
        cleaned,
        profile=profile,
        boundaries=numeric_boundaries,
        danish_ordinal_range_internal_index=ordinal_range_internal_index,
    ):
        if not _locale_numeric_envelope_has_token_boundaries(
            cleaned,
            span,
            profile=profile,
            source_text=text if profile == "da-DK" else None,
        ):
            continue
        value = _parse_locale_numeric_envelope(cleaned[span[0] : span[1]], profile)
        if value is None:
            continue
        occurrence = collector.occurrence(view, span, value)
        grounding_occurrences.append(occurrence)
        inventory_occurrences.append(occurrence)

    if profile == "de-DE":
        word_grounding, word_inventory = _german_word_number_occurrences(
            cleaned,
            view=view,
            collector=collector,
        )
        grounding_occurrences.extend(word_grounding)
        inventory_occurrences.extend(word_inventory)
    elif profile in {"en-US", "en-GB"}:
        grounding_occurrences.extend(
            _english_word_number_occurrences(
                cleaned,
                view=view,
                collector=collector,
            )
        )

    grounding_occurrences = list(
        _complete_typed_year_occurrences(collector, grounding_occurrences)
    )
    inventory_occurrences = list(
        _complete_typed_year_occurrences(collector, inventory_occurrences)
    )
    grounding_occurrences.sort(
        key=lambda occurrence: (occurrence.start, occurrence.end)
    )
    inventory_occurrences.sort(
        key=lambda occurrence: (occurrence.start, occurrence.end)
    )
    return _NumericTokenization(
        grounding=tuple(grounding_occurrences),
        inventory=_scalar_recall_numeric_inventory(inventory_occurrences),
    )


def _occurrence_value_matches(left: float, right: float) -> bool:
    return math.isclose(
        left,
        right,
        rel_tol=0,
        abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
    )


# Complete-source-unit analysis re-tokenizes the same branch texts once per
# formula rule they are matched against; on one module ~95% of calls repeat
# an already-seen text. The result is a tuple of frozen occurrences, so it
# is safe to share.
@functools.lru_cache(maxsize=4096)
def _tokenize_numeric_occurrences_from_text(
    text: str,
    *,
    profile: str = "legacy",
) -> _NumericTokenization:
    """Tokenize once into typed grounding and source-inventory emission streams."""
    if profile not in _NUMERIC_EXTRACTION_PROFILES:
        raise ValueError(f"Unsupported numeric profile: {profile}")
    if profile != "legacy":
        return _tokenize_profiled_numeric_occurrences(text, profile=profile)

    collector = _LegacyNumericCollector(text)
    source_view = _NumericTextView.identity(text)
    implied_cents_matches = _iter_form_implied_cents_matches(text)
    raw_text = _FORM_IMPLIED_CENTS_PATTERN.sub(
        lambda match: " " * len(match.group(0)),
        text,
    )
    raw_view = _NumericTextView.aligned(text, raw_text)
    two_line_table_matches = _iter_two_line_table_value_occurrences(text)
    # raw_text is text with implied-cents runs blanked in place, so offsets
    # carried through the cleaning of raw_text are offsets into text.
    cleaned_tracked = _clean_source_text_for_numeric_extraction_tracked(raw_text)
    cleaned_before_schedule = cleaned_tracked.text
    cleaned_before_schedule_view = _NumericTextView.tracked(text, cleaned_tracked)
    schedule_matches, cleaned = _iter_collapsed_schedule_row_occurrences(
        cleaned_before_schedule
    )
    # Collapsing schedule rows blanks their lines in place, so the offsets
    # carried this far still hold.
    cleaned_view = _NumericTextView(text, cleaned, tuple(cleaned_tracked.offsets))

    def add_both(
        view: _NumericTextView,
        span: tuple[int, int],
        value: float,
        **kwargs: Any,
    ) -> None:
        collector.add_grounding(view, span, value, **kwargs)
        collector.add_inventory(view, span, value, **kwargs)

    def unique_matches(
        matches: Iterable[tuple[tuple[int, int], float]],
    ) -> list[tuple[tuple[int, int], float]]:
        first_span_by_value: dict[float, tuple[int, int]] = {}
        values: set[float] = set()
        for span, value in matches:
            values.add(value)
            first_span_by_value.setdefault(value, span)
        return [(first_span_by_value[value], value) for value in values]

    for span, value in two_line_table_matches:
        add_both(source_view, span, value)
    for span, value in schedule_matches:
        add_both(cleaned_before_schedule_view, span, value)
    for span, value in implied_cents_matches:
        add_both(source_view, span, value)
    for span, value in _iter_inline_form_implied_cents_matches(text):
        collector.add_grounding(source_view, span, value)

    grounding_spans: list[tuple[int, int]] = []
    inventory_spans: list[tuple[int, int]] = []

    range_matches = _iter_belgian_numeric_range_endpoint_matches(cleaned)
    for span, value in range_matches:
        add_both(cleaned_view, span, value)
        grounding_spans.append(span)
        inventory_spans.append(span)

    for match in re.finditer(
        r"\b(?:age|aged)\s+(\d{1,3})(?=\b)",
        raw_text,
        re.IGNORECASE,
    ):
        with contextlib.suppress(ValueError):
            collector.add_grounding(
                raw_view,
                match.span(1),
                float(match.group(1)),
            )

    raw_money_matches = _iter_raw_european_money_value_matches(raw_text)
    for span, value in raw_money_matches:
        collector.add_grounding(raw_view, span, value)

    cleaned_money_values: list[float] = []
    for span, value in _iter_raw_european_money_value_matches(cleaned):
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)
        if _span_overlaps(span, inventory_spans):
            continue
        collector.add_inventory(cleaned_view, span, value)
        cleaned_money_values.append(value)
        inventory_spans.append(span)
    for span, value in raw_money_matches:
        if any(
            math.isclose(
                value,
                cleaned_value,
                rel_tol=0,
                abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
            )
            for cleaned_value in cleaned_money_values
        ):
            continue
        collector.add_inventory(raw_view, span, value)

    # A fraction that a percent sign follows ("16 1⁄2%", "1⁄4%") is one rate,
    # read by the fraction pass below; the plain percentage matcher would
    # otherwise take its denominator ("2%") as a second one.
    fraction_raw_spans = [
        match.span() for match in _FRACTION_SLASH_PATTERN.finditer(raw_text)
    ]
    direct_percentage_rate_matches = [
        (span, value)
        for span, value in _iter_direct_percentage_rate_matches(raw_text)
        if not _span_overlaps(span, fraction_raw_spans)
    ]
    for span, value in direct_percentage_rate_matches:
        collector.add_grounding(
            raw_view,
            span,
            value,
            source_value=value * 100,
            force_rate_context=True,
            requires_rate_context=True,
        )
    for span, value in unique_matches(direct_percentage_rate_matches):
        collector.add_inventory(
            raw_view,
            span,
            value,
            source_value=value * 100,
            force_rate_context=True,
            requires_rate_context=True,
        )

    week_matches: list[tuple[tuple[int, int], float]] = []
    for match in _WEEK_DURATION_PATTERN.finditer(raw_text):
        value = _parse_belgian_numeric_phrase(match.group("number"))
        if value is not None:
            week_matches.append((match.span(), value * 7))
    for match in _ORDINAL_WEEK_DURATION_PATTERN.finditer(raw_text):
        normalized = re.sub(r"\s+", " ", match.group("number").strip().lower())
        value = _FRENCH_ORDINAL_PHRASE_VALUES.get(normalized)
        if value is not None:
            week_matches.append((match.span(), value * 7))
    for span, value in unique_matches(week_matches):
        add_both(raw_view, span, value)

    year_matches: list[tuple[tuple[int, int], float]] = []
    for match in _YEAR_DURATION_PATTERN.finditer(raw_text):
        value = _parse_belgian_numeric_phrase(match.group("number"))
        if value is not None:
            year_matches.append((match.span(), value * 12))
    for span, value in unique_matches(year_matches):
        add_both(raw_view, span, value)

    centime_match = _CENTIME_UNIT_PATTERN.search(raw_text)
    if centime_match:
        add_both(raw_view, centime_match.span(), 100.0)
    annual_match = _ANNUAL_CONTEXT_PATTERN.search(raw_text)
    if annual_match:
        collector.add_grounding(raw_view, annual_match.span(), 12.0)

    form_fraction_spans: list[tuple[int, int]] = []
    for match in (
        *_FORM_ARITHMETIC_FRACTION_PATTERN.finditer(raw_text),
        *_STANDALONE_FORM_FRACTION_PATTERN.finditer(raw_text),
    ):
        with contextlib.suppress(ValueError, ZeroDivisionError):
            denominator = float(match.group("denominator"))
            add_both(
                raw_view,
                match.span(),
                float(match.group("numerator")) / denominator,
            )
            form_fraction_spans.append(match.span())
    for match in _FORM_ARITHMETIC_OPERAND_PATTERN.finditer(raw_text):
        if _span_overlaps(match.span(), form_fraction_spans):
            continue
        with contextlib.suppress(ValueError):
            source_value = float(match.group("number").replace(",", ""))
            is_rate = bool(match.group("percent"))
            value = source_value / 100 if is_rate else source_value
            add_both(
                raw_view,
                match.span(),
                value,
                source_value=source_value,
                force_rate_context=is_rate,
                requires_rate_context=is_rate,
            )

    for match in _CONTEXTUAL_ASCII_FRACTION_PATTERN.finditer(raw_text):
        with contextlib.suppress(ValueError, ZeroDivisionError):
            whole = float(match.group("whole") or 0)
            numerator = float(match.group("numerator"))
            denominator = float(match.group("denominator"))
            add_both(
                raw_view,
                match.span(),
                whole + numerator / denominator,
            )

    # A fraction-slash run is read as written. A mixed number reaches this
    # pass as the whole number, a space and the fraction ("2 1⁄2", the form
    # the corpus keeps for OpenLaw's superscript-over-subscript typesetting);
    # a digit run glued to the slash ("21⁄2") is twenty-one halves and nothing
    # here guesses otherwise -- the boundary is the corpus adapter's to keep.
    # The pass reads the cleaned buffer so the run's span sits in the same
    # coordinates as the general digit passes below, which then leave the
    # numerator, the denominator and the whole number alone: the fraction is
    # one value the source states, atomic for recall, and an encoding that
    # states a quarter of a credit point as 0.25 has recalled it in full. The
    # printed numerator and denominator stay available to grounding, because
    # an encoding may also state them as the explicit pair the statute prints.
    # A fraction-slash run is read by the fraction pass below, percent word
    # and all; the digit matcher must not read its denominator ("1⁄ 2 אחוזים")
    # as a second rate.
    fraction_cleaned_spans = [
        match.span() for match in _FRACTION_SLASH_PATTERN.finditer(cleaned)
    ]
    for match in _HEBREW_DIGIT_PERCENT_PATTERN.finditer(cleaned):
        if _span_overlaps(match.span("number"), fraction_cleaned_spans):
            continue
        with contextlib.suppress(ValueError):
            value = float(match.group("number").replace(",", ""))
            if match.group("sign"):
                value = -value
            add_both(
                cleaned_view,
                match.span(),
                value / 100,
                source_value=value,
                force_rate_context=True,
                requires_rate_context=True,
            )
            grounding_spans.append(match.span())
            inventory_spans.append(match.span())

    for match in _FRACTION_SLASH_PATTERN.finditer(cleaned):
        with contextlib.suppress(ValueError, ZeroDivisionError):
            whole = float(match.group("whole") or 0)
            numerator = float(match.group("numerator"))
            denominator = float(match.group("denominator"))
            value = whole + numerator / denominator
            if match.group("sign"):
                value = -value
            if _PERCENT_MARKER_AFTER_NUMBER_PATTERN.match(
                cleaned, match.end()
            ) or _HEBREW_PERCENT_WORD_PATTERN.match(cleaned, match.end()):
                # "16 1⁄2%" is the rate 0.165: one value to recall, the way
                # "16.5%" is. The printed figure grounds as well, for an
                # encoding that states the percentage and divides itself.
                collector.add_grounding(cleaned_view, match.span(), value)
                add_both(
                    cleaned_view,
                    match.span(),
                    value / 100,
                    source_value=value,
                    force_rate_context=True,
                    requires_rate_context=True,
                )
            else:
                add_both(cleaned_view, match.span(), value)
            collector.add_grounding(cleaned_view, match.span("numerator"), numerator)
            collector.add_grounding(
                cleaned_view, match.span("denominator"), denominator
            )
            grounding_spans.append(match.span())
            inventory_spans.append(match.span())

    month_range_matches: list[tuple[tuple[int, int], float]] = []
    for match in _SMALL_MONTH_RANGE_PATTERN.finditer(raw_text):
        start = int(match.group("start"))
        end = int(match.group("end"))
        preceding_context = raw_text[max(0, match.start() - 500) : match.start()]
        row_context = raw_text[match.start() : match.end() + 80]
        if (
            0 <= start <= end <= 24
            and re.search(
                r"\bmonthly\s+proration\s+table\b",
                preceding_context,
                re.IGNORECASE,
            )
            and re.search(r"\bline\s+[A-E]\b", row_context, re.IGNORECASE)
        ):
            month_range_matches.extend(
                (match.span(), float(value)) for value in range(start, end + 1)
            )
    for span, value in month_range_matches:
        add_both(raw_view, span, value)

    vehicle_matches: list[tuple[tuple[int, int], float]] = []
    lowered_raw_text = raw_text.lower()
    for match in _VEHICLE_TAX_FISCAL_POWER_TABLE_CELL_PATTERN.finditer(raw_text):
        context = lowered_raw_text[max(0, match.start() - 2000) : match.start()]
        if not re.search(
            r"\b(?:chevaux\s+fiscaux|fiscale\s+paardenkracht|aantal\s+pk|cv)\b",
            context,
        ):
            continue
        with contextlib.suppress(ValueError):
            vehicle_matches.append((match.span("cv"), float(match.group("cv"))))
    for span, value in unique_matches(vehicle_matches):
        collector.add_grounding(raw_view, span, value)

    for match in GLUED_UNIT_NUMBER_PATTERN.finditer(cleaned):
        with contextlib.suppress(ValueError):
            collector.add_grounding(
                cleaned_view,
                match.span(),
                float(match.group("number").replace(",", "")),
            )
            grounding_spans.append(match.span())

    for match in CENTS_VALUE_NUMBER_PATTERN.finditer(cleaned):
        span = match.span()
        if _span_overlaps(span, grounding_spans):
            continue
        with contextlib.suppress(ValueError):
            value = float(match.group("number").replace(",", ""))
            collector.add_grounding(cleaned_view, span, value)
            collector.add_grounding(cleaned_view, span, value / 100)
            grounding_spans.append(span)

    special_matches = list(_iter_normalized_special_numeric_matches(cleaned))
    rate_marker_pattern = re.compile(
        r"(?:%|\bp\.?[ \t]*c\.?\b|\bpercent\b|"
        r"\bper[ \t-]+cent(?:um)?\b|\bProzent\b|"
        r"\bvom[ \t]+Hundert\b)",
        re.IGNORECASE,
    )
    for span, value in special_matches:
        raw = cleaned[span[0] : span[1]]
        is_rate = bool(rate_marker_pattern.search(raw))
        kwargs = {
            "source_value": value * 100 if is_rate else value,
            "force_rate_context": is_rate,
            "requires_rate_context": is_rate,
        }
        if not _span_overlaps(span, grounding_spans):
            collector.add_grounding(cleaned_view, span, value, **kwargs)
            grounding_spans.append(span)
        if not _span_overlaps(span, inventory_spans):
            collector.add_inventory(cleaned_view, span, value, **kwargs)
            inventory_spans.append(span)

    for match in re.finditer(
        r"(-?[\d,]+)\s+(\d+)\s*/\s*(\d+)"
        r"(?:\s+|-)(?:percent|per\s*cent(?:um)?)",
        cleaned,
        re.IGNORECASE,
    ):
        for group_index in (1, 2, 3):
            with contextlib.suppress(ValueError):
                collector.add_grounding(
                    cleaned_view,
                    match.span(group_index),
                    float(match.group(group_index).replace(",", "")),
                )

    percentage_number = (
        r"-?(?:\d{1,3}(?:[.\u00a0\u202f ]\d{3})+|\d+)"
        r"(?:,\d{1,4})?"
    )
    range_separator = (
        "(?:and|to|through|thru|et|\\u00e0|a|tot|bis|en|[-\\u2010-\\u2015])"
    )
    for match in re.finditer(
        rf"\b({percentage_number})\s+{range_separator}\s+({percentage_number})"
        r"\s*(?:%|\bp\.?\s*c\.?\b|\b(?:percent|per\s*cent(?:um)?)\b)",
        cleaned,
        re.IGNORECASE,
    ):
        for group_index in (1, 2):
            raw = _normalize_european_decimal_number(match.group(group_index))
            with contextlib.suppress(ValueError):
                source_value = float(raw)
                collector.add_grounding(
                    cleaned_view,
                    match.span(group_index),
                    source_value / 100,
                    source_value=source_value,
                    force_rate_context=True,
                    requires_rate_context=True,
                )

    for match in re.finditer(
        r"(?:^|(?<=[\s(\[,+\-−*/\"'`“”‘’]))"
        r"(-?(?:\d{1,3}(?:[.\u00a0\u202f ]\d{3})+|\d+),\d{1,4})"
        r"\s*(?:%|\bp\.?\s*c\.?\b|\b(?:percent|per\s*cent(?:um)?)\b)",
        cleaned,
        re.IGNORECASE,
    ):
        raw = _normalize_european_decimal_number(match.group(1))
        with contextlib.suppress(ValueError):
            source_value = float(raw)
            collector.add_grounding(
                cleaned_view,
                match.span(1),
                source_value / 100,
                source_value=source_value,
                force_rate_context=True,
                requires_rate_context=True,
            )
            collector.add_grounding(
                cleaned_view,
                match.span(1),
                source_value,
                force_rate_context=True,
            )

    percentage_context_number_matches = list(
        SOURCE_TEXT_NUMBER_PATTERN.finditer(cleaned)
    )
    for match in percentage_context_number_matches:
        raw = match.group(1).replace(",", "")
        with contextlib.suppress(ValueError):
            source_value = float(raw)
            if source_value <= 1:
                continue
            source_span = cleaned_view.source_span(match.span(1))
            if (
                any(
                    money_start <= source_span[0] and source_span[1] <= money_end
                    for money_start, money_end in collector.money_spans
                )
                or _currency_marker_before_number(
                    cleaned,
                    match.start(1),
                    profile=profile,
                    boundaries=collector.context_boundaries,
                )
                or _currency_marker_after_number(
                    cleaned,
                    match.end(1),
                    profile=profile,
                    boundaries=collector.context_boundaries,
                )
            ):
                continue
            context = cleaned[max(0, match.start() - 500) : match.end() + 80].lower()
            if not re.search(r"\bpercent(?:age|ages)?\b", context):
                continue
            collector.add_grounding(
                cleaned_view,
                match.span(1),
                source_value / 100,
                source_value=source_value,
                requires_rate_context=True,
            )
            if source_value >= 100 and re.search(
                r"\b(?:percent\s+of\s+(?:the\s+)?poverty\s+line|"
                r"percent\s+of\s+(?:the\s+)?federal\s+poverty\s+"
                r"(?:line|level)|fpl|income\s+tier)\b",
                context,
            ):
                collector.add_grounding(
                    cleaned_view,
                    match.span(1),
                    source_value,
                )

    word_quantity_matches = list(_iter_word_quantity_fraction_matches(cleaned))
    for span, value in word_quantity_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    standalone_fraction_matches = list(_iter_standalone_fraction_word_matches(cleaned))
    for span, value in standalone_fraction_matches:
        if not _span_overlaps(span, grounding_spans):
            collector.add_grounding(cleaned_view, span, value)
            grounding_spans.append(span)
        if not _span_overlaps(span, inventory_spans):
            collector.add_inventory(cleaned_view, span, value)
            inventory_spans.append(span)

    # A number a Hebrew statute writes as a word is as much a value the source
    # states as a digit is, so it joins the recall inventory as well as the
    # grounding set: an encoding that omits the "three" of "three children or
    # more" is as incomplete as one that omits a printed 3. Teens arrive as one
    # span ahead of their halves, and the overlap test keeps them atomic here
    # as it does for grounding.
    hebrew_word_matches = _iter_hebrew_number_word_matches(cleaned)
    for span, value in hebrew_word_matches:
        # "twenty-three percent" is the rate 0.23, grounded and recalled the
        # way "23%" is: the percent word joins the span and the number word's
        # own value is not a second obligation.
        percent = _HEBREW_PERCENT_WORD_PATTERN.match(cleaned, span[1])
        if percent is not None:
            span = (span[0], percent.end())
            if not _span_overlaps(span, grounding_spans):
                collector.add_grounding(
                    cleaned_view,
                    span,
                    value / 100,
                    source_value=value,
                    force_rate_context=True,
                    requires_rate_context=True,
                )
                grounding_spans.append(span)
            if not _span_overlaps(span, inventory_spans):
                collector.add_inventory(
                    cleaned_view,
                    span,
                    value / 100,
                    source_value=value,
                    force_rate_context=True,
                    requires_rate_context=True,
                )
                inventory_spans.append(span)
            continue
        if not _span_overlaps(span, grounding_spans):
            collector.add_grounding(cleaned_view, span, value)
            grounding_spans.append(span)
        if not _span_overlaps(span, inventory_spans):
            collector.add_inventory(cleaned_view, span, value)
            inventory_spans.append(span)

    ordinal_word_matches = _iter_ordinal_word_number_matches(cleaned)
    for span, value in ordinal_word_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    compound_cardinal_matches = _iter_cardinal_word_number_matches(
        cleaned,
        compound_only=True,
    )
    for span, value in compound_cardinal_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    digit_scale_matches = _iter_digit_scale_number_matches(cleaned)
    for span, value, raw_value in digit_scale_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        collector.add_grounding(cleaned_view, span, raw_value)
        grounding_spans.append(span)

    french_cardinal_matches = _iter_french_cardinal_phrase_matches(cleaned)
    for span, value in french_cardinal_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    dutch_cardinal_matches = _iter_dutch_cardinal_phrase_matches(cleaned)
    for span, value in dutch_cardinal_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    cardinal_matches = _iter_cardinal_word_number_matches(cleaned)
    for span, value in cardinal_matches:
        if _span_overlaps(span, grounding_spans):
            continue
        collector.add_grounding(cleaned_view, span, value)
        grounding_spans.append(span)

    for pattern, normalize, include_grounding, include_inventory in (
        (
            SPACED_EUROPEAN_DECIMAL_MONEY_PATTERN,
            _normalize_european_decimal_number,
            True,
            True,
        ),
        (
            EUROPEAN_DECIMAL_NUMBER_PATTERN,
            _normalize_european_decimal_number,
            True,
            True,
        ),
        (
            EUROPEAN_LEADING_ZERO_DECIMAL_NUMBER_PATTERN,
            _normalize_european_decimal_number,
            True,
            False,
        ),
    ):
        for match in pattern.finditer(cleaned):
            span = match.span(1)
            with contextlib.suppress(ValueError):
                value = float(normalize(match.group(1)))
                if include_grounding:
                    collector.add_grounding(cleaned_view, span, value)
                    grounding_spans.append(span)
                if include_inventory and not _span_overlaps(span, inventory_spans):
                    collector.add_inventory(cleaned_view, span, value)
                    inventory_spans.append(span)

    for match in EUROPEAN_THOUSANDS_NUMBER_PATTERN.finditer(cleaned):
        span = match.span(1)
        with contextlib.suppress(ValueError):
            value = float(_normalize_grouped_thousands_number(match.group(1)))
            if not _span_overlaps(span, grounding_spans):
                collector.add_grounding(cleaned_view, span, value)
                grounding_spans.append(span)
            if not _span_overlaps(span, inventory_spans):
                collector.add_inventory(cleaned_view, span, value)
                inventory_spans.append(span)

    for span, value, _ in digit_scale_matches:
        if _span_overlaps(span, inventory_spans):
            continue
        if value not in GROUNDING_ALLOWED_VALUES:
            collector.add_inventory(cleaned_view, span, value)
        inventory_spans.append(span)

    for match in EUROPEAN_DOT_THOUSANDS_NUMBER_PATTERN.finditer(cleaned):
        span = match.span(1)
        if _span_overlaps(span, grounding_spans):
            continue
        if _number_span_is_immediately_followed_by_percent_marker(cleaned, span):
            grounding_spans.append(span)
            continue
        with contextlib.suppress(ValueError):
            collector.add_grounding(
                cleaned_view,
                span,
                float(_normalize_grouped_thousands_number(match.group(1))),
            )
            grounding_spans.append(span)
        if re.fullmatch(r"-?[1-9]\d{0,2}\.\d{3}", match.group(1)):
            with contextlib.suppress(ValueError):
                collector.add_grounding(
                    cleaned_view,
                    span,
                    float(match.group(1)),
                )

    for match in percentage_context_number_matches:
        span = match.span(1)
        raw = match.group(1).replace(",", "")
        with contextlib.suppress(ValueError):
            value = float(raw)
            if not _span_overlaps(span, grounding_spans):
                if not _number_span_is_immediately_followed_by_percent_marker(
                    cleaned,
                    span,
                ) and not _has_captured_percentage_rate(
                    direct_percentage_rate_matches,
                    value,
                    span=span,
                ):
                    collector.add_grounding(cleaned_view, span, value)
            if _span_overlaps(span, inventory_spans):
                continue
            if _number_span_is_immediately_followed_by_percent_marker(cleaned, span):
                continue
            if _has_captured_percentage_rate(
                direct_percentage_rate_matches,
                value,
                span=span,
            ):
                continue
            grouped_value = _parse_belgian_numeric_phrase(match.group(1))
            if (
                grouped_value is not None
                and not math.isclose(
                    grouped_value,
                    value,
                    rel_tol=0,
                    abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
                )
                and any(
                    math.isclose(
                        grouped_value,
                        occurrence.value,
                        rel_tol=0,
                        abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
                    )
                    for occurrence in collector.inventory
                )
            ):
                continue
            collector.add_inventory(cleaned_view, span, value)

    for match in _ORDINAL_NUMBER_PATTERN.finditer(cleaned):
        with contextlib.suppress(ValueError):
            value = float(match.group(1))
            collector.add_grounding(cleaned_view, match.span(1), value)
            if _ordinal_is_calendar_day_reference(cleaned, match.end(), value):
                continue
            collector.add_inventory(cleaned_view, match.span(1), value)

    for span, value in ordinal_word_matches:
        if _span_overlaps(span, inventory_spans):
            continue
        if value not in GROUNDING_ALLOWED_VALUES:
            collector.add_inventory(cleaned_view, span, value)
        inventory_spans.append(span)

    for glyph, value in _UNICODE_FRACTION_VALUES.items():
        for match in re.finditer(re.escape(glyph), cleaned):
            collector.add_grounding(cleaned_view, match.span(), value)
            collector.add_inventory(cleaned_view, match.span(), value)

    for span, value in compound_cardinal_matches:
        if _span_overlaps(span, inventory_spans):
            continue
        if value not in GROUNDING_ALLOWED_VALUES:
            collector.add_inventory(cleaned_view, span, value)
        inventory_spans.append(span)

    for matches in (
        french_cardinal_matches,
        dutch_cardinal_matches,
        cardinal_matches,
    ):
        for span, value in matches:
            if _span_overlaps(span, inventory_spans):
                continue
            if value not in GROUNDING_ALLOWED_VALUES:
                collector.add_inventory(cleaned_view, span, value)
            inventory_spans.append(span)

    text_lower = cleaned.lower()
    for match in _CARDINAL_WORD_PATTERN.finditer(text_lower):
        if _span_overlaps(match.span(1), grounding_spans):
            continue
        collector.add_grounding(
            cleaned_view,
            match.span(1),
            _CARDINAL_WORD_VALUES[match.group(1)],
        )
        grounding_spans.append(match.span(1))

    collector.grounding = list(
        _complete_typed_year_occurrences(collector, collector.grounding)
    )
    collector.inventory = list(
        _complete_typed_year_occurrences(collector, collector.inventory)
    )
    inventory_occurrences = tuple(collector.inventory)
    normalized_inventory = _scalar_recall_numeric_inventory(
        occurrence
        for occurrence in inventory_occurrences
        if not _is_same_evidence_scaled_inventory_duplicate(
            occurrence,
            inventory_occurrences,
        )
    )
    return _NumericTokenization(
        grounding=tuple(collector.grounding),
        inventory=normalized_inventory,
    )


def extract_typed_numeric_occurrences_from_text(
    text: str,
    *,
    profile: str = "legacy",
) -> list[NumericOccurrence]:
    """Extract typed numeric grounding candidates with exact source metadata."""
    return list(
        _tokenize_numeric_occurrences_from_text(text, profile=profile).grounding
    )


def extract_typed_numeric_inventory_occurrences_from_text(
    text: str,
    *,
    profile: str = "legacy",
) -> list[NumericOccurrence]:
    """Extract the ordered typed source-recall occurrence stream."""
    return list(
        _tokenize_numeric_occurrences_from_text(text, profile=profile).inventory
    )


def extract_numbers_from_text(
    text: str,
    *,
    profile: str = "legacy",
) -> set[float]:
    """Extract numeric values from embedded statute text."""
    return {
        occurrence.value
        for occurrence in _tokenize_numeric_occurrences_from_text(
            text,
            profile=profile,
        ).grounding
    }


def extract_numeric_occurrences_from_text(
    text: str,
    *,
    profile: str = "legacy",
) -> list[float]:
    """Extract substantive numeric occurrences from source text, preserving repeats."""
    return [
        occurrence.value
        for occurrence in _tokenize_numeric_occurrences_from_text(
            text,
            profile=profile,
        ).inventory
    ]


def extract_named_scalar_occurrences(content: str) -> list[NamedScalarOccurrence]:
    """Extract direct named scalar definitions from a RuleSpec file."""
    with contextlib.suppress(yaml.YAMLError, TypeError, ValueError):
        payload = yaml.safe_load(content)
        if (
            isinstance(payload, dict)
            and payload.get("format") == "rulespec/v1"
            and isinstance(payload.get("rules"), list)
        ):
            occurrences: list[NamedScalarOccurrence] = []
            for rule in payload["rules"]:
                if not isinstance(rule, dict):
                    continue
                name = str(rule.get("name") or "").strip()
                if not name:
                    continue
                versions = rule.get("versions")
                if not isinstance(versions, list):
                    continue
                for version in versions:
                    if not isinstance(version, dict):
                        continue
                    formula = version.get("formula")
                    raw: str | None = None
                    if isinstance(formula, (int, float)) and not isinstance(
                        formula, bool
                    ):
                        raw = str(formula)
                    elif isinstance(formula, str):
                        stripped = formula.strip()
                        if _DIRECT_SCALAR_VALUE_PATTERN.fullmatch(stripped):
                            raw = stripped
                    if raw is not None:
                        with contextlib.suppress(ValueError):
                            occurrences.append(
                                NamedScalarOccurrence(
                                    line=1,
                                    name=name,
                                    value=float(raw.replace(",", "")),
                                )
                            )
                    table_values = version.get("values")
                    if isinstance(table_values, dict):
                        for key, table_value in table_values.items():
                            extracted_key = _numeric_rule_value(key)
                            if extracted_key is not None:
                                _, key_value = extracted_key
                                occurrences.append(
                                    NamedScalarOccurrence(
                                        line=1,
                                        name=f"{name}[{key}]",
                                        value=key_value,
                                    )
                                )
                            extracted = _numeric_rule_value(table_value)
                            if extracted is None:
                                continue
                            _, value = extracted
                            occurrences.append(
                                NamedScalarOccurrence(
                                    line=1,
                                    name=f"{name}[{key}]",
                                    value=value,
                                )
                            )
            return occurrences

    return []


def extract_embedded_source_text(content: str) -> str:
    """Extract embedded source text from RuleSpec YAML."""
    with contextlib.suppress(yaml.YAMLError, TypeError, ValueError):
        payload = yaml.safe_load(content)
        if isinstance(payload, dict) and payload.get("format") == "rulespec/v1":
            module = payload.get("module")
            if isinstance(module, dict):
                summary = module.get("summary")
                if isinstance(summary, str) and summary.strip():
                    return summary.strip()

    return ""


_DECIMAL_PLACE_SCALE_SOURCE_PATTERN = re.compile(
    r"\b(?:to\s+)?(?:an?\s+)?(?:accuracy\s+of\s+)?"
    rf"(?P<places>\d+|{_CARDINAL_WORD_SEQUENCE})\s+"
    r"decimal\s+places?\b",
    flags=re.IGNORECASE,
)


def _decimal_place_scale_values_from_source(source: str) -> set[float]:
    """Return integer scales implied by source phrases like four decimal places."""
    values: set[float] = set()
    for match in _DECIMAL_PLACE_SCALE_SOURCE_PATTERN.finditer(source):
        raw_places = match.group("places")
        places: int | None = None
        if raw_places.isdigit():
            places = int(raw_places)
        else:
            parsed = _parse_cardinal_number_words(raw_places)
            if parsed is not None and parsed.is_integer():
                places = int(parsed)
        if places is not None and 1 <= places <= 12:
            values.add(float(10**places))
    return values


def _module_numeric_citation_path(payload: Mapping[str, Any]) -> str | None:
    """Return the exact, unnormalized module citation identity when present."""
    citation_path: str | None = None
    module = payload.get("module")
    source_verification = (
        module.get("source_verification") if isinstance(module, dict) else None
    )
    if isinstance(source_verification, dict):
        raw_citation_path = source_verification.get("corpus_citation_path")
        if isinstance(raw_citation_path, str):
            citation_path = raw_citation_path
    return citation_path


def _module_numeric_evidence_item(
    payload: Mapping[str, Any],
    module_source: str,
    *,
    citation_path: str | None = None,
) -> _NumericEvidenceItem | None:
    """Attach the module source to its exact persisted citation identity."""
    if not module_source:
        return None
    if citation_path is None:
        citation_path = _module_numeric_citation_path(payload)
    return _NumericEvidenceItem(citation_path, module_source)


def _numeric_evidence_index(
    evidence_items: Sequence[_NumericEvidenceItem],
    *,
    suppress_ambiguous_half_up_terms: bool = False,
    cache: dict[
        tuple[str, str],
        tuple[tuple[NumericOccurrence, ...], frozenset[float]],
    ]
    | None = None,
) -> tuple[tuple[NumericOccurrence, ...], set[float]]:
    """Parse each evidence item under its own profile, then union the indexes."""
    occurrences: list[NumericOccurrence] = []
    decimal_place_scale_values: set[float] = set()
    for item in evidence_items:
        source = (
            _strip_ambiguous_half_up_terms(item.text)
            if suppress_ambiguous_half_up_terms
            else item.text
        )
        if not source:
            continue
        profile = _numeric_profile_for_citation_path(item.citation_path)
        cache_key = (profile, source)
        source_index = cache.get(cache_key) if cache is not None else None
        if source_index is None:
            source_index = (
                _tokenize_numeric_occurrences_from_text(
                    source,
                    profile=profile,
                ).grounding,
                frozenset(_decimal_place_scale_values_from_source(source)),
            )
            if cache is not None:
                cache[cache_key] = source_index
        occurrences.extend(source_index[0])
        decimal_place_scale_values.update(source_index[1])
    return tuple(occurrences), decimal_place_scale_values


def _numeric_value_grounded_in_source(
    value: float,
    source_occurrences: Sequence[NumericOccurrence],
    decimal_place_scale_values: set[float],
) -> bool:
    if numeric_value_is_grounded(value, source_occurrences):
        return True
    return any(
        math.isclose(
            value,
            decimal_place_scale_value,
            rel_tol=0,
            abs_tol=NUMERIC_GROUNDING_ABS_TOLERANCE,
        )
        for decimal_place_scale_value in decimal_place_scale_values
    )


def _attached_amendment_citations_for_numeric_value(
    value: float,
    amendment_source_texts: Mapping[str, str] | None,
) -> tuple[str, ...]:
    """Return exact attached citations containing ``value`` as typed evidence."""
    if not amendment_source_texts:
        return ()
    matches: list[str] = []
    for raw_citation_path, source_text in sorted(amendment_source_texts.items()):
        if not isinstance(raw_citation_path, str) or not isinstance(source_text, str):
            continue
        with contextlib.suppress(InvalidCorpusCitationError):
            citation_path = require_canonical_corpus_citation_path(raw_citation_path)
            if _source_text_contains_numeric_value_equivalent(
                source_text,
                value,
                profile=_numeric_profile_for_citation_path(citation_path),
            ):
                matches.append(citation_path)
    return tuple(matches)


def _attached_amendment_ungrounded_literal_hint(
    value: float,
    amendment_source_texts: Mapping[str, str] | None,
) -> str:
    """Point retries to attached evidence while leaving the value ungrounded."""
    citations = _attached_amendment_citations_for_numeric_value(
        value,
        amendment_source_texts,
    )
    if not citations:
        return ""
    citation_display = ", ".join(f"`{citation}`" for citation in citations)
    return (
        " Attached-amendment grounding hint: this value appears in attached "
        f"corpus document {citation_display}, but the attachment alone does not "
        "ground it. Add a source proof atom to the owning scalar/formula with "
        "the exact owning literal `path` (for a scalar parameter, for example, "
        "`path: versions[0].formula`), an appropriate `kind`, and nested "
        f"`source: {{corpus_citation_path: {citations[0]}, excerpt: <exact "
        "verbatim source span>}`."
    )


def _ungrounded_from_values(
    grounding_values: Sequence[tuple[int, str, float]],
    source: str,
    *,
    source_occurrences: Sequence[NumericOccurrence] | None = None,
    decimal_place_scale_values: set[float] | None = None,
) -> list[str]:
    """Report values not grounded in ``source`` (which must be pre-stripped)."""
    if source_occurrences is None:
        source_occurrences = _tokenize_numeric_occurrences_from_text(source).grounding
    if decimal_place_scale_values is None:
        decimal_place_scale_values = _decimal_place_scale_values_from_source(source)
    issues: list[str] = []
    for _, raw, value in grounding_values:
        if _numeric_value_grounded_in_source(
            value, source_occurrences, decimal_place_scale_values
        ):
            continue
        display = raw if raw == f"{value:g}" else f"{raw} ({value:g})"
        issues.append(
            "Ungrounded generated numeric literal: "
            f"{display} does not appear as a substantive numeric value in the source text."
        )
    return issues


def evaluate_numeric_grounding_values(
    content: str,
    source_text: str,
    *,
    authoritative_source_text: str | None = None,
    source_citation_path: str | None = None,
) -> list[tuple[int, str, float, bool]]:
    """Return a grounding decision for every generated numeric literal.

    ``source_text`` may include excerpt-verified proof evidence used for ordinary
    literal matching. Semantic rounding support is intentionally restricted to
    ``authoritative_source_text`` when supplied, so inline excerpts cannot grant
    the half-up helper exemption. A single annotated source is parsed under the
    profile selected by its exact canonical citation; unannotated text remains
    legacy.
    """
    grounding_values = extract_grounding_values(content)
    if not grounding_values:
        return []

    source_profile = _numeric_profile_for_citation_path(source_citation_path)
    authoritative_source = (
        source_text
        if authoritative_source_text is None
        else authoritative_source_text.strip()
    )
    with contextlib.suppress(yaml.YAMLError, TypeError, ValueError):
        payload = yaml.safe_load(content)
        if isinstance(payload, dict) and source_citation_path is None:
            source_profile = _numeric_profile_for_citation_path(
                _module_numeric_citation_path(payload)
            )
        rules = payload.get("rules") if isinstance(payload, dict) else None
        if isinstance(rules, list):
            selector_table_keys = _rulespec_index_selector_keys(rules)
            decisions: list[tuple[int, str, float, bool]] = []
            source_indexes: dict[
                tuple[str, str],
                tuple[tuple[NumericOccurrence, ...], set[float]],
            ] = {}
            for rule in rules:
                anchored_values = _rule_grounding_values_by_path(
                    rule, selector_table_keys=selector_table_keys
                )
                rule_name = (
                    str(rule.get("name") or "").strip()
                    if isinstance(rule, dict)
                    else ""
                )
                for anchor_path, raw, value in anchored_values:
                    direct_half_up_helper = _is_direct_half_up_rounding_helper_value(
                        rule, anchor_path, value
                    )
                    if direct_half_up_helper and (
                        _is_source_backed_half_up_rounding_helper(
                            rule_name, value, authoritative_source
                        )
                    ):
                        decisions.append((1, raw, value, True))
                        continue
                    grounding_source = (
                        _strip_ambiguous_half_up_terms(source_text)
                        if _is_half_up_rounding_helper_scalar(rule_name, value)
                        else source_text
                    )
                    source_index_key = (source_profile, grounding_source)
                    source_index = source_indexes.get(source_index_key)
                    if source_index is None:
                        source_index = (
                            _tokenize_numeric_occurrences_from_text(
                                grounding_source,
                                profile=source_profile,
                            ).grounding,
                            _decimal_place_scale_values_from_source(grounding_source),
                        )
                        source_indexes[source_index_key] = source_index
                    decisions.append(
                        (
                            1,
                            raw,
                            value,
                            _numeric_value_grounded_in_source(
                                value, source_index[0], source_index[1]
                            ),
                        )
                    )
            if len(decisions) == len(grounding_values):
                return decisions

    source_occurrences = _tokenize_numeric_occurrences_from_text(
        source_text,
        profile=source_profile,
    ).grounding
    decimal_place_scale_values = _decimal_place_scale_values_from_source(source_text)
    return [
        (
            line,
            raw,
            value,
            _numeric_value_grounded_in_source(
                value, source_occurrences, decimal_place_scale_values
            ),
        )
        for line, raw, value in grounding_values
    ]


def find_ungrounded_numeric_issues(
    content: str,
    source_text: str | None = None,
    *,
    authoritative_source_text: str | None = None,
    source_citation_path: str | None = None,
    require_complete_source_unit: bool = False,
    amendment_source_texts: Mapping[str, str] | None = None,
) -> list[str]:
    """Return issues for generated numeric literals absent from source text."""
    grounding_values = extract_grounding_values(content)
    if not grounding_values:
        return []

    if source_text is not None:
        source = source_text.strip()
    else:
        source = (extract_numeric_grounding_source_text(content) or "").strip()
    if not source:
        return [
            "Numeric source required: RuleSpec defines policy numeric literals "
            "but does not provide `source_verification.corpus_citation_path` text. "
            "`module.summary` is not accepted as source text for numeric grounding."
        ]

    issues: list[str] = []
    for _line, raw, value, grounded in evaluate_numeric_grounding_values(
        content,
        source,
        authoritative_source_text=authoritative_source_text,
        source_citation_path=source_citation_path,
    ):
        if grounded:
            continue
        display = raw if raw == f"{value:g}" else f"{raw} ({value:g})"
        hint = _stated_conversion_ungrounded_literal_hint(
            content,
            source,
            value,
            source_citation_path=source_citation_path,
            require_complete_source_unit=require_complete_source_unit,
        )
        amendment_hint = _attached_amendment_ungrounded_literal_hint(
            value,
            amendment_source_texts,
        )
        issues.append(
            "Ungrounded generated numeric literal: "
            f"{display} does not appear as a substantive numeric value in the source text."
            f"{hint}{amendment_hint}"
        )
    return issues


def _stated_conversion_ungrounded_literal_hint(
    content: str,
    source_text: str,
    value: float,
    *,
    source_citation_path: str | None,
    require_complete_source_unit: bool,
) -> str:
    """Return targeted retry guidance for a complete-mode calendar conversion."""

    if (
        not require_complete_source_unit
        or value not in _STATED_CONVERSION_CALENDAR_CONSTANTS
        or not source_states_stated_conversion_result(source_text)
    ):
        return ""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return ""
    if not isinstance(payload, dict):
        return ""
    citation_path = _module_numeric_citation_path(payload)
    if not isinstance(citation_path, str) or not citation_path.strip():
        return ""
    if (
        source_citation_path is not None
        and citation_path.strip() != source_citation_path.strip()
    ):
        return ""
    return f" {_STATED_CONVERSION_UNGROUNDED_HINT}"


def evaluate_numeric_grounding_values_scoped(
    content: str,
    *,
    module_source_text: str | None,
    module_citation_path: str | None = None,
    proof_source_texts: Mapping[str, str | None] | None = None,
    authoritative_source_text: str | None = None,
    require_body_bound_proof_evidence: bool = True,
) -> list[tuple[int, str, float, bool]]:
    """Evaluate anchored literals against separately profiled evidence items."""
    grounding_values = extract_grounding_values(content)
    if not grounding_values:
        return []

    module_source = (module_source_text or "").strip()
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        payload = None
    if (
        not isinstance(payload, dict)
        or payload.get("format") != "rulespec/v1"
        or not isinstance(payload.get("rules"), list)
    ):
        return evaluate_numeric_grounding_values(
            content,
            module_source,
            authoritative_source_text=authoritative_source_text,
            source_citation_path=module_citation_path,
        )

    module_evidence = _module_numeric_evidence_item(
        payload,
        module_source,
        citation_path=module_citation_path,
    )
    evidence_items_by_rule = [
        _rule_atom_numeric_evidence_items_by_path(
            rule,
            proof_source_texts,
            require_body_bound_evidence=require_body_bound_proof_evidence,
        )
        for rule in payload["rules"]
    ]
    selector_table_keys = _rulespec_index_selector_keys(payload["rules"])
    evidence_index_cache: dict[
        tuple[str, str],
        tuple[tuple[NumericOccurrence, ...], frozenset[float]],
    ] = {}
    decisions: list[tuple[int, str, float, bool]] = []
    for rule, evidence_items_by_path in zip(
        payload["rules"],
        evidence_items_by_rule,
        strict=True,
    ):
        anchored_values = _rule_grounding_values_by_path(
            rule,
            selector_table_keys=selector_table_keys,
        )
        if not anchored_values:
            continue
        verified_source_pairs_by_path = _rule_verified_source_excerpt_pairs_by_path(
            rule,
            proof_source_texts,
        )
        rule_name = (
            str(rule.get("name") or "").strip() if isinstance(rule, dict) else ""
        )
        for anchor_path, raw, value in anchored_values:
            direct_half_up_helper = _is_direct_half_up_rounding_helper_value(
                rule,
                anchor_path,
                value,
            )
            module_supports_rounding = bool(module_source) and (
                _is_source_backed_half_up_rounding_helper(
                    rule_name,
                    value,
                    module_source,
                )
            )
            source_evidence = verified_source_pairs_by_path.get(anchor_path, ())
            atom_supports_rounding = any(
                (
                    excerpt is None
                    or _is_source_backed_half_up_rounding_helper(
                        rule_name,
                        value,
                        excerpt,
                    )
                )
                and _is_source_backed_half_up_rounding_helper(
                    rule_name,
                    value,
                    resolved_source,
                )
                for excerpt, resolved_source in source_evidence
            )
            if direct_half_up_helper and (
                module_supports_rounding or atom_supports_rounding
            ):
                decisions.append((1, raw, value, True))
                continue

            evidence_items = (
                [module_evidence] if module_evidence is not None else []
            ) + list(evidence_items_by_path.get(anchor_path, ()))
            source_occurrences, decimal_place_scale_values = _numeric_evidence_index(
                evidence_items,
                suppress_ambiguous_half_up_terms=(
                    _is_half_up_rounding_helper_scalar(rule_name, value)
                ),
                cache=evidence_index_cache,
            )
            decisions.append(
                (
                    1,
                    raw,
                    value,
                    _numeric_value_grounded_in_source(
                        value,
                        source_occurrences,
                        decimal_place_scale_values,
                    ),
                )
            )

    if len(decisions) == len(grounding_values):
        return decisions
    return evaluate_numeric_grounding_values(
        content,
        module_source,
        authoritative_source_text=authoritative_source_text,
        source_citation_path=module_citation_path,
    )


def find_ungrounded_numeric_issues_scoped(
    content: str,
    *,
    module_source_text: str | None,
    module_citation_path: str | None = None,
    proof_source_texts: Mapping[str, str | None] | None = None,
    require_body_bound_proof_evidence: bool = True,
    require_complete_source_unit: bool = False,
    amendment_source_texts: Mapping[str, str] | None = None,
) -> list[str]:
    """Ground each rule's literals against the provisions that rule actually cites.

    A benefit/tax module legitimately draws its numbers from several provisions
    of one Act — a rate clause, a threshold clause, period conversions. Each such
    value is cited by the owning rule's proof atom (independently excerpt-verified
    against that provision). Grounding a rule's literals against its own cited
    provisions plus the module source is therefore both correct and no weaker than
    single-source grounding: a fabricated number still fails unless it appears in a
    provision that rule genuinely cites. Falls back to whole-module single-source
    grounding when the content cannot be parsed per rule.
    """
    module_source = (module_source_text or "").strip()
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        payload = None
    if (
        not isinstance(payload, dict)
        or payload.get("format") != "rulespec/v1"
        or not isinstance(payload.get("rules"), list)
    ):
        return find_ungrounded_numeric_issues(
            content,
            source_text=module_source_text,
            source_citation_path=module_citation_path,
            require_complete_source_unit=require_complete_source_unit,
            amendment_source_texts=amendment_source_texts,
        )

    if not extract_grounding_values(content):
        return []
    module_evidence = _module_numeric_evidence_item(
        payload,
        module_source,
        citation_path=module_citation_path,
    )
    evidence_items_by_rule = [
        _rule_atom_numeric_evidence_items_by_path(
            rule,
            proof_source_texts,
            require_body_bound_evidence=require_body_bound_proof_evidence,
        )
        for rule in payload["rules"]
    ]
    any_evidence = module_evidence is not None or any(
        any(items for items in evidence_by_path.values())
        for evidence_by_path in evidence_items_by_rule
    )
    if not any_evidence:
        return [
            "Numeric source required: RuleSpec defines policy numeric literals "
            "but does not provide `source_verification.corpus_citation_path` text. "
            "`module.summary` is not accepted as source text for numeric grounding."
        ]

    seen: set[str] = set()
    issues: list[str] = []
    # Bind each literal to only the proof atom at its exact RuleSpec path plus
    # the designated module source. The evaluator parses each source fragment
    # under its own citation-selected profile before unioning typed indexes.
    for _line, raw, value, grounded in evaluate_numeric_grounding_values_scoped(
        content,
        module_source_text=module_source,
        module_citation_path=module_citation_path,
        proof_source_texts=proof_source_texts,
        require_body_bound_proof_evidence=require_body_bound_proof_evidence,
    ):
        if grounded:
            continue
        display = raw if raw == f"{value:g}" else f"{raw} ({value:g})"
        stated_conversion_hint = _stated_conversion_ungrounded_literal_hint(
            content,
            module_source,
            value,
            source_citation_path=module_citation_path,
            require_complete_source_unit=require_complete_source_unit,
        )
        amendment_hint = _attached_amendment_ungrounded_literal_hint(
            value,
            amendment_source_texts,
        )
        issue = (
            "Ungrounded generated numeric literal: "
            f"{display} does not appear as a substantive numeric value in the source text."
            f"{stated_conversion_hint}{amendment_hint}"
        )
        if issue not in seen:
            seen.add(issue)
            issues.append(issue)
    return issues


def extract_numeric_grounding_source_text(content: str) -> str | None:
    """Return authoritative source text usable for numeric grounding.

    Numeric grounding must use ingested corpus source text. The human-readable
    module summary is intentionally excluded.
    """
    return _extract_source_verification_text(content)


def find_deprecated_source_url_issues(content: str) -> list[str]:
    """Reject raw source URL references in RuleSpec encodings."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []

    locations: list[str] = []
    module = payload.get("module")
    if isinstance(module, dict):
        if "source_url" in module:
            locations.append("module.source_url")
        source_verification = module.get("source_verification")
        if (
            isinstance(source_verification, dict)
            and "source_url" in source_verification
        ):
            locations.append("module.source_verification.source_url")

    source_verification = payload.get("source_verification")
    if isinstance(source_verification, dict) and "source_url" in source_verification:
        locations.append("source_verification.source_url")

    rules = payload.get("rules")
    if isinstance(rules, list):
        for index, rule in enumerate(rules):
            if isinstance(rule, dict) and "source_url" in rule:
                name = rule.get("name") or f"rules[{index}]"
                locations.append(f"rules.{name}.source_url")

    if not locations:
        return []
    return [
        "Legacy source URL metadata not allowed: "
        + ", ".join(locations[:5])
        + ("; ..." if len(locations) > 5 else "")
        + ". Use `module.source_verification.corpus_citation_path`."
    ]


def find_source_claim_reference_issues(content: str) -> list[str]:
    """Reject mutable source-claim references in favor of direct provisions."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []

    issues: list[str] = []
    module = payload.get("module")
    if isinstance(module, dict) and "source_claims" in module:
        issues.append(
            "Source claims are not supported: `module.source_claims` references "
            "mutable, release-agnostic claim artifacts. Cite immutable, "
            "release-bound corpus provisions with "
            "`module.source_verification.corpus_citation_path`, and use direct "
            "proof atom `source` evidence."
        )

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return issues
    for rule_index, rule in enumerate(rules):
        if not isinstance(rule, dict):
            continue
        metadata = rule.get("metadata")
        proof = metadata.get("proof") if isinstance(metadata, dict) else None
        if not isinstance(proof, dict):
            proof = rule.get("proof")
        atoms = proof.get("atoms") if isinstance(proof, dict) else None
        if not isinstance(atoms, list):
            continue
        rule_name = str(rule.get("name") or f"rules[{rule_index}]").strip()
        for atom_index, atom in enumerate(atoms):
            if not isinstance(atom, dict) or "claim" not in atom:
                continue
            issues.append(
                "Proof claim references are not supported: "
                f"rule `{rule_name}` proof atom {atom_index} declares `claim`. "
                "Cite the immutable, release-bound corpus provision directly "
                "with proof atom `source` evidence."
            )

    return issues


_INTERVAL_TABLE_SELECTOR_BOUND_KIND = "selector_inline_interval_bound"
_INTERVAL_TABLE_NON_SELECTOR_BOUND_KIND = "non_selector_interval_bound_literal"
_STRUCTURED_SCALE_BRANCH_FORMULA_KIND = "branch_formula_scale"
_STRUCTURED_SCALE_MALFORMED_TABLE_KIND = "malformed_parameter_table"


def find_interval_table_reencoding_candidates(
    content: str,
    *,
    include_selector_bounds: bool = False,
) -> list[IntervalTableAuditIssue]:
    """Find generated interval-table formulas that should be re-encoded.

    Today's encoder represents source tables with interval row labels as a
    derived band selector plus indexed parameter columns. Selector predicates
    are still allowed to contain the structural row bounds. Reusing those same
    bounds in other formula arithmetic is not allowed because it bakes
    parameter-table structure into formulas and prevents clean reparameterizing.
    """
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    selector_table_keys = _rulespec_index_selector_keys(rules)
    source_text = extract_embedded_source_text(content)
    source_looks_like_table = _source_text_looks_like_table(source_text)
    if not selector_table_keys and not source_looks_like_table:
        return []

    selector_bounds: list[_IntervalSelectorBound] = []
    selector_issues: list[IntervalTableAuditIssue] = []
    seen_selector_bounds: set[tuple[str, str, float]] = set()

    for rule in rules:
        if not isinstance(rule, dict) or not _is_structural_selector_rule(rule):
            continue
        rule_name = str(rule.get("name") or "<unknown>").strip()
        if not source_looks_like_table and rule_name not in selector_table_keys:
            continue
        selector_keys = selector_table_keys.get(rule_name)
        for formula in _rulespec_rule_formula_strings(rule):
            for raw, value in _interval_table_selector_bound_literals(
                formula,
                selector_keys=selector_keys,
            ):
                selector_bounds.append(
                    _IntervalSelectorBound(
                        raw=raw,
                        value=value,
                        selector_rule=rule_name,
                        formula=formula,
                    )
                )
                seen_key = (rule_name, raw, value)
                if seen_key in seen_selector_bounds:
                    continue
                seen_selector_bounds.add(seen_key)
                if include_selector_bounds:
                    selector_issues.append(
                        IntervalTableAuditIssue(
                            kind=_INTERVAL_TABLE_SELECTOR_BOUND_KIND,
                            rule=rule_name,
                            literal=raw,
                            value=value,
                            message=(
                                "Interval table selector inventory: "
                                f"`{rule_name}` keeps source-table row bound "
                                f"`{raw}` inline in selector arithmetic. This is "
                                "currently allowed, but the file should be "
                                "re-encoded after native interval-table support "
                                "lands."
                            ),
                        )
                    )

    if not selector_bounds:
        return selector_issues

    issues: list[IntervalTableAuditIssue] = list(selector_issues)
    seen_formula_bounds: set[tuple[str, str, float]] = set()
    for rule in rules:
        if not isinstance(rule, dict) or _is_structural_selector_rule(rule):
            continue
        rule_name = str(rule.get("name") or "<unknown>").strip()
        for formula in _rulespec_rule_formula_strings(rule):
            for raw, value in _interval_table_formula_literals(
                formula,
                selector_table_keys=selector_table_keys,
            ):
                if not _numeric_matches_interval_bound(
                    raw,
                    value,
                    selector_bounds,
                    formula=formula,
                ):
                    continue
                seen_key = (rule_name, raw, value)
                if seen_key in seen_formula_bounds:
                    continue
                seen_formula_bounds.add(seen_key)
                issues.append(
                    IntervalTableAuditIssue(
                        kind=_INTERVAL_TABLE_NON_SELECTOR_BOUND_KIND,
                        rule=rule_name,
                        literal=raw,
                        value=value,
                        message=(
                            "Interval table re-encoding required: "
                            f"`{rule_name}` formula contains source-table row "
                            f"bound literal `{raw}` outside structural selector "
                            "arithmetic. Move the interval row bounds into a "
                            "native interval table/scale representation instead "
                            "of hard-coding them in derived formulas."
                        ),
                    )
                )

    return issues


def find_interval_table_reencoding_issues(content: str) -> list[str]:
    """Return CI-blocking interval-table re-encoding issues."""
    return [
        issue.message
        for issue in find_interval_table_reencoding_candidates(content)
        if issue.kind == _INTERVAL_TABLE_NON_SELECTOR_BOUND_KIND
    ]


def _rulespec_rule_formula_strings(rule: dict[str, Any]) -> list[str]:
    formulas: list[str] = []
    versions = rule.get("versions")
    if not isinstance(versions, list):
        return formulas
    for version in versions:
        if not isinstance(version, dict):
            continue
        formula = version.get("formula")
        if isinstance(formula, str):
            formulas.append(formula)
    return formulas


def _interval_table_selector_bound_literals(
    formula: str,
    *,
    selector_keys: set[str] | None,
) -> list[tuple[str, float]]:
    literals: list[tuple[str, float]] = []
    cleaned = _formula_without_comments_and_dates(formula)
    for raw, value, start, end in _formula_numeric_literal_occurrences(cleaned):
        if not _formula_literal_is_comparison_bound(cleaned, raw, span=(start, end)):
            continue
        if _interval_table_literal_is_structural(
            cleaned,
            raw,
            value,
            selector_keys,
            span=(start, end),
            ignore_small_literals=True,
        ):
            continue
        literals.append((raw, value))
    return literals


def _interval_table_formula_literals(
    formula: str,
    *,
    selector_table_keys: dict[str, set[str]],
) -> list[tuple[str, float]]:
    literals: list[tuple[str, float]] = []
    cleaned = _formula_without_comments_and_dates(formula)
    for raw, value, start, end in _formula_numeric_literal_occurrences(cleaned):
        if _is_structural_selector_key_literal(cleaned, raw, selector_table_keys):
            continue
        if _interval_table_literal_is_structural(
            cleaned,
            raw,
            value,
            selector_keys=None,
            span=(start, end),
            ignore_small_literals=False,
        ):
            continue
        literals.append((raw, value))
    return literals


def _formula_without_comments_and_dates(formula: str) -> str:
    lines = [line.split("#", 1)[0] for line in formula.splitlines()]
    return GROUNDING_DATE_PATTERN.sub(" ", "\n".join(lines))


def _formula_numeric_literals(expression: str) -> list[tuple[str, float]]:
    return [
        (raw, value)
        for raw, value, _start, _end in _formula_numeric_literal_occurrences(expression)
    ]


def _formula_numeric_literal_occurrences(
    expression: str,
) -> list[tuple[str, float, int, int]]:
    literals: list[tuple[str, float, int, int]] = []
    for match in GROUNDING_FORMULA_NUMBER_PATTERN.finditer(expression):
        raw = match.group(1).replace(",", "")
        with contextlib.suppress(ValueError):
            start, end = match.span(1)
            literals.append((raw, float(raw), start, end))
    return literals


def _interval_table_literal_is_structural(
    expression: str,
    raw: str,
    value: float,
    selector_keys: set[str] | None,
    *,
    span: tuple[int, int] | None = None,
    ignore_small_literals: bool,
) -> bool:
    if ignore_small_literals and value in GROUNDING_ALLOWED_VALUES and "." not in raw:
        return True
    if raw == "0.5" and _is_half_up_rounding_expression(expression):
        return True
    return (
        _is_structural_table_key_literal(expression, raw, span=span)
        or _is_structural_table_index_clamp_literal(expression, raw, span=span)
        or _is_structural_mapping_key_literal(expression, raw, span=span)
        or _is_structural_schedule_index_literal(expression, raw, span=span)
        or _is_structural_enum_index_literal(expression, raw, span=span)
        or _is_structural_selector_result_literal(
            expression,
            raw,
            selector_keys,
            span=span,
        )
    )


def _is_structural_selector_key_literal(
    expression: str,
    raw: str,
    selector_table_keys: dict[str, set[str]],
) -> bool:
    if not selector_table_keys or not re.fullmatch(r"-?\d+(?:\.0+)?", raw):
        return False
    normalized_key = _structural_integer_key(raw)
    if normalized_key is None:
        return False
    selector_names = [
        name for name, keys in selector_table_keys.items() if normalized_key in keys
    ]
    if not selector_names:
        return False
    normalized = re.sub(r"\s+", " ", expression)
    for selector_name in selector_names:
        escaped_selector = re.escape(selector_name)
        escaped_raw = re.escape(raw)
        if re.search(
            rf"\b{escaped_selector}\s*(?:==|!=)\s*{escaped_raw}\b"
            rf"|\b{escaped_raw}\s*(?:==|!=)\s*{escaped_selector}\b",
            normalized,
        ):
            return True
    return False


def _formula_literal_is_comparison_bound(
    expression: str,
    raw: str,
    *,
    span: tuple[int, int] | None = None,
) -> bool:
    if span is not None:
        start, end = span
        before = expression[:start].rstrip()
        after = expression[end:].lstrip()
        return bool(
            re.search(r"(?:<=|>=|<|>)\s*$", before) or re.match(r"(?:<=|>=|<|>)", after)
        )
    escaped = re.escape(raw)
    return bool(
        re.search(rf"(?:<=|>=|<|>)\s*{escaped}(?![\d.])", expression)
        or re.search(rf"(?<![\d.]){escaped}\s*(?:<=|>=|<|>)", expression)
    )


def _numeric_matches_interval_bound(
    raw: str,
    value: float,
    bounds: list[_IntervalSelectorBound],
    *,
    formula: str = "",
) -> bool:
    for bound in bounds:
        if math.isclose(value, bound.value, rel_tol=0.0, abs_tol=1e-9):
            return True
        if not _percent_fraction_context_supports_conversion(formula, bound, value):
            continue
        if math.isclose(value * 100, bound.value, rel_tol=0.0, abs_tol=1e-9):
            return True
        if math.isclose(value, bound.value * 100, rel_tol=0.0, abs_tol=1e-9):
            return True
    return False


def _percent_fraction_context_supports_conversion(
    formula: str,
    bound: _IntervalSelectorBound,
    formula_value: float,
) -> bool:
    context = f"{formula}\n{bound.formula}\n{bound.selector_rule}".lower()
    if not any(
        token in context for token in ("fpl", "poverty", "percent", "percentage")
    ):
        return False
    if not any(token in context for token in ("fraction", "ratio", "share")):
        return False
    # Percent/FPL thresholds are conventionally 0-1000 percent or 0-10 as a
    # fraction. This avoids amount-like collisions such as 400 vs 40_000.
    percent_side = max(abs(bound.value), abs(formula_value))
    fraction_side = min(abs(bound.value), abs(formula_value))
    return percent_side <= 1000 and fraction_side <= 10


def find_structured_scale_parameter_issues(content: str) -> list[str]:
    """Flag source-stated numeric scales encoded as branch formulas."""
    return [
        issue.message
        for issue in find_structured_scale_parameter_issue_records(content)
    ]


def find_structured_scale_parameter_issue_records(
    content: str,
) -> list[StructuredScaleParameterIssue]:
    """Return structured records for malformed scale/table encodings."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    issues: list[StructuredScaleParameterIssue] = []
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        kind = str(rule.get("kind") or "").lower()
        if kind == "parameter":
            if rule.get("indexed_by") is None and any(
                isinstance(version, dict)
                and isinstance(version.get("values"), dict)
                and version.get("values")
                for version in rule.get("versions") or []
            ):
                name = str(rule.get("name") or "<unknown>")
                issues.append(
                    StructuredScaleParameterIssue(
                        kind=_STRUCTURED_SCALE_MALFORMED_TABLE_KIND,
                        rule=name,
                        message=(
                            "Structured parameter table malformed: "
                            f"{name} uses versioned `values` but does not "
                            "declare `indexed_by`."
                        ),
                    )
                )
            continue
        if kind != "derived":
            continue
        name = str(rule.get("name") or "<unknown>")
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            selector = _embedded_integer_scale_selector(formula)
            if selector is not None:
                issues.append(
                    StructuredScaleParameterIssue(
                        kind=_STRUCTURED_SCALE_BRANCH_FORMULA_KIND,
                        rule=name,
                        message=(
                            "Structured parameter table required: "
                            f"{name} encodes a numeric schedule keyed by {selector} "
                            "inside a derived formula; move source-stated cells to a "
                            "`kind: parameter` rule with `indexed_by` and versioned "
                            "`values`, then reference it with table lookup syntax."
                        ),
                    )
                )
                break
    return issues


def find_source_table_row_scalar_parameter_issues(content: str) -> list[str]:
    """Flag source tables exploded into scalar parameters per row/band/cell."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []

    source_text = extract_embedded_source_text(content)
    if not _source_text_looks_like_table(source_text):
        return []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    row_scalar_names: list[str] = []
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").lower() != "parameter":
            continue
        if rule.get("indexed_by") is not None:
            continue
        name = str(rule.get("name") or "").strip()
        if not name:
            continue
        if _is_source_table_structural_scalar_name(name):
            row_scalar_names.append(name)

    if len(row_scalar_names) < 3:
        return []

    sample = ", ".join(f"`{name}`" for name in row_scalar_names[:5])
    if len(row_scalar_names) > 5:
        sample += ", ..."
    return [
        "Source table row/band scalar parameters: "
        f"{sample} encode table rows, bands, or cells as standalone public "
        "parameters. "
        "Use one `kind: parameter` rule with `indexed_by` and versioned "
        "`values` for each substantive source table column, plus a derived "
        "band/key selector when the table uses interval rows. Store structural "
        "bounds as private named numeric concepts or indexed bound columns "
        "referenced by the selector instead of exporting one public scalar per "
        "row."
    ]


def _is_source_table_structural_scalar_name(name: str) -> bool:
    return bool(
        re.search(r"(?:^|_)row_\d+(?:_|$)", name)
        or re.search(r"(?:^|_)(?:band|bracket)_\d+(?:_|$)", name)
        or _is_source_table_structural_bound_parameter_name(name)
    )


@dataclass(frozen=True)
class _SourceTableScalarBound:
    name: str
    rule: dict[str, Any]
    side: str
    row_key: int
    value: int | float | None
    alias: str | None


def repair_source_table_band_scalar_parameters(
    content: str,
    *,
    source_text: str | None = None,
) -> tuple[str, list[str]]:
    """Normalize generated source-table bound scalars into named concepts."""
    payload = _rulespec_payload(content)
    table_source_text = source_text or extract_embedded_source_text(content)
    if (
        payload is None
        or payload.get("format") != "rulespec/v1"
        or not _source_text_looks_like_table(table_source_text)
    ):
        return content, []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return content, []

    bound_names: set[str] = set()
    scalar_bounds: dict[str, _SourceTableScalarBound] = {}
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").strip().lower() != "parameter":
            continue
        if rule.get("indexed_by") is not None:
            continue
        name = str(rule.get("name") or "").strip()
        if not _is_source_table_structural_bound_parameter_name(name):
            continue
        bound_names.add(name)
        bound = _source_table_scalar_bound(rule)
        if bound is not None:
            scalar_bounds[name] = bound

    if not bound_names:
        return content, []

    resolved_scalar_bounds = {
        name: value
        for name in scalar_bounds
        if (
            value := _resolve_source_table_scalar_bound_value(
                name,
                scalar_bounds,
            )
        )
        is not None
    }
    migratable_bound_names = set(resolved_scalar_bounds)
    selector_rule = (
        _source_table_bound_scalar_selector_rule(rules, migratable_bound_names)
        if len(migratable_bound_names) >= 3
        else None
    )
    selector_name = (
        str(selector_rule.get("name") or "").strip()
        if isinstance(selector_rule, dict)
        else ""
    )
    bound_table_names = {
        "lower": f"{selector_name}_lower_bound",
        "upper": f"{selector_name}_upper_bound",
    }
    migrated_replacements = (
        {
            name: f"{bound_table_names[scalar_bounds[name].side]}[{scalar_bounds[name].row_key}]"
            for name in migratable_bound_names
        }
        if selector_name
        else {}
    )

    referenced_bounds: set[str] = set()
    changed_rules: set[str] = set()
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        rule_name = str(rule.get("name") or "<unknown>").strip() or "<unknown>"
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            formula_bounds = {
                name
                for name in bound_names
                if _formula_references_identifier(formula, name)
            }
            if not formula_bounds:
                continue
            repaired = _repair_else_if_formula(formula)
            if migrated_replacements:
                repaired = _replace_formula_identifiers(
                    repaired,
                    {
                        name: replacement
                        for name, replacement in migrated_replacements.items()
                        if name in formula_bounds
                    },
                )
            if _formula_has_unsupported_chained_conditional(repaired):
                continue
            referenced_bounds.update(formula_bounds)
            if repaired != formula:
                version["formula"] = repaired
                changed_rules.add(rule_name)

    if not referenced_bounds:
        return content, []

    if migrated_replacements and isinstance(selector_rule, dict):
        for side in ("lower", "upper"):
            side_values = {
                scalar_bounds[name].row_key: resolved_scalar_bounds[name]
                for name in migratable_bound_names
                if scalar_bounds[name].side == side
            }
            if not side_values:
                continue
            _upsert_source_table_bound_values_rule(
                rules,
                selector_rule=selector_rule,
                table_name=bound_table_names[side],
                selector_name=selector_name,
                side=side,
                values=side_values,
                source_rules=[
                    scalar_bounds[name].rule
                    for name in migratable_bound_names
                    if scalar_bounds[name].side == side
                ],
            )
            changed_rules.add(bound_table_names[side])

        payload["rules"] = [
            rule
            for rule in rules
            if not (
                isinstance(rule, dict)
                and str(rule.get("name") or "").strip() in migratable_bound_names
            )
        ]
        changed_rules.update(migratable_bound_names)

    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, sorted(changed_rules)


def _source_table_scalar_bound(
    rule: dict[str, Any],
) -> _SourceTableScalarBound | None:
    name = str(rule.get("name") or "").strip()
    parsed = _parse_source_table_scalar_bound_name(name)
    if parsed is None:
        return None
    side, row_key = parsed
    value = _single_version_scalar_numeric_value(rule)
    alias = None if value is not None else _single_version_identifier_value(rule)
    return _SourceTableScalarBound(
        name=name,
        rule=rule,
        side=side,
        row_key=row_key,
        value=value,
        alias=alias,
    )


def _unreferenced_source_table_scalar_bound_names(rules: list[Any]) -> set[str]:
    candidates: set[str] = set()
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").strip().lower() != "parameter":
            continue
        if rule.get("indexed_by") is not None:
            continue
        name = str(rule.get("name") or "").strip()
        if _is_source_table_structural_bound_parameter_name(name):
            candidates.add(name)
    if not candidates:
        return set()

    referenced: set[str] = set()
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        rule_name = str(rule.get("name") or "").strip()
        if rule_name in candidates:
            continue
        for formula in _rulespec_rule_formula_strings(rule):
            referenced.update(
                name
                for name in candidates
                if _formula_references_identifier(formula, name)
            )
    return candidates - referenced


def _parse_source_table_scalar_bound_name(name: str) -> tuple[str, int] | None:
    normalized = name.strip().lower()
    patterns = (
        r"(?:^|_)(?P<side>lower|upper)_bound_"
        r"(?P<kind>row|band|bracket)_(?P<row>\d+)(?:_|$)",
        r"(?:^|_)(?P<side>lower|upper|min|max|minimum|maximum)_"
        r"(?P<kind>row|band|bracket)_(?P<row>\d+)(?:_|$)",
        r"(?:^|_)(?P<kind>row|band|bracket)_(?P<row>\d+)_"
        r"(?P<side>lower|upper|min|max|minimum|maximum)(?:_|$)",
    )
    for pattern in patterns:
        match = re.search(pattern, normalized)
        if match is None:
            continue
        side = _normalize_source_table_bound_side(match.group("side"))
        if side is None:
            continue
        return side, int(match.group("row"))
    return None


def _normalize_source_table_bound_side(raw_side: str) -> str | None:
    normalized = raw_side.strip().lower()
    if normalized in {"lower", "min", "minimum"}:
        return "lower"
    if normalized in {"upper", "max", "maximum"}:
        return "upper"
    return None


def _single_version_scalar_numeric_value(rule: dict[str, Any]) -> int | float | None:
    versions = rule.get("versions")
    if not isinstance(versions, list) or len(versions) != 1:
        return None
    version = versions[0]
    if not isinstance(version, dict):
        return None
    formula = version.get("formula")
    numeric = _numeric_rule_value(formula)
    if numeric is None:
        return None
    raw, value = numeric
    if "." not in raw and value.is_integer():
        return int(value)
    return value


def _single_version_identifier_value(rule: dict[str, Any]) -> str | None:
    versions = rule.get("versions")
    if not isinstance(versions, list) or len(versions) != 1:
        return None
    version = versions[0]
    if not isinstance(version, dict):
        return None
    formula = version.get("formula")
    if not isinstance(formula, str):
        return None
    stripped = formula.strip()
    return stripped if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", stripped) else None


def _resolve_source_table_scalar_bound_value(
    name: str,
    scalar_bounds: dict[str, _SourceTableScalarBound],
) -> int | float | None:
    seen: set[str] = set()
    current = name
    while current not in seen:
        seen.add(current)
        bound = scalar_bounds.get(current)
        if bound is None:
            return None
        if bound.value is not None:
            return bound.value
        if bound.alias is None:
            return None
        current = bound.alias
    return None


def _source_table_bound_scalar_selector_rule(
    rules: list[Any],
    bound_names: set[str],
) -> dict[str, Any] | None:
    if not bound_names:
        return None
    for rule in rules:
        if not isinstance(rule, dict) or not _is_structural_selector_rule(rule):
            continue
        for formula in _rulespec_rule_formula_strings(rule):
            if any(
                _formula_references_identifier(formula, bound_name)
                for bound_name in bound_names
            ):
                return rule
    return None


def _replace_formula_identifiers(
    formula: str,
    replacements: dict[str, str],
) -> str:
    repaired = formula
    for name in sorted(replacements, key=len, reverse=True):
        repaired = re.sub(
            rf"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])",
            replacements[name],
            repaired,
        )
    return repaired


def _upsert_source_table_bound_values_rule(
    rules: list[Any],
    *,
    selector_rule: dict[str, Any],
    table_name: str,
    selector_name: str,
    side: str,
    values: dict[int, int | float],
    source_rules: list[dict[str, Any]],
) -> None:
    sorted_values = {key: values[key] for key in sorted(values)}
    existing_rule = next(
        (
            rule
            for rule in rules
            if isinstance(rule, dict)
            and str(rule.get("name") or "").strip() == table_name
        ),
        None,
    )
    sample_rule = source_rules[0] if source_rules else selector_rule
    target_rule: dict[str, Any]
    if existing_rule is None:
        target_rule = {
            "name": table_name,
            "kind": "parameter",
            "dtype": sample_rule.get("dtype") or "Decimal",
            "indexed_by": selector_name,
            "versions": [
                {
                    "effective_from": _single_version_effective_from(sample_rule)
                    or _single_version_effective_from(selector_rule)
                    or "1900-01-01",
                    "values": sorted_values,
                }
            ],
        }
        if sample_rule.get("source") is not None:
            target_rule["source"] = sample_rule["source"]
        metadata = _source_table_bound_values_metadata(
            selector_rule=selector_rule,
            source_rules=source_rules,
            sample_rule=sample_rule,
        )
        if metadata:
            target_rule["metadata"] = metadata
        with contextlib.suppress(ValueError):
            rules.insert(rules.index(selector_rule), target_rule)
            return
        rules.append(target_rule)
        return

    target_rule = existing_rule
    target_rule["kind"] = "parameter"
    target_rule.setdefault("dtype", sample_rule.get("dtype") or "Decimal")
    target_rule["indexed_by"] = selector_name
    target_rule.setdefault("source", sample_rule.get("source"))
    metadata = _source_table_bound_values_metadata(
        selector_rule=selector_rule,
        source_rules=source_rules,
        sample_rule=sample_rule,
    )
    if metadata and not _rule_has_source_proof(target_rule):
        existing_metadata = target_rule.get("metadata")
        if isinstance(existing_metadata, dict):
            target_rule["metadata"] = {
                **existing_metadata,
                "proof": metadata["proof"],
            }
        else:
            target_rule["metadata"] = metadata
    versions = target_rule.get("versions")
    if not isinstance(versions, list) or not versions:
        target_rule["versions"] = [
            {
                "effective_from": _single_version_effective_from(sample_rule)
                or _single_version_effective_from(selector_rule)
                or "1900-01-01",
                "values": sorted_values,
            }
        ]
        return
    first_version = versions[0]
    if not isinstance(first_version, dict):
        versions[0] = {
            "effective_from": _single_version_effective_from(sample_rule)
            or _single_version_effective_from(selector_rule)
            or "1900-01-01",
            "values": sorted_values,
        }
        return
    first_version.setdefault(
        "effective_from",
        _single_version_effective_from(sample_rule)
        or _single_version_effective_from(selector_rule)
        or "1900-01-01",
    )
    first_version["values"] = sorted_values


def _source_table_bound_values_metadata(
    *,
    selector_rule: dict[str, Any],
    source_rules: list[dict[str, Any]],
    sample_rule: dict[str, Any],
) -> dict[str, Any]:
    source = _source_table_bound_values_proof_source(
        [selector_rule, *source_rules],
    )
    if source is None:
        raw_source = sample_rule.get("source") or selector_rule.get("source")
        if raw_source is not None:
            source = {"excerpt": str(raw_source)}
    if source is None:
        return {}
    return {
        "proof": {
            "atoms": [
                {
                    "path": "versions[0].values",
                    "kind": "parameter_table",
                    "source": source,
                }
            ]
        }
    }


def _source_table_bound_values_proof_source(
    rules: list[dict[str, Any]],
) -> dict[str, Any] | None:
    for rule in rules:
        metadata = rule.get("metadata")
        proof = metadata.get("proof") if isinstance(metadata, dict) else None
        atoms = proof.get("atoms") if isinstance(proof, dict) else None
        if not isinstance(atoms, list):
            continue
        for atom in atoms:
            if not isinstance(atom, dict):
                continue
            source = atom.get("source")
            if not isinstance(source, dict):
                continue
            if not (source.get("corpus_citation_path") or source.get("excerpt")):
                continue
            return copy.deepcopy(source)
    return None


def _single_version_effective_from(rule: dict[str, Any]) -> str | None:
    versions = rule.get("versions")
    if not isinstance(versions, list) or not versions:
        return None
    version = versions[0]
    if not isinstance(version, dict):
        return None
    effective_from = version.get("effective_from")
    return str(effective_from) if effective_from is not None else None


def repair_unsupported_chained_conditionals(content: str) -> tuple[str, list[str]]:
    """Rewrite generated multiline `elif`/`else if` formulas into expressions."""
    payload = _rulespec_payload(content)
    if payload is None or payload.get("format") != "rulespec/v1":
        return content, []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return content, []

    changed_rules: set[str] = set()
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        rule_name = str(rule.get("name") or "<unknown>").strip() or "<unknown>"
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            repaired = _repair_then_conditional_formula(formula)
            repaired = _repair_python_ternary_formula(repaired)
            repaired = _repair_else_if_formula(repaired)
            if repaired == formula:
                continue
            if _formula_has_unsupported_chained_conditional(repaired):
                continue
            version["formula"] = repaired
            changed_rules.add(rule_name)

    if not changed_rules:
        return content, []

    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, sorted(changed_rules)


def repair_formula_let_bindings(content: str) -> tuple[str, list[str]]:
    """Inline simple generated formula-local assignments."""
    payload = _rulespec_payload(content)
    if payload is None or payload.get("format") != "rulespec/v1":
        return content, []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return content, []

    changed_rules: set[str] = set()
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        rule_name = str(rule.get("name") or "<unknown>").strip() or "<unknown>"
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            repaired = _repair_formula_let_binding_text(formula)
            if repaired == formula:
                continue
            version["formula"] = repaired
            changed_rules.add(rule_name)

    if not changed_rules:
        return content, []

    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, sorted(changed_rules)


_FORMULA_LET_BINDING_PATTERN = re.compile(
    r"^(?P<indent>\s*)(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*=\s*(?!=)(?P<expr>.*)$"
)


def _repair_formula_let_binding_text(formula: str) -> str:
    lines = formula.splitlines()
    if not any(_FORMULA_LET_BINDING_PATTERN.match(line) for line in lines):
        return formula

    replacements: dict[str, str] = {}
    repaired_lines: list[str] = []
    changed = False
    index = 0
    while index < len(lines):
        line = lines[index]
        match = _FORMULA_LET_BINDING_PATTERN.match(line)
        if match is None:
            repaired_lines.append(
                _replace_formula_let_binding_names(line, replacements)
            )
            index += 1
            continue

        name = match.group("name")
        indent = len(match.group("indent"))
        expr_parts: list[str] = []
        inline_expr = match.group("expr").strip()
        if inline_expr:
            expr_parts.append(inline_expr)
            index += 1
        else:
            index += 1
            while index < len(lines):
                continuation = lines[index]
                if continuation.strip() == "":
                    index += 1
                    continue
                continuation_indent = len(continuation) - len(continuation.lstrip(" "))
                if continuation_indent <= indent:
                    break
                expr_parts.append(continuation.strip())
                index += 1

        if not expr_parts:
            repaired_lines.append(line)
            continue

        expression = " ".join(expr_parts)
        expression = _replace_formula_let_binding_names(expression, replacements)
        replacements[name] = f"({expression})"
        changed = True

    if not changed:
        return formula
    return "\n".join(repaired_lines)


def _replace_formula_let_binding_names(line: str, replacements: dict[str, str]) -> str:
    repaired = line
    for name, expression in replacements.items():
        repaired = re.sub(rf"\b{re.escape(name)}\b", expression, repaired)
    return repaired


def repair_source_table_open_ended_bound_sentinels(
    content: str,
    *,
    source_text: str | None = None,
) -> tuple[str, list[str]]:
    """Remove invented sentinel values for open-ended source table bounds."""
    payload = _rulespec_payload(content)
    if payload is None or payload.get("format") != "rulespec/v1":
        return content, []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return content, []

    source = (
        source_text.strip()
        if source_text is not None
        else (extract_numeric_grounding_source_text(content) or "").strip()
    )
    profile = _numeric_profile_for_citation_path(_module_numeric_citation_path(payload))
    source_occurrences = (
        extract_typed_numeric_occurrences_from_text(source, profile=profile)
        if source
        else []
    )
    changed_rules: set[str] = set()

    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").strip().lower() != "parameter":
            continue
        if rule.get("indexed_by") is None:
            continue
        rule_name = str(rule.get("name") or "").strip()
        if not _looks_like_open_ended_upper_bound_parameter(rule):
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        for version in versions:
            if not isinstance(version, dict):
                continue
            values = version.get("values")
            if not isinstance(values, dict) or len(values) < 2:
                continue
            max_key = _max_structural_integer_table_key(values)
            if max_key is None:
                continue
            numeric = _numeric_rule_value(values.get(max_key))
            if numeric is None:
                continue
            _raw, value = numeric
            if not _is_generated_open_ended_bound_sentinel(
                value,
                source_occurrences,
            ):
                continue
            del values[max_key]
            changed_rules.add(rule_name or "<unknown>")

    if not changed_rules:
        return content, []

    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, sorted(changed_rules)


@dataclass(frozen=True)
class _IntervalSourceRow:
    lower: str | None
    upper: str | None
    outputs: tuple[str, ...]


@dataclass(frozen=True)
class _IntervalSourceTable:
    output_headers: tuple[str, ...]
    rows: tuple[_IntervalSourceRow, ...]


@dataclass(frozen=True)
class _IntervalAlignmentSpec:
    selector_name: str
    input_name: str
    rows: tuple[_IntervalSourceRow, ...]
    lower_bound_parameter_name: str | None
    upper_bound_parameter_name: str | None
    lower_bound_parameter_rule: dict[str, Any] | None
    upper_bound_parameter_rule: dict[str, Any] | None
    output_parameter_names: tuple[str, ...]
    output_parameter_rules: tuple[dict[str, Any], ...]


def repair_source_table_interval_row_alignment(
    content: str,
    *,
    source_text: str | None = None,
) -> tuple[str, list[str]]:
    """Preserve row identity for open-ended interval source tables."""
    payload = _rulespec_payload(content)
    if payload is None or payload.get("format") != "rulespec/v1":
        return content, []

    specs = _source_table_interval_alignment_specs(payload, source_text=source_text)
    if not specs:
        return content, []

    rules = payload.get("rules")
    if not isinstance(rules, list):
        return content, []

    changed_rules: set[str] = set()
    selector_by_name = {
        str(rule.get("name") or "").strip(): rule
        for rule in rules
        if isinstance(rule, dict)
    }
    for spec in specs:
        selector_rule = selector_by_name.get(spec.selector_name)
        if not isinstance(selector_rule, dict):
            continue
        versions = selector_rule.get("versions")
        if not isinstance(versions, list) or not versions:
            continue
        first_version = versions[0]
        if not isinstance(first_version, dict):
            continue

        lower_bound_name, lower_bound_changed = _ensure_interval_bound_parameter_rule(
            rules,
            spec=spec,
            selector_rule=selector_rule,
            selector_version=first_version,
            side="lower",
        )
        if lower_bound_changed and lower_bound_name:
            changed_rules.add(lower_bound_name)
        upper_bound_name, upper_bound_changed = _ensure_interval_bound_parameter_rule(
            rules,
            spec=spec,
            selector_rule=selector_rule,
            selector_version=first_version,
            side="upper",
        )
        if upper_bound_changed and upper_bound_name:
            changed_rules.add(upper_bound_name)

        repaired_formula = _build_interval_selector_formula(
            input_name=spec.input_name,
            rows=spec.rows,
            lower_bound_name=lower_bound_name,
            upper_bound_name=upper_bound_name,
        )
        if not repaired_formula:
            continue
        if first_version.get("formula") != repaired_formula:
            first_version["formula"] = repaired_formula
            changed_rules.add(spec.selector_name)

        for column_index, parameter_rule in enumerate(spec.output_parameter_rules):
            parameter_name = str(parameter_rule.get("name") or "").strip()
            parameter_versions = parameter_rule.get("versions")
            if not isinstance(parameter_versions, list) or not parameter_versions:
                continue
            parameter_version = parameter_versions[0]
            if not isinstance(parameter_version, dict):
                continue
            repaired_values = {
                row_index: _coerce_interval_source_output_value(
                    row.outputs[column_index],
                    parameter_rule,
                )
                for row_index, row in enumerate(spec.rows, start=1)
            }
            if parameter_version.get("values") != repaired_values:
                parameter_version["values"] = repaired_values
                changed_rules.add(parameter_name or "<unknown>")

    removable_bound_names = _unreferenced_source_table_scalar_bound_names(rules)
    if removable_bound_names:
        payload["rules"] = [
            rule
            for rule in rules
            if not (
                isinstance(rule, dict)
                and str(rule.get("name") or "").strip() in removable_bound_names
            )
        ]
        changed_rules.update(removable_bound_names)

    if not changed_rules:
        return content, []

    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, sorted(changed_rules)


def repair_source_table_interval_tests(
    content: str,
    *,
    rulespec_content: str | None,
    source_text: str | None = None,
) -> tuple[str, list[str]]:
    """Repair generated tests after interval source-table row realignment."""
    if not rulespec_content:
        return content, []
    try:
        cases = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return content, []
    if not isinstance(cases, list):
        return content, []

    payload = _rulespec_payload(rulespec_content)
    if payload is None:
        return content, []
    specs = _source_table_interval_alignment_specs(payload, source_text=source_text)
    if not specs:
        return content, []

    changed_cases: list[str] = []
    for case in cases:
        if not isinstance(case, dict):
            continue
        inputs = case.get("input")
        outputs = case.get("output")
        if not isinstance(inputs, dict) or not isinstance(outputs, dict):
            continue
        case_changed = False
        for spec in specs:
            input_value = _test_input_value_for_name(inputs, spec.input_name)
            if input_value is None:
                continue
            with contextlib.suppress(TypeError, ValueError):
                selector_key = _interval_selector_key_for_value(
                    float(input_value),
                    spec.rows,
                )
                if selector_key is None:
                    continue
                expected_outputs = _interval_expected_outputs_for_key(
                    payload,
                    spec,
                    selector_key,
                )
                for output_key in list(outputs):
                    local_name = _rulespec_test_reference_local_name(output_key)
                    if local_name not in expected_outputs:
                        continue
                    repaired_value = expected_outputs[local_name]
                    if outputs[output_key] != repaired_value:
                        outputs[output_key] = repaired_value
                        case_changed = True
        if case_changed:
            changed_cases.append(str(case.get("name") or "<unnamed>"))

    if not changed_cases:
        return content, []
    repaired_content = yaml.safe_dump(cases, sort_keys=False).strip() + "\n"
    return repaired_content, changed_cases


def repair_copied_cross_reference_summary(
    content: str,
    *,
    rules_file: Path,
    policy_repo_path: Path | None = None,
) -> tuple[str, list[str]]:
    """Remove copied same-section cross-reference bodies from module summaries."""
    payload = _rulespec_payload(content)
    if payload is None or payload.get("format") != "rulespec/v1":
        return content, []

    module = payload.get("module")
    if not isinstance(module, dict):
        return content, []
    summary = module.get("summary")
    if not isinstance(summary, str) or not summary.strip():
        return content, []

    statute_path = (
        _statute_path_parts_for_file(rules_file, policy_repo_path)
        if policy_repo_path is not None
        else _statute_path_parts_for_any_file(rules_file)
    )
    if statute_path is None:
        return content, []
    title, section, current_fragments = statute_path

    cited_subsections = _same_section_subsections_cited_by_summary(summary)
    if not cited_subsections:
        return content, []

    repaired_summary = summary
    repaired_imports: list[str] = []
    for subsection in cited_subsections:
        if subsection in current_fragments:
            continue
        repaired, changed = _remove_summary_subsection_body(
            repaired_summary,
            subsection=subsection,
        )
        if not changed:
            continue
        repaired_summary = repaired
        repaired_imports.append("/".join(["statutes", title, section, subsection]))

    if not repaired_imports:
        return content, []

    module["summary"] = repaired_summary.strip()
    repaired_content = yaml.safe_dump(payload, sort_keys=False).strip() + "\n"
    return repaired_content, repaired_imports


def _same_section_subsections_cited_by_summary(summary: str) -> list[str]:
    seen: set[str] = set()
    subsections: list[str] = []
    for match in re.finditer(
        r"\bsubsection\s+\((?P<subsection>[A-Za-z0-9.]+)\)"
        r"(?:\s+of\s+this\s+section)?(?=\W|$)",
        summary,
        flags=re.IGNORECASE,
    ):
        subsection = match.group("subsection")
        if subsection in seen:
            continue
        seen.add(subsection)
        subsections.append(subsection)
    return subsections


def _remove_summary_subsection_body(
    summary: str,
    *,
    subsection: str,
) -> tuple[str, bool]:
    copied_body_pattern = re.compile(
        rf"(?ms)(^|\n+)\({re.escape(subsection)}\)\s+[A-Z][\s\S]*?"
        r"(?=\n+\([A-Za-z0-9.]+\)\s+[A-Z]|\Z)"
    )

    def remove_body(match: re.Match[str]) -> str:
        prefix = match.group(1)
        return "\n\n" if "\n\n" in prefix else prefix

    repaired, count = copied_body_pattern.subn(remove_body, summary)
    if count == 0:
        return summary, False
    repaired = re.sub(r"\n{3,}", "\n\n", repaired).strip()
    return repaired, True


def _statute_path_parts_for_any_file(
    rules_file: Path,
) -> tuple[str, str, tuple[str, ...]] | None:
    parts = rules_file.resolve(strict=False).parts
    for index, part in enumerate(parts):
        if part != "statutes":
            continue
        return _statute_path_parts_from_relative_parts(tuple(parts[index:]))
    return None


def _statute_path_parts_from_relative_parts(
    relative_parts: tuple[str, ...],
) -> tuple[str, str, tuple[str, ...]] | None:
    if not relative_parts or len(relative_parts) < 4 or relative_parts[0] != "statutes":
        return None

    title = relative_parts[1]
    section = relative_parts[2]
    fragments = list(relative_parts[3:-1])
    stem = Path(relative_parts[-1]).stem
    if stem not in {"index", "__init__"}:
        fragments.append(stem)
    return title, section, tuple(fragments)


def _source_table_interval_alignment_specs(
    payload: dict[str, Any],
    *,
    source_text: str | None = None,
) -> list[_IntervalAlignmentSpec]:
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    source_table = _parse_interval_source_table(
        source_text or _rulespec_module_summary(payload)
    )
    if source_table is None or not source_table.rows:
        return []
    if not any(row.lower is None or row.upper is None for row in source_table.rows):
        return []

    specs: list[_IntervalAlignmentSpec] = []
    for selector_rule in rules:
        if not isinstance(selector_rule, dict) or not _is_structural_selector_rule(
            selector_rule
        ):
            continue
        if str(selector_rule.get("kind") or "").strip().lower() != "derived":
            continue
        selector_name = str(selector_rule.get("name") or "").strip()
        if not selector_name:
            continue
        selector_formula = _first_version_formula(selector_rule)
        if not selector_formula:
            continue
        bound_rules = [
            rule
            for rule in rules
            if isinstance(rule, dict)
            and selector_name in _rulespec_indexed_by_names(rule.get("indexed_by"))
            and _looks_like_interval_bound_parameter(rule)
        ]
        bound_names = frozenset(
            str(rule.get("name") or "").strip()
            for rule in bound_rules
            if str(rule.get("name") or "").strip()
        )
        lower_bound_rule = _interval_bound_parameter_rule(bound_rules, side="lower")
        upper_bound_rule = _interval_bound_parameter_rule(bound_rules, side="upper")
        lower_bound_name = _interval_bound_parameter_rule_name(
            lower_bound_rule,
            selector_name=selector_name,
            side="lower",
        )
        upper_bound_name = _interval_bound_parameter_rule_name(
            upper_bound_rule,
            selector_name=selector_name,
            side="upper",
        )

        output_rules = [
            rule
            for rule in rules
            if isinstance(rule, dict)
            and str(rule.get("kind") or "").strip().lower() == "parameter"
            and selector_name in _rulespec_indexed_by_names(rule.get("indexed_by"))
            and not _looks_like_interval_bound_parameter(rule)
        ]
        output_rules = _ordered_interval_output_parameter_rules(
            output_rules,
            source_table.output_headers,
        )
        if len(output_rules) != len(source_table.rows[0].outputs):
            continue

        input_name = _infer_interval_selector_input_name(
            selector_formula,
            selector_name,
            bound_names,
        )
        if not input_name:
            continue
        specs.append(
            _IntervalAlignmentSpec(
                selector_name=selector_name,
                input_name=input_name,
                rows=source_table.rows,
                lower_bound_parameter_name=lower_bound_name,
                upper_bound_parameter_name=upper_bound_name,
                lower_bound_parameter_rule=lower_bound_rule,
                upper_bound_parameter_rule=upper_bound_rule,
                output_parameter_names=tuple(
                    str(rule.get("name") or "").strip() for rule in output_rules
                ),
                output_parameter_rules=tuple(output_rules),
            )
        )
    return specs


def _parse_interval_source_table(text: str | None) -> _IntervalSourceTable | None:
    if not text:
        return None
    output_headers: tuple[str, ...] = ()
    rows: list[_IntervalSourceRow] = []
    for line in text.splitlines():
        cells = _source_table_cells(line)
        if not cells:
            continue
        row_key_index = _find_interval_row_key_header_index(cells)
        if row_key_index is not None and row_key_index + 2 < len(cells):
            candidate_headers = tuple(cells[row_key_index + 2 :])
            if candidate_headers and not _cells_look_like_interval_row(
                candidate_headers
            ):
                output_headers = candidate_headers
            elif candidate_headers:
                compact_headers = _compact_interval_output_headers(
                    cells,
                    row_key_index,
                )
                compact_rows = _compact_interval_rows_from_cells(
                    candidate_headers,
                    output_count=len(compact_headers) or None,
                )
                if compact_rows:
                    if compact_headers:
                        output_headers = compact_headers
                    rows.extend(compact_rows)
                    continue
        row_cells = _interval_row_cells_from_cells(cells)
        if row_cells is None:
            continue
        lower, upper, outputs = row_cells
        rows.append(_IntervalSourceRow(lower=lower, upper=upper, outputs=outputs))
    if not rows:
        return None
    output_count = len(rows[0].outputs)
    if output_count == 0 or any(len(row.outputs) != output_count for row in rows):
        return None
    if output_headers and len(output_headers) != output_count:
        output_headers = ()
    return _IntervalSourceTable(output_headers=output_headers, rows=tuple(rows))


def _source_table_cells(line: str) -> list[str]:
    if "|" not in line:
        return []
    return [cell.strip() for cell in line.split("|") if cell.strip()]


def _compact_interval_output_headers(
    cells: list[str],
    row_key_index: int,
) -> tuple[str, ...]:
    prefix = cells[:row_key_index]
    separator_index = next(
        (
            index
            for index, cell in enumerate(prefix)
            if _is_markdown_separator_cell(cell)
        ),
        None,
    )
    if separator_index is not None:
        prefix = prefix[:separator_index]
    prefix = [cell for cell in prefix if not _is_markdown_separator_cell(cell)]
    return tuple(prefix[2:]) if len(prefix) > 2 else ()


def _compact_interval_rows_from_cells(
    cells: tuple[str, ...],
    *,
    output_count: int | None,
) -> list[_IntervalSourceRow]:
    output_counts = [output_count] if output_count else list(range(1, 8))
    for candidate_output_count in output_counts:
        group_size = candidate_output_count + 2
        if group_size <= 2 or len(cells) % group_size != 0:
            continue
        rows: list[_IntervalSourceRow] = []
        valid = True
        for start in range(0, len(cells), group_size):
            group = cells[start : start + group_size]
            lower = _parse_interval_bound_cell(group[0])
            upper = _parse_interval_bound_cell(group[1])
            if lower is _UNPARSED_BOUND or upper is _UNPARSED_BOUND:
                valid = False
                break
            outputs = tuple(group[2:])
            if any(_parse_source_numeric_cell(output) is None for output in outputs):
                valid = False
                break
            rows.append(
                _IntervalSourceRow(
                    lower=lower,
                    upper=upper,
                    outputs=outputs,
                )
            )
        if valid and len(rows) > 1:
            return rows
    return []


def _is_markdown_separator_cell(cell: str) -> bool:
    return bool(re.fullmatch(r":?-{2,}:?", cell.strip()))


def _find_interval_row_key_header_index(cells: list[str]) -> int | None:
    for index in range(0, len(cells) - 1):
        if (
            _normalized_text(cells[index]) == "atleast"
            and _normalized_text(cells[index + 1]) == "butlessthan"
        ):
            return index
    return None


def _interval_row_cells_from_cells(
    cells: list[str],
) -> tuple[str | None, str | None, tuple[str, ...]] | None:
    row_key_index = _find_interval_row_key_header_index(cells)
    if row_key_index is not None:
        cells = cells[row_key_index + 2 :]
    for start in range(0, max(1, len(cells) - 2)):
        lower = _parse_interval_bound_cell(cells[start])
        upper = (
            _parse_interval_bound_cell(cells[start + 1])
            if start + 1 < len(cells)
            else _UNPARSED_BOUND
        )
        if lower is _UNPARSED_BOUND or upper is _UNPARSED_BOUND:
            continue
        outputs = tuple(
            cell
            for cell in cells[start + 2 :]
            if _parse_source_numeric_cell(cell) is not None
        )
        if outputs:
            return lower, upper, outputs
    return None


_UNPARSED_BOUND = object()


def _parse_interval_bound_cell(cell: str) -> str | None | object:
    normalized = cell.strip()
    if not normalized or re.fullmatch(r"[.\u2026]+", normalized):
        return None
    return (
        normalized
        if _parse_source_numeric_cell(normalized) is not None
        else _UNPARSED_BOUND
    )


def _parse_source_numeric_cell(cell: str) -> float | None:
    normalized = cell.strip().replace(",", "")
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", normalized):
        return None
    with contextlib.suppress(ValueError):
        return float(normalized)
    return None


def _cells_look_like_interval_row(cells: tuple[str, ...]) -> bool:
    return bool(cells and _parse_interval_bound_cell(cells[0]) is not _UNPARSED_BOUND)


def _rulespec_module_summary(payload: dict[str, Any]) -> str:
    module = payload.get("module")
    if not isinstance(module, dict):
        return ""
    summary = module.get("summary")
    return summary if isinstance(summary, str) else ""


def _looks_like_interval_bound_parameter(rule: dict[str, Any]) -> bool:
    return _looks_like_interval_lower_bound_parameter(
        rule
    ) or _looks_like_open_ended_upper_bound_parameter(rule)


def _interval_bound_parameter_rule(
    bound_rules: list[dict[str, Any]],
    *,
    side: str,
) -> dict[str, Any] | None:
    predicate = (
        _looks_like_interval_lower_bound_parameter
        if side == "lower"
        else _looks_like_open_ended_upper_bound_parameter
    )
    matches = [rule for rule in bound_rules if predicate(rule)]
    return matches[0] if matches else None


def _interval_bound_parameter_rule_name(
    rule: dict[str, Any] | None,
    *,
    selector_name: str,
    side: str,
) -> str | None:
    if rule is not None:
        name = str(rule.get("name") or "").strip()
        if name:
            return name
    return f"{selector_name}_{side}_bound"


def _looks_like_interval_lower_bound_parameter(rule: dict[str, Any]) -> bool:
    name = str(rule.get("name") or "").strip().lower()
    text = _interval_parameter_text(rule)
    return bool(
        re.search(r"\bat\s+least\b", text)
        or re.search(r"(?:^|_)(?:lower|minimum|min)(?:_|$)", name)
    )


def _interval_parameter_text(rule: dict[str, Any]) -> str:
    name = str(rule.get("name") or "").strip().lower()
    text_parts = [name]
    metadata = rule.get("metadata")
    if isinstance(metadata, dict):
        proof = metadata.get("proof")
        if isinstance(proof, dict):
            atoms = proof.get("atoms")
            if isinstance(atoms, list):
                for atom in atoms:
                    if not isinstance(atom, dict):
                        continue
                    source = atom.get("source")
                    if not isinstance(source, dict):
                        continue
                    table = source.get("table")
                    if not isinstance(table, dict):
                        continue
                    for key in ("header", "row_key", "column_key"):
                        value = table.get(key)
                        if isinstance(value, str):
                            text_parts.append(value.lower())
    return " ".join(text_parts)


def _ordered_interval_output_parameter_rules(
    output_rules: list[dict[str, Any]],
    output_headers: tuple[str, ...],
) -> list[dict[str, Any]]:
    if not output_headers or len(output_headers) != len(output_rules):
        return output_rules
    indexed: list[tuple[int, dict[str, Any]]] = []
    used_indexes: set[int] = set()
    for rule in output_rules:
        rule_text = _normalized_text(_interval_parameter_text(rule))
        matches = [
            index
            for index, header in enumerate(output_headers)
            if _normalized_text(header)
            and (
                _normalized_text(header) in rule_text
                or rule_text in _normalized_text(header)
            )
        ]
        if len(matches) != 1 or matches[0] in used_indexes:
            return output_rules
        used_indexes.add(matches[0])
        indexed.append((matches[0], rule))
    return [rule for _index, rule in sorted(indexed, key=lambda item: item[0])]


def _normalized_text(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.lower())


def _first_version_formula(rule: dict[str, Any]) -> str | None:
    versions = rule.get("versions")
    if not isinstance(versions, list) or not versions:
        return None
    first_version = versions[0]
    if not isinstance(first_version, dict):
        return None
    formula = first_version.get("formula")
    return formula if isinstance(formula, str) else None


def _infer_interval_selector_input_name(
    formula: str,
    selector_name: str,
    bound_names: frozenset[str],
) -> str | None:
    for bound_name in sorted(bound_names, key=len, reverse=True):
        match = re.search(
            rf"\b([A-Za-z_][A-Za-z0-9_]*)\b\s*(?:[<>]=?|==)\s*{re.escape(bound_name)}\s*\[",
            formula,
        )
        if match:
            return match.group(1)
        match = re.search(
            rf"{re.escape(bound_name)}\s*\[[^\]]+\]\s*(?:[<>]=?|==)\s*\b([A-Za-z_][A-Za-z0-9_]*)\b",
            formula,
        )
        if match:
            return match.group(1)
    suffix_match = re.match(r"(.+?)_(?:band|bracket|tier|index)$", selector_name)
    return suffix_match.group(1) if suffix_match else None


def _build_interval_selector_formula(
    *,
    input_name: str,
    rows: tuple[_IntervalSourceRow, ...],
    lower_bound_name: str | None = None,
    upper_bound_name: str | None = None,
) -> str | None:
    if not rows:
        return None
    tail = "0"
    rows_to_chain = list(enumerate(rows, start=1))
    if _interval_rows_are_contiguous(rows) and rows[-1].upper is None:
        tail = str(len(rows))
        rows_to_chain = rows_to_chain[:-1]
    for row_index, row in reversed(rows_to_chain):
        condition = _interval_row_condition(
            input_name,
            row,
            row_index=row_index,
            lower_bound_name=lower_bound_name,
            upper_bound_name=upper_bound_name,
        )
        if not condition:
            tail = str(row_index)
            continue
        tail = f"if {condition}: {row_index} else: {tail}"
    return tail


def _interval_rows_are_contiguous(rows: tuple[_IntervalSourceRow, ...]) -> bool:
    if len(rows) < 2:
        return False
    for previous, current in zip(rows, rows[1:]):
        if previous.upper is None or current.lower is None:
            return False
        if not math.isclose(
            float(previous.upper),
            float(current.lower),
            rel_tol=0,
            abs_tol=1e-12,
        ):
            return False
    return True


def _interval_row_condition(
    input_name: str,
    row: _IntervalSourceRow,
    *,
    row_index: int | None = None,
    lower_bound_name: str | None = None,
    upper_bound_name: str | None = None,
) -> str | None:
    parts: list[str] = []
    if row.lower is not None:
        lower_bound = (
            f"{lower_bound_name}[{row_index}]"
            if lower_bound_name is not None and row_index is not None
            else row.lower
        )
        parts.append(f"{input_name} >= {lower_bound}")
    if row.upper is not None:
        upper_bound = (
            f"{upper_bound_name}[{row_index}]"
            if upper_bound_name is not None and row_index is not None
            else row.upper
        )
        parts.append(f"{input_name} < {upper_bound}")
    return " and ".join(parts) if parts else None


def _ensure_interval_bound_parameter_rule(
    rules: list[Any],
    *,
    spec: _IntervalAlignmentSpec,
    selector_rule: dict[str, Any],
    selector_version: dict[str, Any],
    side: str,
) -> tuple[str | None, bool]:
    values = _interval_bound_values(spec.rows, side=side)
    if not values:
        return None, False
    existing_rule = (
        spec.lower_bound_parameter_rule
        if side == "lower"
        else spec.upper_bound_parameter_rule
    )
    name = (
        spec.lower_bound_parameter_name
        if side == "lower"
        else spec.upper_bound_parameter_name
    )
    if not name:
        name = f"{spec.selector_name}_{side}_bound"

    if existing_rule is None:
        new_rule: dict[str, Any] = {
            "name": name,
            "kind": "parameter",
            "dtype": "Decimal",
            "indexed_by": spec.selector_name,
            "versions": [
                {
                    "effective_from": selector_version.get(
                        "effective_from", "1900-01-01"
                    ),
                    "values": values,
                }
            ],
        }
        if selector_rule.get("source") is not None:
            new_rule["source"] = selector_rule.get("source")
        with contextlib.suppress(ValueError):
            selector_index = rules.index(selector_rule)
            rules.insert(selector_index, new_rule)
            return name, True
        rules.append(new_rule)
        return name, True

    changed = False
    if str(existing_rule.get("kind") or "").strip().lower() != "parameter":
        existing_rule["kind"] = "parameter"
        changed = True
    if existing_rule.get("indexed_by") != spec.selector_name:
        existing_rule["indexed_by"] = spec.selector_name
        changed = True
    versions = existing_rule.get("versions")
    if not isinstance(versions, list) or not versions:
        existing_rule["versions"] = [
            {
                "effective_from": selector_version.get("effective_from", "1900-01-01"),
                "values": values,
            }
        ]
        return name, True
    first_version = versions[0]
    if not isinstance(first_version, dict):
        versions[0] = {
            "effective_from": selector_version.get("effective_from", "1900-01-01"),
            "values": values,
        }
        return name, True
    if "effective_from" not in first_version and "effective_from" in selector_version:
        first_version["effective_from"] = selector_version["effective_from"]
        changed = True
    if first_version.get("values") != values:
        first_version["values"] = values
        changed = True
    return name, changed


def _interval_bound_values(
    rows: tuple[_IntervalSourceRow, ...],
    *,
    side: str,
) -> dict[int, int | float]:
    values: dict[int, int | float] = {}
    for row_index, row in enumerate(rows, start=1):
        raw_value = row.lower if side == "lower" else row.upper
        if raw_value is None:
            continue
        coerced = _coerce_interval_source_bound_value(raw_value)
        if coerced is not None:
            values[row_index] = coerced
    return values


def _coerce_interval_source_bound_value(raw_value: str) -> int | float | None:
    normalized = raw_value.strip().replace(",", "")
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", normalized):
        return None
    with contextlib.suppress(ValueError):
        if "." not in normalized:
            return int(normalized)
        return float(normalized)
    return None


def _coerce_interval_source_output_value(
    raw_value: str,
    rule: dict[str, Any],
) -> float:
    value = _parse_source_numeric_cell(raw_value)
    if value is None:
        return 0.0
    dtype = str(rule.get("dtype") or "").strip().lower()
    name = str(rule.get("name") or "").strip().lower()
    parameter_text = _interval_parameter_text(rule)
    percentage_labeled = (
        "percentage" in name
        or "percent" in name
        or re.search(r"\bpercent(?:age)?\b", parameter_text) is not None
    )
    if percentage_labeled and value != 0:
        value = value / 100
    elif dtype == "rate" and abs(value) > 1:
        value = value / 100
    return round(value, 12)


def _test_input_value_for_name(inputs: dict[Any, Any], input_name: str) -> Any:
    for key, value in inputs.items():
        key_text = str(key)
        if key_text == input_name:
            return value
        if key_text.endswith(f"#input.{input_name}") or key_text.endswith(
            f"#{input_name}"
        ):
            return value
    return None


def _interval_selector_key_for_value(
    input_value: float,
    rows: tuple[_IntervalSourceRow, ...],
) -> int | None:
    for row_index, row in enumerate(rows, start=1):
        lower_ok = row.lower is None or input_value >= float(row.lower)
        upper_ok = row.upper is None or input_value < float(row.upper)
        if lower_ok and upper_ok:
            return row_index
    return None


def _interval_expected_outputs_for_key(
    payload: dict[str, Any],
    spec: _IntervalAlignmentSpec,
    selector_key: int,
) -> dict[str, Any]:
    expected: dict[str, Any] = {spec.selector_name: selector_key}
    parameter_values = _interval_parameter_values_by_name(payload, spec)
    for parameter_name, values in parameter_values.items():
        if selector_key in values:
            expected[parameter_name] = values[selector_key]

    derived_to_parameter = _interval_derived_output_parameter_map(payload, spec)
    for derived_name, parameter_name in derived_to_parameter.items():
        values = parameter_values.get(parameter_name)
        if values and selector_key in values:
            expected[derived_name] = values[selector_key]
    return expected


def _interval_parameter_values_by_name(
    payload: dict[str, Any],
    spec: _IntervalAlignmentSpec,
) -> dict[str, dict[int, Any]]:
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return {}
    output_names = set(spec.output_parameter_names)
    values_by_name: dict[str, dict[int, Any]] = {}
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        name = str(rule.get("name") or "").strip()
        if name not in output_names:
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list) or not versions:
            continue
        version = versions[0]
        if not isinstance(version, dict) or not isinstance(version.get("values"), dict):
            continue
        values: dict[int, Any] = {}
        for key, value in version["values"].items():
            normalized_key = _structural_integer_key(key)
            if normalized_key is None:
                continue
            values[int(normalized_key)] = value
        values_by_name[name] = values
    return values_by_name


def _interval_derived_output_parameter_map(
    payload: dict[str, Any],
    spec: _IntervalAlignmentSpec,
) -> dict[str, str]:
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return {}
    direct: dict[str, str] = {}
    aliases: dict[str, str] = {}
    output_names = set(spec.output_parameter_names)
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").strip().lower() != "derived":
            continue
        name = str(rule.get("name") or "").strip()
        formula = re.sub(r"\s+", " ", (_first_version_formula(rule) or "").strip())
        lookup_pattern = (
            rf"([A-Za-z_][A-Za-z0-9_]*)\s*"
            rf"\[\s*{re.escape(spec.selector_name)}\s*\]"
        )
        lookup_match = re.fullmatch(lookup_pattern, formula)
        if lookup_match and lookup_match.group(1) in output_names:
            direct[name] = lookup_match.group(1)
            continue
        guarded_lookup_match = re.fullmatch(
            rf"if\s+{re.escape(spec.selector_name)}\s*(?:==|=)\s*0\s*:\s*"
            rf"0(?:\.0)?\s+else:\s*{lookup_pattern}",
            formula,
        )
        if guarded_lookup_match and guarded_lookup_match.group(1) in output_names:
            direct[name] = guarded_lookup_match.group(1)
            continue
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", formula):
            aliases[name] = formula

    changed = True
    while changed:
        changed = False
        for alias_name, target_name in aliases.items():
            target_parameter = direct.get(target_name)
            if (
                target_parameter is not None
                and direct.get(alias_name) != target_parameter
            ):
                direct[alias_name] = target_parameter
                changed = True
    return direct


def _rulespec_test_reference_local_name(key: object) -> str | None:
    if not isinstance(key, str):
        return None
    if "#" in key:
        return key.rsplit("#", 1)[1].strip() or None
    return key.strip() or None


def _looks_like_open_ended_upper_bound_parameter(rule: dict[str, Any]) -> bool:
    name = str(rule.get("name") or "").strip().lower()
    text = _interval_parameter_text(rule)
    return bool(
        re.search(r"\bbut\s+less\s+than\b", text)
        or re.search(r"\bless\s+than\b", text)
        or re.search(r"(?:^|_)(?:upper|maximum|max)(?:_|$)", name)
    )


def _max_structural_integer_table_key(values: dict[Any, Any]) -> Any | None:
    keyed: list[tuple[int, Any]] = []
    for key in values:
        normalized = _structural_integer_key(key)
        if normalized is None:
            continue
        with contextlib.suppress(ValueError):
            keyed.append((int(normalized), key))
    if not keyed:
        return None
    return max(keyed, key=lambda item: item[0])[1]


def _is_generated_open_ended_bound_sentinel(
    value: float,
    source_occurrences: Sequence[NumericOccurrence],
) -> bool:
    if abs(value) < 1_000_000:
        return False
    if source_occurrences and numeric_value_is_grounded(value, source_occurrences):
        return False
    return True


def _is_source_table_structural_bound_parameter_name(name: str) -> bool:
    normalized = name.strip().lower()
    if not normalized:
        return False
    has_index = re.search(r"(?:^|_)(?:row|band|bracket)_\d+(?:_|$)", normalized)
    has_bound_word = re.search(
        r"(?:^|_)(?:lower|upper)(?:_bound|_threshold|_limit)?(?:_|$)",
        normalized,
    )
    has_structural_noun = re.search(
        r"(?:^|_)(?:bound|threshold|limit)(?:_|$)", normalized
    )
    has_adjacent_min_max = re.search(
        r"(?:^|_)(?:row|band|bracket)_\d+_(?:min|max|minimum|maximum)(?:_|$)",
        normalized,
    ) or re.search(
        r"(?:^|_)(?:min|max|minimum|maximum)_(?:row|band|bracket)_\d+(?:_|$)",
        normalized,
    )
    has_adjacent_lower_upper = re.search(
        r"(?:^|_)(?:row|band|bracket)_\d+_(?:lower|upper)(?:_|$)",
        normalized,
    ) or re.search(
        r"(?:^|_)(?:lower|upper)_(?:row|band|bracket)_\d+(?:_|$)",
        normalized,
    )
    has_named_band_bound = re.search(
        r"(?:^|_)(?:band|bracket)_(?:bound|threshold|limit)_\d",
        normalized,
    ) or re.search(
        r"(?:^|_)(?:bound|threshold|limit)_(?:band|bracket)_\d",
        normalized,
    )
    return bool(
        (
            has_index
            and (
                (has_bound_word and has_structural_noun)
                or has_adjacent_min_max
                or has_adjacent_lower_upper
            )
        )
        or has_named_band_bound
    )


def _formula_references_identifier(formula: str, identifier: str) -> bool:
    return (
        re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(identifier)}(?![A-Za-z0-9_])",
            formula,
        )
        is not None
    )


def _repair_else_if_formula(formula: str) -> str:
    branches = _parse_multiline_else_if_formula(formula)
    if branches is None:
        return formula

    tail = branches[-1][1]
    for condition, result in reversed(branches[:-1]):
        tail = f"if {condition}: {result} else: {tail}"
    return tail


def _repair_then_conditional_formula(formula: str) -> str:
    compact = " ".join(line.strip() for line in formula.strip().splitlines())
    match = re.fullmatch(
        r"if\s+(?P<condition>.+?)\s+then:\s+"
        r"(?P<true_result>.+?)\s+else:\s+(?P<false_result>.+)",
        compact,
    )
    if match is None:
        return formula

    true_result = match["true_result"].strip()
    false_result = match["false_result"].strip()
    if re.match(r"(?:if|elif|else\b)", true_result) or re.match(
        r"(?:elif|else\b)", false_result
    ):
        return formula
    return f"if {match['condition'].strip()}: {true_result} else: {false_result}"


def _repair_python_ternary_formula(formula: str) -> str:
    compact = " ".join(line.strip() for line in formula.strip().splitlines())
    if compact.startswith("if "):
        return formula
    match = re.fullmatch(
        r"(?P<true_result>.+?)\s+if\s+(?P<condition>.+?)\s+else\s+"
        r"(?P<false_result>.+)",
        compact,
    )
    if match is None:
        return formula

    true_result = match["true_result"].strip()
    condition = match["condition"].strip()
    false_result = match["false_result"].strip()
    if not true_result or not condition or not false_result:
        return formula
    if re.search(r"\b(?:if|else)\b", true_result) or re.search(
        r"\b(?:if|else)\b", false_result
    ):
        return formula
    return f"if {condition}: {true_result} else: {false_result}"


def _parse_multiline_else_if_formula(
    formula: str,
) -> list[tuple[str | None, str]] | None:
    lines = [line.rstrip() for line in formula.strip().splitlines() if line.strip()]
    if len(lines) < 2:
        return None

    def collect_block_result(start: int) -> tuple[str, int] | None:
        result_lines: list[str] = []
        index = start
        while index < len(lines):
            stripped = lines[index].strip()
            if result_lines and re.fullmatch(
                r"(?:if|elif|else\s+if)\b.*|else:",
                stripped,
            ):
                break
            if not result_lines and re.match(r"(?:if|elif|else\b)", stripped):
                return None
            result_lines.append(stripped)
            index += 1

        result = " ".join(result_lines).strip()
        if not result or re.match(r"(?:if|elif|else\b)", result):
            return None
        return result, index

    branches: list[tuple[str | None, str]] = []
    index = 0
    while index < len(lines):
        collected_header = _collect_multiline_conditional_header(lines, index)
        if collected_header is None:
            return None
        header, next_index = collected_header
        inline_if_match = re.fullmatch(
            r"(?:if|elif|else\s+if)\s+(.+?):\s*(.+)",
            header,
        )
        if inline_if_match is not None:
            result = inline_if_match.group(2).strip()
            if not result or re.match(r"(?:elif|else\b)", result):
                return None
            branches.append((inline_if_match.group(1).strip(), result))
            index = next_index
            continue
        inline_else_match = re.fullmatch(r"else:\s*(.+)", header)
        if inline_else_match is not None:
            result = inline_else_match.group(1).strip()
            if not result or re.match(r"(?:if|elif|else\b)", result):
                return None
            branches.append((None, result))
            index = next_index
            break
        if_match = re.fullmatch(r"(?:if|elif|else\s+if)\s+(.+):", header)
        if if_match is not None:
            collected = collect_block_result(next_index)
            if collected is None:
                return None
            result, index = collected
            branches.append((if_match.group(1).strip(), result))
            continue
        if header == "else:":
            collected = collect_block_result(next_index)
            if collected is None:
                return None
            result, index = collected
            branches.append((None, result))
            break
        return None

    if index != len(lines):
        return None
    if len(branches) < 2 or branches[-1][0] is not None:
        return None
    if not any(condition is not None for condition, _result in branches):
        return None
    return branches


def _collect_multiline_conditional_header(
    lines: list[str],
    index: int,
) -> tuple[str, int] | None:
    header = lines[index].strip()
    if not re.match(r"(?:if|elif|else\s+if)\b", header) or ":" in header:
        return header, index + 1

    parts = [header]
    cursor = index + 1
    while cursor < len(lines):
        part = lines[cursor].strip()
        if re.match(r"(?:if|elif|else\s+if)\b|else:", part):
            return None
        parts.append(part)
        cursor += 1
        if ":" in part:
            return " ".join(parts), cursor
    return None


def _formula_has_unsupported_chained_conditional(formula: str) -> bool:
    return bool(re.search(r"(?:^|\s)(?:elif|else\s+if)\b", formula))


def _source_text_looks_like_table(source_text: str) -> bool:
    money_cells = re.findall(r"\$\s*[\d,]+(?:\.\d+)?", source_text)
    return bool(
        re.search(r"\btable\b", source_text, flags=re.IGNORECASE)
        or source_text.count("|") >= 6
        or (
            re.search(r"\bschedule\b", source_text, flags=re.IGNORECASE)
            and source_text.count("|") >= 2
        )
        or (
            re.search(
                r"\b(?:household|family|assistance\s+unit)\s+size\b",
                source_text,
                flags=re.IGNORECASE,
            )
            and len(money_cells) >= 2
        )
    )


def find_versioned_derived_formula_issues(content: str) -> list[str]:
    """Return versioned-derived issues.

    Versioned derived formulas are supported by the Axiom runtime. This hook is
    retained so older manifests and callers can keep invoking the same
    validation surface without special-casing the capability transition.
    """
    return []


def find_local_dependency_temporal_coverage_issues(content: str) -> list[str]:
    """Flag formula versions not covered by their direct local dependencies.

    This intentionally considers only direct, same-file rule references. It does
    not infer coverage through imports or through arbitrary formula expressions.
    """

    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, TypeError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    raw_rules = payload.get("rules")
    if not isinstance(raw_rules, list):
        return []
    rules = {
        str(rule.get("name") or "").strip(): rule
        for rule in raw_rules
        if isinstance(rule, dict) and str(rule.get("name") or "").strip()
    }

    coverage_by_rule: dict[str, tuple[tuple[date, date | None], ...]] = {}
    for name, rule in rules.items():
        intervals = [
            (effective_from, effective_to)
            for _index, _version, effective_from, effective_to in (
                _rule_effective_intervals(rule)
            )
        ]
        if intervals:
            coverage_by_rule[name] = tuple(sorted(intervals))

    issues: list[str] = []
    for name, rule in rules.items():
        if str(rule.get("kind") or "").strip().lower() not in {
            "derived",
            "derived_relation",
        }:
            continue
        for index, version, effective_from, effective_to in _rule_effective_intervals(
            rule
        ):
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            for dependency in sorted(
                _formula_local_identifiers(formula) & coverage_by_rule.keys()
            ):
                if _interval_is_covered(
                    effective_from,
                    effective_to,
                    coverage_by_rule[dependency],
                ):
                    continue
                consumer_end = (
                    effective_to.isoformat()
                    if effective_to is not None
                    else "unbounded"
                )
                issues.append(
                    "[temporal-dependency-coverage] Derived rule "
                    f"`{name}` version {index + 1} covers "
                    f"{effective_from.isoformat()} through {consumer_end} but "
                    f"directly references local rule `{dependency}`, whose "
                    "version intervals "
                    f"({_format_effective_intervals(coverage_by_rule[dependency])}) "
                    "do not cover that entire period. Align "
                    "the derived interval, extend the dependency with "
                    "authoritative coverage, or add a later derived version."
                )
    return issues


def _rule_effective_intervals(
    rule: Mapping[str, object],
) -> tuple[tuple[int, dict[str, Any], date, date | None], ...]:
    """Return explicit or next-version-bounded inclusive rule intervals."""

    versions = rule.get("versions")
    if not isinstance(versions, list):
        return ()
    dated: list[tuple[int, dict[str, Any], date]] = []
    for index, version in enumerate(versions):
        if not isinstance(version, dict):
            continue
        try:
            effective_from = date.fromisoformat(str(version["effective_from"]).strip())
        except (KeyError, TypeError, ValueError):
            continue
        dated.append((index, version, effective_from))
    dated.sort(key=lambda item: (item[2], item[0]))

    intervals: list[tuple[int, dict[str, Any], date, date | None]] = []
    for position, (index, version, effective_from) in enumerate(dated):
        raw_effective_to = version.get("effective_to")
        if raw_effective_to not in (None, ""):
            try:
                effective_to = date.fromisoformat(str(raw_effective_to).strip())
            except (TypeError, ValueError):
                continue
        elif position + 1 < len(dated):
            next_effective_from = dated[position + 1][2]
            if next_effective_from <= effective_from:
                continue
            effective_to = date.fromordinal(next_effective_from.toordinal() - 1)
        else:
            effective_to = None
        if effective_to is not None and effective_to < effective_from:
            continue
        intervals.append((index, version, effective_from, effective_to))
    return tuple(intervals)


def _format_effective_intervals(
    intervals: Sequence[tuple[date, date | None]],
) -> str:
    return ", ".join(
        f"{effective_from.isoformat()} through "
        f"{effective_to.isoformat() if effective_to is not None else 'unbounded'}"
        for effective_from, effective_to in intervals
    )


def _interval_is_covered(
    required_from: date,
    required_to: date | None,
    available: Sequence[tuple[date, date | None]],
) -> bool:
    """Return whether inclusive version intervals cover one required interval."""

    cursor = required_from
    for available_from, available_to in available:
        if available_to is not None and available_to < cursor:
            continue
        if available_from > cursor:
            return False
        if available_to is None:
            return True
        if required_to is not None and available_to >= required_to:
            return True
        if available_to == date.max:
            return required_to is not None and available_to >= required_to
        cursor = date.fromordinal(available_to.toordinal() + 1)
    return False


def _contract_sequence(value: object) -> tuple[str, ...]:
    if isinstance(value, list):
        return tuple(str(item).strip() for item in value if str(item).strip())
    if value is None:
        return ()
    text = str(value).strip()
    return (text,) if text else ()


def _existing_target_surface_contract(
    rule: Mapping[str, object],
) -> ExistingTargetSurfaceContract | None:
    name = str(rule.get("name") or "").strip()
    kind = str(rule.get("kind") or "").strip().lower()
    dtype = str(rule.get("dtype") or "").strip()
    versions = rule.get("versions")
    if (
        not name
        or kind not in {"parameter", "derived", "derived_relation", "data_relation"}
        or not dtype
        or not isinstance(versions, list)
        or not versions
    ):
        return None
    metadata = rule.get("metadata")
    return ExistingTargetSurfaceContract(
        name=name,
        kind=kind,
        entity=str(rule.get("entity") or "").strip(),
        dtype=dtype,
        period=str(rule.get("period") or "").strip(),
        unit=str(rule.get("unit") or "").strip(),
        indexed_by=_contract_sequence(rule.get("indexed_by")),
        private=(isinstance(metadata, Mapping) and metadata.get("private") is True),
    )


def _existing_target_input_contract(
    item: Mapping[str, object],
) -> ExistingTargetInputContract | None:
    name = str(item.get("name") or "").strip()
    dtype = str(item.get("dtype") or "").strip()
    if not name or not dtype:
        return None
    return ExistingTargetInputContract(
        name=name,
        entity=str(item.get("entity") or "").strip(),
        dtype=dtype,
        period=str(item.get("period") or "").strip(),
        unit=str(item.get("unit") or "").strip(),
    )


_REPLACEMENT_LEGAL_SOURCE_NAME_MARKERS = frozenset(
    {
        "article",
        "chapter",
        "code",
        "cfr",
        "krs",
        "regulation",
        "section",
        "statute",
        "title",
        "usc",
    }
)
_REPLACEMENT_LEGAL_SOURCE_FRAGMENT = re.compile(r"[0-9]+[a-z]*", re.IGNORECASE)


def _replacement_target_name_identity(target: str) -> str:
    """Return a narrow year/source identity repeated by legacy target names."""

    target_path = target.partition(":")[2] or target
    basename = Path(target_path).name
    tokens = tuple(token for token in basename.lower().split("_") if token)
    if len(tokens) < 3 or re.fullmatch(r"(?:19|20)\d{2}", tokens[0]) is None:
        return ""
    if tokens[1] not in _REPLACEMENT_LEGAL_SOURCE_NAME_MARKERS:
        return ""
    identity = list(tokens[:2])
    for token in tokens[2:]:
        if _REPLACEMENT_LEGAL_SOURCE_FRAGMENT.fullmatch(token) is None:
            break
        identity.append(token)
    if len(identity) < 3:
        return ""
    return "_".join(identity)


def _rule_name_contains_token_sequence(name: str, sequence: str) -> bool:
    """Return whether one snake-case name contains an exact token sequence."""

    name_tokens = tuple(token for token in name.lower().split("_") if token)
    sequence_tokens = tuple(token for token in sequence.split("_") if token)
    if not sequence_tokens or len(sequence_tokens) > len(name_tokens):
        return False
    width = len(sequence_tokens)
    return any(
        name_tokens[index : index + width] == sequence_tokens
        for index in range(len(name_tokens) - width + 1)
    )


def build_existing_target_oracle_contract(
    content: str,
    *,
    target: str,
    policyengine_registry: object,
    invalid_input_names: Iterable[str] = (),
) -> ExistingTargetOracleContract | None:
    """Build the replacement contract for valid exact registry-owned exports."""

    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, TypeError, ValueError):
        return None
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return None
    raw_rules = payload.get("rules")
    if not isinstance(raw_rules, list):
        return None
    rules = {
        str(rule.get("name") or "").strip(): rule
        for rule in raw_rules
        if isinstance(rule, dict) and str(rule.get("name") or "").strip()
    }
    exact_mappings = getattr(policyengine_registry, "mappings_by_legal_id", {})
    if not isinstance(exact_mappings, dict):
        return None
    surface_names = sorted(
        name for name in rules if f"{target}#{name}" in exact_mappings
    )
    surfaces = tuple(
        surface
        for name in surface_names
        if (surface := _existing_target_surface_contract(rules[name])) is not None
    )
    if not surfaces:
        return None

    explicit_inputs: dict[str, ExistingTargetInputContract] = {}
    raw_inputs = payload.get("inputs")
    if isinstance(raw_inputs, list):
        for item in raw_inputs:
            if not isinstance(item, dict):
                continue
            contract = _existing_target_input_contract(item)
            if contract is not None:
                explicit_inputs[contract.name] = contract

    reachable_rules = {surface.name for surface in surfaces}
    reachable_identifiers: set[str] = set()
    pending = list(reachable_rules)
    while pending:
        rule_name = pending.pop()
        rule = rules.get(rule_name)
        if not isinstance(rule, dict):
            continue
        reachable_identifiers.update(_contract_sequence(rule.get("indexed_by")))
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        for version in versions:
            formula = version.get("formula") if isinstance(version, dict) else None
            if not isinstance(formula, str):
                continue
            identifiers = _formula_local_identifiers(formula)
            reachable_identifiers.update(identifiers)
            for dependency in identifiers & rules.keys() - reachable_rules:
                reachable_rules.add(dependency)
                pending.append(dependency)

    invalid = set(invalid_input_names)
    inputs = tuple(
        explicit_inputs[name]
        for name in sorted(reachable_identifiers & explicit_inputs.keys() - invalid)
    )
    return ExistingTargetOracleContract(
        target,
        surfaces,
        inputs,
        _replacement_target_name_identity(target),
    )


def find_existing_target_oracle_contract_issues(
    content: str,
    contract: ExistingTargetOracleContract | None,
) -> list[str]:
    """Require a replacement to retain registry-owned names and input schemas."""

    if contract is None:
        return []
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, TypeError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    raw_rules = payload.get("rules")
    raw_inputs = payload.get("inputs")
    rules = {
        str(rule.get("name") or "").strip(): rule
        for rule in (raw_rules if isinstance(raw_rules, list) else [])
        if isinstance(rule, dict) and str(rule.get("name") or "").strip()
    }
    inputs = {
        str(item.get("name") or "").strip(): item
        for item in (raw_inputs if isinstance(raw_inputs, list) else [])
        if isinstance(item, dict) and str(item.get("name") or "").strip()
    }
    issues: list[str] = []
    for expected in contract.surfaces:
        actual_rule = rules.get(expected.name)
        actual = (
            _existing_target_surface_contract(actual_rule)
            if isinstance(actual_rule, dict)
            else None
        )
        if actual == expected:
            continue
        issues.append(
            "[existing-target-oracle-contract] Replacement must retain valid "
            f"exact-oracle-mapped surface `{contract.target}#{expected.name}` "
            "with its existing kind/entity/dtype/period/unit/index and "
            "metadata.private/public contract. Repair its implementation under "
            "that stable surface."
        )
    for expected in contract.inputs:
        actual_item = inputs.get(expected.name)
        actual = (
            _existing_target_input_contract(actual_item)
            if isinstance(actual_item, dict)
            else None
        )
        if actual == expected:
            continue
        issues.append(
            "[existing-target-oracle-contract] Replacement must retain valid "
            f"explicit input `{contract.target}#input.{expected.name}` with its "
            "existing entity/dtype/period/unit contract because an exact-oracle-"
            "mapped surface depends on it. Invalid legacy inputs are not covered."
        )
    mapped_names = {surface.name for surface in contract.surfaces}
    if contract.replacement_name_identity:
        for name, rule in sorted(rules.items()):
            if name in mapped_names:
                continue
            kind = str(rule.get("kind") or "").strip().lower()
            if kind not in {
                "parameter",
                "derived",
                "derived_relation",
                "data_relation",
            }:
                continue
            if not _rule_name_contains_token_sequence(
                name,
                contract.replacement_name_identity,
            ):
                continue
            issues.append(
                "[existing-target-naming-contract] New replacement helper "
                f"`{name}` repeats target-path year/legal-source identity "
                f"`{contract.replacement_name_identity}`. The file path already "
                "supplies that identity; use a concise semantic helper name. "
                "Only exact-oracle-mapped legacy surface names listed by the "
                "replacement contract may retain this prefix."
            )
    return issues


def find_upstream_placement_issues(
    content: str,
    *,
    rules_file: Path | None = None,
    source_metadata: dict[str, object] | None = None,
    rulespec_dependency_roots: Iterable[Path] | None = None,
) -> list[str]:
    """Flag rules encoded downstream of their canonical legal authority."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    issues: list[str] = []
    issues.extend(_find_rule_metadata_schema_issues(rules))
    issues.extend(
        _find_source_metadata_upstream_issues(
            rules=rules,
            source_metadata=source_metadata,
        )
    )
    issues.extend(_find_restatement_executable_copy_issues(rules, source_metadata))
    issues.extend(
        _find_duplicate_upstream_executable_issues(
            rules=rules,
            rules_file=rules_file,
            rulespec_dependency_roots=rulespec_dependency_roots,
        )
    )
    return issues


_SOURCE_METADATA_RESTATEMENT_RELATIONS = {
    "restate",
    "restates",
    "restated",
    "copy",
    "copies",
    "copied",
}
_SOURCE_METADATA_DECLARATIVE_RELATIONS = {
    "sets": "sets",
    "set": "sets",
    "amends": "amends",
    "amend": "amends",
    "amended": "amends",
    "implements": "implements",
    "implement": "implements",
    "implemented": "implements",
}
_RULE_METADATA_TARGET_KEYS = ("defines", "delegates", "implements", "sets", "amends")


def _find_rule_metadata_schema_issues(rules: list[Any]) -> list[str]:
    """Reject source-relation metadata on executable RuleSpec rules."""
    issues: list[str] = []
    for rule in rules:
        if not isinstance(rule, dict):
            continue

        metadata = rule.get("metadata")
        if metadata is None:
            continue

        rule_name = str(rule.get("name") or "<unnamed>").strip() or "<unnamed>"
        if not isinstance(metadata, dict):
            issues.append(
                f"RuleSpec relation metadata malformed: rule `{rule_name}` metadata "
                "must be a mapping."
            )
            continue

        relation_keys = [
            key
            for key in ("source_relation", *_RULE_METADATA_TARGET_KEYS)
            if key in metadata
        ]
        if relation_keys:
            keys = ", ".join(f"`metadata.{key}`" for key in relation_keys)
            issues.append(
                f"RuleSpec source-relation metadata is not allowed on executable "
                f"rule `{rule_name}`: {keys}. Encode legal/provenance edges as "
                "separate `kind: source_relation` records."
            )
            continue

        if str(metadata.get("concept_id") or "").strip():
            issues.append(
                f"RuleSpec relation metadata has placeholder target: rule "
                f"`{rule_name}` declares `metadata.concept_id`; use an absolute "
                "RuleSpec or corpus target in a separate `kind: source_relation` "
                "record instead."
            )

    return issues


def _find_source_metadata_upstream_issues(
    *,
    rules: list[Any],
    source_metadata: dict[str, object] | None,
) -> list[str]:
    """Enforce generic upstream/source relations from structured source metadata."""
    issues: list[str] = []
    for relation, target in _iter_source_metadata_target_relations(source_metadata):
        if relation in _SOURCE_METADATA_RESTATEMENT_RELATIONS:
            if _rules_include_source_relation_target(
                rules,
                target,
                relation_type="restates",
            ):
                continue
            issues.append(
                "Source metadata upstream relation requires source_relation: "
                f"source metadata says this source `{relation}` `{target}`, so "
                "encode it as `kind: source_relation` with "
                "`source_relation.type: restates` and `source_relation.target` "
                "instead of redefining executable policy locally."
            )
            continue

        metadata_key = _SOURCE_METADATA_DECLARATIVE_RELATIONS.get(relation)
        if metadata_key is None:
            continue
        if _rules_include_source_relation_target(
            rules,
            target,
            relation_type=metadata_key,
        ):
            continue
        issues.append(
            "Source metadata upstream relation not recorded: "
            f"source metadata says this source `{relation}` `{target}`, so "
            "the corresponding RuleSpec file must include a "
            f"`kind: source_relation` record with `source_relation.type: {metadata_key}` "
            f"and `source_relation.target: {target}`."
        )
    return issues


def _iter_source_metadata_target_relations(
    source_metadata: dict[str, object] | None,
) -> Iterable[tuple[str, str]]:
    if not isinstance(source_metadata, dict):
        return

    relations = source_metadata.get("relations")
    if not isinstance(relations, list):
        return

    for relation in relations:
        if not isinstance(relation, dict):
            continue
        relation_name = str(relation.get("relation") or "").strip().lower()
        target = _normalize_relation_target(relation.get("target"))
        if relation_name and target:
            yield relation_name, target


def _rules_include_source_relation_target(
    rules: list[Any],
    target: str,
    *,
    relation_type: str,
) -> bool:
    return any(
        isinstance(rule, dict)
        and str(rule.get("kind") or "").lower() == "source_relation"
        and isinstance(rule.get("source_relation"), dict)
        and str(rule["source_relation"].get("type") or "").strip().lower()
        == relation_type
        and _target_matches(
            _normalize_relation_target(rule["source_relation"].get("target")),
            target,
        )
        for rule in rules
    )


def _normalize_relation_target(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = value.strip().strip('"').strip("'")
    if not normalized:
        return None
    base, separator, symbol = normalized.partition("#")
    if base.endswith(RULESPEC_FILE_SUFFIX):
        base = str(Path(base).with_suffix(""))
        base = str(Path(base).with_suffix(""))
    return f"{base}{separator}{symbol}" if separator else base


def _target_matches(left: str | None, right: str | None) -> bool:
    if left is None or right is None:
        return False
    return _normalize_relation_target(left) == _normalize_relation_target(right)


def _find_restatement_executable_copy_issues(
    rules: list[Any],
    source_metadata: dict[str, object] | None,
) -> list[str]:
    """Reject local executable rules that copy explicitly restated targets."""
    restated_symbols: dict[str, str] = {}
    for relation, target in _iter_source_metadata_target_relations(source_metadata):
        if relation not in _SOURCE_METADATA_RESTATEMENT_RELATIONS:
            continue
        symbol = _target_symbol(target)
        if symbol is not None:
            restated_symbols.setdefault(symbol, target)

    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("kind") or "").strip().lower() != "source_relation":
            continue
        source_relation = rule.get("source_relation")
        if not isinstance(source_relation, dict):
            continue
        if str(source_relation.get("type") or "").strip().lower() != "restates":
            continue
        target = _normalize_relation_target(source_relation.get("target"))
        if target is None:
            continue
        symbol = _target_symbol(target)
        if symbol is not None:
            restated_symbols.setdefault(symbol, target)
        verification = rule.get("verification")
        if isinstance(verification, dict) and isinstance(
            verification.get("values"), dict
        ):
            for value_name in verification["values"]:
                restated_symbols.setdefault(str(value_name), target)

    issues: list[str] = []
    for rule in rules:
        if not _is_executable_rulespec_rule(rule):
            continue
        name = _rulespec_rule_name(rule)
        target = restated_symbols.get(name)
        if target is None:
            continue
        issues.append(
            "Restated upstream target copied as executable RuleSpec: "
            f"`{name}` duplicates `{target}`. Remove the local executable rule "
            "and keep only an import or a non-executable `kind: source_relation` "
            "record with verification if the downstream source restates it."
        )
    return issues


@dataclass(frozen=True)
class _IndexedExecutableRule:
    """Executable RuleSpec rule discovered in a local rule repository."""

    target: str
    symbol: str
    signature: str
    source_file: str


def _find_duplicate_upstream_executable_issues(
    *,
    rules: list[Any],
    rules_file: Path | None,
    rulespec_dependency_roots: Iterable[Path] | None,
) -> list[str]:
    """Reject copied executable rules when an upstream RuleSpec target exists."""
    if rules_file is None:
        return []

    repo_root = _rulespec_repo_root(rules_file)
    if repo_root is None:
        return []

    prefix = _rulespec_repo_prefix(repo_root)
    current_file = Path(rules_file).resolve()
    candidate_roots = _candidate_upstream_rulespec_roots(
        repo_root,
        rulespec_dependency_roots=rulespec_dependency_roots,
    )
    index = _rulespec_executable_index_for_roots(
        tuple(str(root.resolve()) for root in candidate_roots)
    )
    if not index:
        return []

    issues: list[str] = []
    for rule in rules:
        if not _is_executable_rulespec_rule(rule):
            continue
        signature = _rulespec_executable_signature(rule)
        if signature is None:
            continue
        name = _rulespec_rule_name(rule)
        current_target = _canonical_rulespec_target(
            prefix=prefix,
            repo_root=repo_root,
            rules_file=current_file,
            symbol=name,
        )
        for candidate in index:
            if candidate.symbol != name or candidate.signature != signature:
                continue
            if candidate.target == current_target:
                continue
            if _rulespec_targets_are_equivalent(candidate.target, current_target):
                continue
            if Path(candidate.source_file).resolve() == current_file:
                continue
            if _rulespec_target_is_descendant_of(current_target, candidate.target):
                continue
            issues.append(
                "Upstream placement violation: "
                f"executable rule `{name}` duplicates existing RuleSpec target "
                f"`{candidate.target}`. Remove the local executable copy and "
                "use an import, or encode only a non-executable "
                "`kind: source_relation` record if this source restates the "
                "upstream rule."
            )
            break
    return issues


def _rulespec_target_is_descendant_of(target: str, ancestor: str) -> bool:
    """Return whether a RuleSpec target is a more-specific path under ancestor."""
    target_base = _canonical_rulespec_target_identity_base(target)
    ancestor_base = _canonical_rulespec_target_identity_base(ancestor)
    return (
        target_base is not None
        and ancestor_base is not None
        and target_base.startswith(f"{ancestor_base}/")
    )


def _rulespec_targets_are_equivalent(left: str, right: str) -> bool:
    left_base = _canonical_rulespec_target_identity_base(left)
    right_base = _canonical_rulespec_target_identity_base(right)
    return (
        left_base is not None
        and right_base is not None
        and left_base == right_base
        and _target_symbol(left) == _target_symbol(right)
    )


def _canonical_rulespec_target_identity_base(target: str) -> str | None:
    """Return one canonical ``jurisdiction:path`` target for comparison."""

    target_ref = _parse_rulespec_target(target)
    if target_ref is None:
        return None
    relative = target_ref.relative_path.with_suffix("").as_posix()
    return f"{target_ref.prefix}:{relative}"


def _rulespec_repo_root(rules_file: Path) -> Path | None:
    """Return the canonical jurisdiction content root holding ``rules_file``."""

    return find_policy_repo_root(Path(rules_file))


def _rulespec_repo_prefix(repo_root: Path) -> str:
    return jurisdiction_prefix(repo_root)


def _candidate_upstream_rulespec_roots(
    repo_root: Path,
    *,
    rulespec_dependency_roots: Iterable[Path] | None = None,
) -> tuple[Path, ...]:
    """Return upstream roots from the active and explicit dependency checkouts."""
    roots: list[Path] = []

    def add(candidate: Path) -> None:
        if candidate.exists() and candidate.is_dir():
            roots.append(candidate)

    add(repo_root)
    checkout_roots: list[Path] = []
    dependency_roots = _effective_rulespec_dependency_roots(rulespec_dependency_roots)
    if canonical_rulespec_root_identity(repo_root) is not None:
        checkout_roots.append(repo_root.parent)
        dependency_roots = _rulespec_dependencies_for_active_root(
            repo_root,
            dependency_roots,
        )
    checkout_roots.extend(dependency_roots)
    prefix_parts = _rulespec_repo_prefix(repo_root).split("-")
    for length in range(len(prefix_parts) - 1, 0, -1):
        ancestor_prefix = "-".join(prefix_parts[:length])
        for checkout_root in checkout_roots:
            for candidate in candidate_jurisdiction_content_dirs(
                checkout_root, ancestor_prefix
            ):
                add(candidate)

    unique: list[Path] = []
    seen: set[Path] = set()
    for root in roots:
        resolved = root.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        unique.append(root)
    return tuple(unique)


@functools.lru_cache(maxsize=64)
def _rulespec_executable_index_for_roots(
    root_paths: tuple[str, ...],
) -> tuple[_IndexedExecutableRule, ...]:
    records: list[_IndexedExecutableRule] = []
    for root_path in root_paths:
        root = Path(root_path)
        if not root.exists():
            continue
        prefix = _rulespec_repo_prefix(root)
        for source_root_name in sorted(RULESPEC_ATOMIC_MODULE_ROOTS):
            source_root = validate_rulespec_context_directory(
                root / source_root_name,
                root,
            )
            if source_root is None:
                continue
            for rules_file in sorted(source_root.rglob("*.yaml")):
                if rules_file.name.endswith(".test.yaml"):
                    continue
                try:
                    payload = yaml.safe_load(rules_file.read_text())
                except (OSError, yaml.YAMLError, ValueError):
                    continue
                if (
                    not isinstance(payload, dict)
                    or payload.get("format") != "rulespec/v1"
                ):
                    continue
                rules = payload.get("rules")
                if not isinstance(rules, list):
                    continue
                for rule in rules:
                    if not _is_executable_rulespec_rule(rule):
                        continue
                    signature = _rulespec_executable_signature(rule)
                    if signature is None:
                        continue
                    symbol = _rulespec_rule_name(rule)
                    records.append(
                        _IndexedExecutableRule(
                            target=_canonical_rulespec_target(
                                prefix=prefix,
                                repo_root=root,
                                rules_file=rules_file,
                                symbol=symbol,
                            ),
                            symbol=symbol,
                            signature=signature,
                            source_file=str(rules_file.resolve()),
                        )
                    )
    return tuple(records)


def _is_executable_rulespec_rule(rule: Any) -> bool:
    if not isinstance(rule, dict):
        return False
    return str(rule.get("kind") or "").strip().lower() in {
        "parameter",
        "derived",
        "derived_relation",
    }


def _has_module_source_locator(payload: dict[str, Any]) -> bool:
    module = payload.get("module")
    if not isinstance(module, dict):
        return False
    source_verification = module.get("source_verification")
    if not isinstance(source_verification, dict):
        return False
    citation_path = source_verification.get("corpus_citation_path")
    return isinstance(citation_path, str) and bool(citation_path.strip())


def find_rule_source_metadata_issues(content: str) -> list[str]:
    """Require source metadata for executable RuleSpec records."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    executable_rules = [rule for rule in rules if _is_executable_rulespec_rule(rule)]
    if not executable_rules:
        return []

    issues: list[str] = []
    if not _has_module_source_locator(payload):
        issues.append(
            "Rule source locator required: module.source_verification must include "
            "exactly one `corpus_citation_path` when executable rules are present."
        )

    for rule in executable_rules:
        name = _rulespec_rule_name(rule)
        if not rule.get("source"):
            issues.append(
                "Rule source metadata required: "
                f"`{name}` is an executable rule and must include `source:` "
                "with the legal citation/span supporting it."
            )

    return issues


def _rulespec_rule_name(rule: dict[str, Any]) -> str:
    return str(rule.get("name") or "<unknown>").strip() or "<unknown>"


def _canonical_rulespec_target(
    *,
    prefix: str,
    repo_root: Path,
    rules_file: Path,
    symbol: str,
) -> str:
    relative = rules_file.resolve().relative_to(repo_root.resolve())
    if relative.suffix == RULESPEC_FILE_SUFFIX:
        relative = relative.with_suffix("")
    if not relative.parts or relative.parts[0] not in RULESPEC_ATOMIC_MODULE_ROOTS:
        raise ValueError(
            "RuleSpec target must be beneath a canonical content root "
            f"in the canonical jurisdiction root: {rules_file}"
        )
    return f"{prefix}:{relative.as_posix()}#{symbol}"


def _canonical_rulespec_file_target(
    *,
    policy_repo_path: Path | None,
    rules_file: Path,
    symbol: str,
) -> str | None:
    repo_root: Path | None
    if policy_repo_path is not None and is_jurisdiction_content_root(
        Path(policy_repo_path)
    ):
        repo_root = Path(policy_repo_path)
        # The direct jurisdiction directory is the canonical target anchor.
        walked_root = _rulespec_repo_root(rules_file)
        if walked_root is not None:
            try:
                walked_root.relative_to(repo_root.resolve())
            except ValueError:
                pass
            else:
                repo_root = walked_root
    else:
        repo_root = _rulespec_repo_root(rules_file)
    if repo_root is None:
        return None
    try:
        return _canonical_rulespec_target(
            prefix=_rulespec_repo_prefix(repo_root),
            repo_root=repo_root,
            rules_file=rules_file,
            symbol=symbol,
        )
    except ValueError:
        return None


def _strict_rules_repo_layout_checks_enabled(
    *,
    policy_repo_path: Path | None,
    rules_file: Path,
) -> bool:
    if policy_repo_path is None:
        return False
    repo_root = Path(policy_repo_path)
    if not is_jurisdiction_content_root(repo_root):
        return False
    try:
        rules_file.resolve().relative_to(repo_root.resolve())
    except ValueError:
        return False
    return True


def find_missing_derived_companion_output_issues(
    content: str,
    cases: list[Any],
    *,
    rules_file: Path,
    policy_repo_path: Path | None = None,
) -> list[str]:
    """Require companion tests to assert every local derived output."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    covered_outputs: set[str] = set()
    for case in cases:
        if not isinstance(case, dict):
            continue
        outputs = case.get("output")
        if isinstance(outputs, dict):
            covered_outputs.update(str(name) for name in outputs)

    issues: list[str] = []
    for rule in rules:
        if not isinstance(rule, dict) or rule.get("kind") != "derived":
            continue
        name = _rulespec_rule_name(rule)
        target = _canonical_rulespec_file_target(
            policy_repo_path=policy_repo_path,
            rules_file=rules_file,
            symbol=name,
        )
        if target is None or target in covered_outputs:
            continue
        issues.append(
            "Derived rule missing companion output coverage: "
            f"`{target}` is not asserted by the companion `.test.yaml` file."
        )

    return issues


def find_judgment_positive_companion_output_issues(
    content: str,
    cases: list[Any],
    *,
    rules_file: Path,
    policy_repo_path: Path | None = None,
) -> list[str]:
    """Require local Judgment outputs to have at least one positive case."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return []

    positive_outputs: set[str] = set()
    positive_fragments: set[str] = set()
    for case in cases:
        if not isinstance(case, dict):
            continue
        outputs = case.get("output")
        if not isinstance(outputs, dict):
            continue
        for key, value in outputs.items():
            if not _is_positive_judgment_value(value):
                continue
            key_text = str(key).strip()
            positive_outputs.add(key_text)
            positive_fragments.add(_test_reference_fragment(key_text))

    issues: list[str] = []
    for rule in rules:
        if not isinstance(rule, dict) or rule.get("kind") != "derived":
            continue
        if str(rule.get("dtype") or "").strip().lower() != "judgment":
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list) or not any(
            isinstance(version, dict)
            and isinstance(version.get("formula"), str)
            and version["formula"].strip()
            for version in versions
        ):
            continue
        if _rule_versions_are_constant_false(versions):
            continue
        name = _rulespec_rule_name(rule)
        target = _canonical_rulespec_file_target(
            policy_repo_path=policy_repo_path,
            rules_file=rules_file,
            symbol=name,
        )
        if target is None:
            continue
        if target in positive_outputs or name in positive_fragments:
            continue
        issues.append(
            "Judgment rule missing positive companion output coverage: "
            f"`{target}` is not asserted as `holds` by the companion "
            "`.test.yaml` file."
        )

    return issues


_SYNTHETIC_SOURCE_AUTHORIZED_INPUT_PATTERN = re.compile(
    r"(?:^|_)source_authorized(?:_|$)"
)


def find_synthetic_source_authorized_input_issues(content: str) -> list[str]:
    """Reject local inputs that let tests invent source authorization.

    These inputs usually appear when a source-stated prohibition is encoded as a
    positive entitlement gated by a caller-supplied escape hatch, e.g. a source
    says a county is not entitled to a postponement but the formula depends on
    ``county_has_source_authorized_postponement_entitlement``.
    """
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []

    local_symbols = _rulespec_executable_names_from_payload(payload)
    local_symbols.update(_rulespec_data_relation_names(payload))
    local_symbols.update(_rulespec_import_symbol_names(payload))

    issues: list[str] = []
    seen: set[tuple[str, str]] = set()
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return issues
    for rule in rules:
        if not isinstance(rule, dict) or rule.get("kind") != "derived":
            continue
        rule_name = _rulespec_rule_name(rule)
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            for identifier in sorted(_formula_local_identifiers(formula)):
                if identifier in local_symbols:
                    continue
                if not _SYNTHETIC_SOURCE_AUTHORIZED_INPUT_PATTERN.search(identifier):
                    continue
                key = (rule_name, identifier)
                if key in seen:
                    continue
                seen.add(key)
                issues.append(
                    "Synthetic source-authorized local input: "
                    f"`{rule_name}` depends on local input `{identifier}`. "
                    "Encode the source-stated authorization, prohibition, or "
                    "entitlement directly, or import a source-backed upstream "
                    "authorization rule; do not let tests supply a "
                    "`source_authorized` escape hatch."
                )
    return issues


def _rule_versions_are_constant_false(versions: list[Any]) -> bool:
    formulas = [
        str(version.get("formula") or "").strip()
        for version in versions
        if isinstance(version, dict) and isinstance(version.get("formula"), str)
    ]
    return bool(formulas) and all(
        _formula_is_syntactically_unsatisfiable_false(formula) for formula in formulas
    )


def _formula_is_syntactically_unsatisfiable_false(formula: str) -> bool:
    if not _rulespec_expression_nesting_within_limit(formula):
        return False

    pending = [formula]
    while pending:
        exact = _strip_balanced_outer_parentheses(pending.pop().strip())
        if exact in {"false", "False"}:
            return True
        literal_comparison = _literal_comparison_truth_value(exact)
        if literal_comparison is not None:
            if not literal_comparison:
                return True
            continue
        if len(_split_top_level_boolean_operator(exact, "or")) > 1:
            continue
        conjuncts = _split_top_level_boolean_operator(exact, "and")
        if len(conjuncts) > 1:
            pending.extend(conjuncts)
    return False


def _literal_comparison_truth_value(expression: str) -> bool | None:
    """Evaluate one comparison using RuleSpec literal and operator semantics."""

    split = _split_rulespec_literal_comparison(expression)
    if split is None:
        return None
    left_text, operator, right_text = split
    left = _rulespec_literal_value(left_text)
    right = _rulespec_literal_value(right_text)
    if left is None or right is None:
        return None
    left_kind, left_value = left
    right_kind, right_value = right

    if left_kind in {"integer", "decimal"} and right_kind in {
        "integer",
        "decimal",
    }:
        left_value = Decimal(left_value)
        right_value = Decimal(right_value)
    elif left_kind == right_kind and left_kind in {"boolean", "text"}:
        if operator not in {"==", "!="}:
            return None
    else:
        return None

    if operator == "==":
        return left_value == right_value
    if operator == "!=":
        return left_value != right_value
    if operator == "<":
        return left_value < right_value
    if operator == "<=":
        return left_value <= right_value
    if operator == ">":
        return left_value > right_value
    if operator == ">=":
        return left_value >= right_value
    return None


def _split_rulespec_literal_comparison(
    expression: str,
) -> tuple[str, str, str] | None:
    """Split exactly one top-level RuleSpec comparison outside quoted text."""

    operators: list[tuple[int, str]] = []
    depth = 0
    quote: str | None = None
    escaped = False
    index = 0
    while index < len(expression):
        char = expression[index]
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
            index += 1
            continue
        if char in {'"', "'"}:
            quote = char
            index += 1
            continue
        if char == "(":
            depth += 1
            index += 1
            continue
        if char == ")":
            depth -= 1
            if depth < 0:
                return None
            index += 1
            continue
        if depth == 0:
            operator = next(
                (
                    candidate
                    for candidate in ("<=", ">=", "==", "!=", "<", ">")
                    if expression.startswith(candidate, index)
                ),
                None,
            )
            if operator is not None:
                operators.append((index, operator))
                index += len(operator)
                continue
        index += 1
    if quote is not None or depth != 0 or len(operators) != 1:
        return None
    operator_index, operator = operators[0]
    left = expression[:operator_index].strip()
    right = expression[operator_index + len(operator) :].strip()
    if not left or not right:
        return None
    return left, operator, right


def _rulespec_literal_value(
    expression: str,
) -> tuple[str, bool | int | Decimal | str] | None:
    """Parse the literal subset accepted by the RuleSpec formula lexer."""

    literal = _strip_balanced_outer_parentheses(expression.strip())
    if literal in {"true", "True"}:
        return "boolean", True
    if literal in {"false", "False"}:
        return "boolean", False

    if re.fullmatch(r"-?[0-9][0-9_]*", literal):
        exact = literal.replace("_", "")
        magnitude = exact.removeprefix("-").lstrip("0") or "0"
        if len(magnitude) > 19:
            return None
        unsigned_value = int(magnitude)
        if unsigned_value > 2**63 - 1:
            return None
        value = -unsigned_value if exact.startswith("-") else unsigned_value
        return "integer", value

    if re.fullmatch(r"-?[0-9][0-9_]*\.[0-9][0-9_]*", literal):
        exact = literal.replace("_", "")
        unsigned = exact.removeprefix("-")
        whole, fractional = unsigned.split(".", 1)
        coefficient_text = f"{whole}{fractional}".lstrip("0") or "0"
        if len(fractional) > 28 or len(coefficient_text) > 29:
            return None
        coefficient = int(coefficient_text)
        if coefficient > 2**96 - 1:
            return None
        try:
            return "decimal", Decimal(exact)
        except InvalidOperation:
            return None

    if len(literal) < 2 or literal[0] not in {'"', "'"}:
        return None
    quote = literal[0]
    if literal[-1] != quote:
        return None
    value: list[str] = []
    index = 1
    while index < len(literal) - 1:
        char = literal[index]
        if char == quote:
            return None
        if char != "\\":
            value.append(char)
            index += 1
            continue
        if index + 1 >= len(literal) - 1:
            return None
        escaped = literal[index + 1]
        value.append(
            {
                "\\": "\\",
                '"': '"',
                "'": "'",
                "n": "\n",
                "r": "\r",
                "t": "\t",
            }.get(escaped, escaped)
        )
        index += 2
    return "text", "".join(value)


def _strip_balanced_outer_parentheses(expression: str) -> str:
    stripped = expression.strip()
    if not stripped.startswith("(") or not stripped.endswith(")"):
        return stripped

    matching_parentheses: dict[int, int] = {}
    opening_parentheses: list[int] = []
    quote: str | None = None
    escaped = False
    for index, char in enumerate(stripped):
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
            continue
        if char in {'"', "'"}:
            quote = char
            continue
        if char == "(":
            opening_parentheses.append(index)
            continue
        if char != ")":
            continue
        if not opening_parentheses:
            return stripped
        matching_parentheses[opening_parentheses.pop()] = index
    if quote is not None or opening_parentheses:
        return stripped

    start = 0
    end = len(stripped) - 1
    while start < end and matching_parentheses.get(start) == end:
        start += 1
        end -= 1
        while start <= end and stripped[start].isspace():
            start += 1
        while end >= start and stripped[end].isspace():
            end -= 1
    return stripped[start : end + 1]


def _rulespec_expression_nesting_within_limit(
    expression: str,
    *,
    max_depth: int = 256,
) -> bool:
    """Bound heuristic-only parsing and reject malformed delimiters safely."""

    depth = 0
    quote: str | None = None
    escaped = False
    for char in expression:
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
            continue
        if char in {'"', "'"}:
            quote = char
            continue
        if char == "(":
            depth += 1
            if depth > max_depth:
                return False
        elif char == ")":
            depth -= 1
            if depth < 0:
                return False
    return quote is None and depth == 0


def _split_top_level_boolean_operator(expression: str, operator: str) -> list[str]:
    parts: list[str] = []
    depth = 0
    quote: str | None = None
    escaped = False
    start = 0
    index = 0
    pattern = re.compile(rf"\b{re.escape(operator)}\b")
    while index < len(expression):
        char = expression[index]
        if quote is not None:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
            index += 1
            continue
        if char in {'"', "'"}:
            quote = char
            index += 1
            continue
        if char == "(":
            depth += 1
            index += 1
            continue
        if char == ")":
            depth = max(depth - 1, 0)
            index += 1
            continue
        if depth == 0:
            match = pattern.match(expression, index)
            if match is not None:
                parts.append(expression[start:index].strip())
                start = match.end()
                index = match.end()
                continue
        index += 1
    parts.append(expression[start:].strip())
    return [part for part in parts if part]


def _rulespec_executable_signature(rule: dict[str, Any]) -> str | None:
    versions = rule.get("versions")
    if not isinstance(versions, list):
        return None

    normalized_versions: list[dict[str, Any]] = []
    substantive = False
    for version in versions:
        if not isinstance(version, dict):
            continue
        normalized_version: dict[str, Any] = {}
        for key in ("effective_from", "from", "effective_to", "to"):
            if key in version:
                normalized_version[key] = _canonical_yaml_value(version.get(key))
        values = version.get("values")
        if isinstance(values, dict) and values:
            normalized_version["values"] = _canonical_yaml_value(values)
            substantive = True
        else:
            formula = version.get("formula")
            if isinstance(formula, str) and formula.strip():
                normalized_formula = _normalize_formula_signature(formula)
                normalized_version["formula"] = normalized_formula
                if _formula_signature_is_substantive(normalized_formula):
                    substantive = True
        if "values" in normalized_version or "formula" in normalized_version:
            normalized_versions.append(normalized_version)

    if not normalized_versions or not substantive:
        return None

    payload = {
        "kind": str(rule.get("kind") or "").strip().lower(),
        "dtype": str(rule.get("dtype") or "").strip(),
        "period": str(rule.get("period") or "").strip(),
        "unit": str(rule.get("unit") or "").strip(),
        "indexed_by": str(rule.get("indexed_by") or "").strip(),
        "versions": normalized_versions,
    }
    return json.dumps(payload, sort_keys=True, separators=(",", ":"))


def _normalize_formula_signature(formula: str) -> str:
    return re.sub(r"\s+", " ", formula.strip())


def _formula_signature_is_substantive(formula: str) -> bool:
    numeric = _numeric_rule_value(formula)
    if numeric is not None:
        value = numeric[1]
        return not (float(value).is_integer() and int(value) in {-1, 0, 1, 2, 3})
    if re.fullmatch(r"[A-Za-z_][\w.]*", formula):
        return False
    return True


def _canonical_yaml_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            str(key): _canonical_yaml_value(value[key])
            for key in sorted(value, key=lambda item: str(item))
        }
    if isinstance(value, list):
        return [_canonical_yaml_value(item) for item in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def _target_symbol(target: str | None) -> str | None:
    if not target:
        return None
    _, separator, symbol = target.partition("#")
    if not separator:
        return None
    symbol = symbol.strip()
    return symbol or None


def find_source_verification_issues(
    content: str,
    *,
    source_texts: dict[str, str] | None = None,
) -> list[str]:
    """Validate declared RuleSpec values against an ingested corpus source page."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict) or payload.get("format") != "rulespec/v1":
        return []

    plural_issues = find_plural_corpus_citation_path_issues(payload)
    if plural_issues:
        return plural_issues

    source_verification = _source_verification_block(payload)
    if source_verification is None:
        return []

    citation_paths, source_label = _source_verification_source_fields(
        source_verification
    )
    expected_values = source_verification.get("values")
    if not citation_paths:
        return ["Source verification source required: missing `corpus_citation_path`."]
    if not isinstance(expected_values, dict) or not expected_values:
        if expected_values is not None:
            return [
                "Source verification values invalid: "
                "`source_verification.values` must be a non-empty mapping when present."
            ]
        expected_values = {}

    rulespec_values, _, load_issue = _extract_rulespec_parameter_values(payload)
    if load_issue is not None:
        return [f"Source verification RuleSpec invalid: {load_issue}"]

    issues: list[str] = []
    for value_name, expected_value in expected_values.items():
        value_key = str(value_name)
        if value_key not in rulespec_values:
            issues.append(
                "Source verification RuleSpec value missing: "
                f"`{value_key}` is declared for source verification but is not "
                "defined as a scalar/table parameter."
            )
            continue
        issues.extend(
            _compare_source_verification_expected_value(
                value_name=value_key,
                expected_value=expected_value,
                rulespec_value=rulespec_values[value_key],
            )
        )

    source_text = _source_verification_text(
        citation_paths=citation_paths,
        source_label=source_label,
        source_texts=source_texts,
    )
    if source_text is None:
        issues.append(
            "Source verification source missing: "
            + f"{_format_source_verification_paths(citation_paths)} "
            "was not found in corpus.provisions."
        )
        return issues
    if not expected_values:
        return issues

    for value_name, expected_value in expected_values.items():
        value_key = str(value_name)
        issues.extend(
            _find_source_text_value_issues(
                source_label=source_label,
                source_text=source_text,
                value_name=value_key,
                expected_value=expected_value,
            )
        )

    return issues


_COST_AVAILABILITY_SOURCE_PATTERN = re.compile(
    r"\b(available|allowed|eligible|entitled)\b.{0,180}"
    r"\b(billed|cost|costs|expense|expenses|incur|incurs|incurred)\b"
    r"|"
    r"\b(billed|cost|costs|expense|expenses|incur|incurs|incurred)\b"
    r".{0,180}\b(available|allowed|eligible|entitled)\b",
    flags=re.IGNORECASE | re.DOTALL,
)


def find_source_condition_coverage_issues(
    content: str,
    *,
    source_texts: dict[str, str] | None = None,
) -> list[str]:
    """Flag eligibility formulas that collapse cost availability to only exclusions."""
    try:
        payload = yaml.safe_load(content)
    except (yaml.YAMLError, ValueError):
        return []
    if not isinstance(payload, dict):
        return []

    source_verification = _source_verification_block(payload)
    if source_verification is None:
        return []
    citation_paths, source_label = _source_verification_source_fields(
        source_verification
    )
    source_text = extract_embedded_source_text(content) or _source_verification_text(
        citation_paths=citation_paths,
        source_label=source_label,
        source_texts=source_texts,
    )
    if not source_text or not _COST_AVAILABILITY_SOURCE_PATTERN.search(source_text):
        return []

    issues: list[str] = []
    rules = payload.get("rules")
    if not isinstance(rules, list):
        return issues
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        kind = str(rule.get("kind") or "").strip().lower()
        if kind != "derived":
            continue
        name = str(rule.get("name") or "").strip()
        normalized_name = name.lower()
        if not any(
            token in normalized_name
            for token in ("eligible", "available", "allowance", "applies")
        ):
            continue
        dtype = str(rule.get("dtype") or "").strip().lower()
        if dtype not in {"judgment", "boolean", "bool"}:
            continue
        versions = rule.get("versions")
        if not isinstance(versions, list):
            continue
        for version in versions:
            if not isinstance(version, dict):
                continue
            formula = version.get("formula")
            if not isinstance(formula, str):
                continue
            identifiers = set(_RULESPEC_IDENTIFIER.findall(formula))
            identifiers -= _RULESPEC_FORMULA_BUILTINS
            if not identifiers:
                continue
            negated = {
                match.group(1)
                for match in re.finditer(r"\bnot\s+([A-Za-z_][A-Za-z0-9_]*)\b", formula)
            }
            if identifiers and identifiers <= negated:
                issues.append(
                    "Source condition coverage missing: "
                    f"`{name}` is grounded in source text that makes cost/expense availability conditional, "
                    "but its formula only negates other predicates. Add a positive fact predicate "
                    "for the source-stated cost, billing, payment, or incurrence condition."
                )
                continue
    return issues


_ANAPHORIC_SCOPE_PHRASE_PATTERN = re.compile(
    r"\b(?P<connector>through|with\s+respect\s+to|in\s+connection\s+with|on)"
    r"\s+such\s+"
    r"(?P<object>account|accounts|instrument|instruments|payment|payments|"
    r"property|properties|contract|contracts|membership|memberships|stock|"
    r"payee|payor|broker|acquisition|transaction|transactions|plan|plans|"
    r"service|services|item|items|year|period|employee|employer|individual|"
    r"child|household|unit)\b",
    flags=re.IGNORECASE,
)
_ANAPHORIC_EVENT_STOPWORDS = frozenset(
    {
        "a",
        "an",
        "and",
        "any",
        "as",
        "be",
        "by",
        "during",
        "for",
        "if",
        "in",
        "is",
        "of",
        "or",
        "such",
        "that",
        "the",
        "to",
        "was",
        "were",
        "which",
        "with",
    }
)
_ANAPHORIC_SCOPE_STOPWORDS = frozenset(
    {
        "a",
        "an",
        "and",
        "in",
        "of",
        "such",
        "the",
        "to",
        "with",
    }
)


def find_anaphoric_scope_omission_issues(
    content: str,
    *,
    source_texts: dict[str, str] | None = None,
) -> list[str]:
    """Flag predicates that drop source-stated same-object scope.

    This catches cases like a proof excerpt for broker activity where the full
    source sentence continues with "through such account", but the generated
    predicate only says the broker acted for the payee generally.
    """
    payload = _rulespec_payload(content)
    if payload is None:
        return []

    source_verification = _source_verification_block(payload)
    if source_verification is None:
        return []
    citation_paths, source_label = _source_verification_source_fields(
        source_verification
    )
    source_text = _source_verification_text(
        citation_paths=citation_paths,
        source_label=source_label,
        source_texts=source_texts,
    )
    if not source_text:
        return []

    issues: list[str] = []
    seen: set[tuple[str, str, str, str]] = set()
    for rule_name, kind, formula, _source, rule in _rulespec_rule_formula_rule_records(
        payload
    ):
        if kind != "derived":
            continue
        identifiers = sorted(_formula_local_identifiers(formula))
        if not identifiers:
            continue
        for excerpt in _rule_proof_source_excerpts(rule):
            scope_phrase = _anaphoric_scope_phrase_for_excerpt(
                source_text=source_text,
                excerpt=excerpt,
            )
            if scope_phrase is None:
                continue
            excerpt_tokens = _anaphoric_event_tokens(excerpt)
            if len(excerpt_tokens) < 3:
                continue
            required_scope_tokens = _anaphoric_scope_tokens(scope_phrase)
            if not required_scope_tokens:
                continue
            required_overlap = min(4, len(excerpt_tokens))
            for identifier in identifiers:
                identifier_tokens = _anaphoric_identifier_tokens(identifier)
                if len(excerpt_tokens & identifier_tokens) < required_overlap:
                    continue
                if required_scope_tokens <= identifier_tokens:
                    continue
                issue_key = (rule_name, excerpt, scope_phrase, identifier)
                if issue_key in seen:
                    continue
                seen.add(issue_key)
                issues.append(
                    "Anaphoric scope omitted: "
                    f"`{rule_name}` uses predicate `{identifier}` for proof excerpt "
                    f"`{excerpt}`, but the supporting source states "
                    f"`{scope_phrase}`. Preserve that same-object relationship in "
                    "the predicate name/formula and companion tests instead of "
                    "broadening the condition."
                )
    return issues


def _anaphoric_scope_phrase_for_excerpt(
    *,
    source_text: str,
    excerpt: str,
) -> str | None:
    excerpt_text = _collapse_source_sentence_text(excerpt)
    if not excerpt_text:
        return None
    if excerpt_match := _ANAPHORIC_SCOPE_PHRASE_PATTERN.search(excerpt_text):
        return _collapse_source_sentence_text(excerpt_match.group(0))

    source = _collapse_source_sentence_text(source_text)
    match = re.search(re.escape(excerpt_text), source, flags=re.IGNORECASE)
    if match is None:
        return None
    tail = source[match.end() : match.end() + 240]
    scope_match = _ANAPHORIC_SCOPE_PHRASE_PATTERN.search(tail)
    if scope_match is None:
        return None

    sentence_boundary = _first_sentence_boundary_index(tail)
    if sentence_boundary is not None and scope_match.start() > sentence_boundary:
        return None
    if _anaphoric_tail_crosses_clause_boundary(tail[: scope_match.start()]):
        return None
    return _collapse_source_sentence_text(scope_match.group(0))


def _collapse_source_sentence_text(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip()


def _first_sentence_boundary_index(value: str) -> int | None:
    indexes = [
        index for marker in (".", ";", "\n") if (index := value.find(marker)) != -1
    ]
    return min(indexes) if indexes else None


def _anaphoric_tail_crosses_clause_boundary(value: str) -> bool:
    return bool(
        re.search(
            r"\([A-Z0-9ivx]+\)|\b(?:then|shall|must|may)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _anaphoric_event_tokens(value: str) -> set[str]:
    return {
        token
        for token in _anaphoric_normalized_tokens(value)
        if token not in _ANAPHORIC_EVENT_STOPWORDS and not token.isdigit()
    }


def _anaphoric_scope_tokens(value: str) -> set[str]:
    return {
        token
        for token in _anaphoric_normalized_tokens(value)
        if token not in _ANAPHORIC_SCOPE_STOPWORDS
    }


def _anaphoric_identifier_tokens(value: str) -> set[str]:
    return {
        token
        for token in _anaphoric_normalized_tokens(value)
        if token not in _ANAPHORIC_EVENT_STOPWORDS
    }


def _anaphoric_normalized_tokens(value: str) -> set[str]:
    tokens: set[str] = set()
    for raw_token in re.findall(r"[A-Za-z0-9]+", value.lower()):
        tokens.add(raw_token)
        if len(raw_token) > 4 and raw_token.endswith("ies"):
            tokens.add(raw_token[:-3] + "y")
        elif len(raw_token) > 3 and raw_token.endswith("s"):
            tokens.add(raw_token[:-1])
    return tokens


